-- ========== VIEW (234) ==========

CREATE VIEW "SBODEMOUS"."AgentAll_BATCHSTOCK" AS
SELECT
  T0."ItemCode",
  T0."ItemName",
  T2."ItmsGrpNam",
  T0."BatchNum",
  T0."WhsCode",
  T3."WhsName" ,
  T0."Quantity" ,
  T0."InDate" ,
  T0."SuppSerial",
  T0."ExpDate",
  T0."PrdDate" ,
  T3."BPLid",
  T4."BPLName"
FROM OIBT T0 
LEFT JOIN OITM T1 ON T0."ItemCode"=T1."ItemCode" 
LEFT JOIN OITB T2 ON T1."ItmsGrpCod" = T2."ItmsGrpCod" 
LEFT JOIN OWHS T3 ON T0."WhsCode" = T3."WhsCode" 
LEFT JOIN OBPL T4 ON T3."BPLid"=T4."BPLId"
INNER JOIN "AgentAll_USERRIGHT"(SESSION_CONTEXT('USERCODE')) TD ON TD.USERID=T0."UserSign"
INNER JOIN "AgentAll_USERBPL"(SESSION_CONTEXT('USERCODE')) TB ON TB.BPLID=IFNULL(T4."BPLId",0)
;

CREATE VIEW "SBODEMOUS"."AgentAll_BOMLIST" AS
SELECT
	 T0."ProductCode",
	 --产品代码
 T0. "ProductName",
	 --产品名称
 T0. "ItemCode",
	 --底层BOM代码
 T0. "ItemName",
	 --底层BOM名称
 T0. "TreeType",
	 --BOM类型代码
 T0. "TreeTypeName",
	 --BOM类型名称
 T0. "WhsCode",
	 --仓库代码
 T1."WhsName",
	 --仓库名称
 T0. "Quantity",
	 --BOM数量
 T0. "AddQuantity",
	 --附加数量
 T0."IssueMthd",
	 --发货方式
 T0. "Father" --父节点代码
 
FROM "AgentAll_BOM_LIST"(1) T0 
LEFT JOIN OWHS T1 ON T1."WhsCode"=T0."WhsCode" 
WHERE "TreeType"='P' 
and "Type"=4
;

CREATE VIEW "SBODEMOUS"."AgentAll_CUSTBAL" AS
SELECT
  T0."ShortName",
  T1."CardName",
  T7."descript" AS "Province",
  T8."descript" AS "Region",
  T1."CardType",
  T4."GroupName",
  T3."SlpName",
  T2."RefDate",
  T2."DueDate",
  T0."TransId" ,
  IFNULL(T0."FCCurrency",T5."MainCurncy") AS "Currency" ,
  CASE WHEN IFNULL(T0."FCCurrency",T5."MainCurncy")=T5."MainCurncy" THEN 'Y' ELSE 'N' END AS "IsLocCurrency",
  CASE WHEN T0."Credit"=0 THEN T0."Debit" ELSE T0."Credit" END AS "Amount" ,
  CASE WHEN T0."BalDueCred"=0 THEN T0."BalDueDeb" ELSE T0."BalDueCred" END AS "BalDue" ,
  CASE WHEN T0."FCCredit"=0 THEN T0."FCDebit" ELSE T0."FCCredit" END AS "FCAmount" ,
  CASE WHEN T0."BalFcCred"=0 THEN T0."BalFcDeb" ELSE T0."BalFcCred" END AS "BalFcDue" ,
  CASE WHEN DAYS_BETWEEN(T2."DueDate", CURRENT_DATE)<0 THEN 'Forward' 
   WHEN DAYS_BETWEEN(T2."DueDate", CURRENT_DATE) BETWEEN 0 AND 30 THEN '0~30' 
   WHEN DAYS_BETWEEN(T2."DueDate", CURRENT_DATE) BETWEEN 31 AND 60 THEN '31~60' 
   WHEN DAYS_BETWEEN(T2."DueDate", CURRENT_DATE) BETWEEN 61 AND 90 THEN '61~90' 
                         WHEN DAYS_BETWEEN(T2."DueDate",CURRENT_DATE) BETWEEN 91 AND 180 THEN '91~180' 
                         WHEN DAYS_BETWEEN(T2."DueDate",CURRENT_DATE) BETWEEN 181 AND 365 THEN '181~365' 
                         WHEN DAYS_BETWEEN(T2."DueDate",CURRENT_DATE) BETWEEN 366 AND 730 THEN '366~730' 
             ELSE '731+' END AS "Aging" ,
  T0."BPLId",
  T6."BPLName"
FROM JDT1 T0 
INNER JOIN OCRD T1 ON T0."ShortName"=T1."CardCode" 
INNER JOIN OJDT T2 ON T0."TransId"=T2."TransId" 
LEFT JOIN OSLP T3 ON T1."SlpCode"=T3."SlpCode" 
LEFT JOIN OCRG T4 ON T1."GroupCode"=T4."GroupCode" 
LEFT JOIN OADM T5 ON 1=1 
LEFT JOIN OBPL T6 ON T0."BPLId"=T6."BPLId"
LEFT JOIN OTER T7 ON T1."Territory"=T7."territryID" 
LEFT JOIN OTER T8 ON T7."parent"=T8."territryID" 
WHERE CASE WHEN T0."BalDueCred"=0 
THEN T0."BalScDeb" 
ELSE T0."BalDueCred" 
END <>0 
AND T1."CardType"='C' 
AND (EXISTS(SELECT 1 FROM OADM WHERE "MltpBrnchs" = 'N')
         OR EXISTS(SELECT 1 
                   FROM "CRD8" TC 
                   INNER JOIN "AgentAll_USERBPL"(SESSION_CONTEXT('USERCODE')) TB 
                       ON TB."BPLID" = IFNULL(TC."BPLId", 0)
                   WHERE TC."CardCode" = T1."CardCode")) ORDER BY T0."ShortName"
;

