         OR EXISTS(SELECT 1 
                   FROM "CRD8" TC 
                   INNER JOIN "AgentAll_USERBPL"(SESSION_CONTEXT('USERCODE')) TB 
                       ON TB."BPLID" = IFNULL(TC."BPLId", 0)
                   WHERE TC."CardCode" = T0."CardCode"))
;

CREATE VIEW "SBODEMOUS"."AgentAll_CUSTCREDIT" AS
SELECT
  T0."CardCode" ,
  T0."CardName",
  T0."CardType",
              T1."GroupName",
              T2."SlpName",
              T3."descript" AS "Province",
  T4."descript" AS "Region",
  T0."CreditLine",
  T0."Currency" ,
  CASE WHEN T0."Currency"=T5."MainCurncy" THEN 'Y' ELSE 'N' END AS "IsLocCurrency",
  T0."OrdersBal",
  T0. "OrderBalFC",
  T0."DNotesBal",
  T0."DNoteBalFC",
  T0."Balance",
  T0."BalanceFC",
  T0."ChecksBalL",
  T0."ChecksBal" 
FROM OCRD T0 
LEFT JOIN OCRG T1 ON T0."GroupCode"=T1."GroupCode" 
LEFT JOIN OSLP T2 ON T0."SlpCode"=T2."SlpCode" 
LEFT JOIN OTER T3 ON T0."Territory"=T3."territryID" 
LEFT JOIN OTER T4 ON T3."parent"=T4."territryID" 
LEFT JOIN OADM T5 ON T0."Currency"=T5."MainCurncy"
WHERE T0."CardType" = 'C' 
  AND (EXISTS(SELECT 1 FROM OADM WHERE "MltpBrnchs" = 'N')
         OR EXISTS(SELECT 1 
                   FROM "CRD8" TC 
                   INNER JOIN "AgentAll_USERBPL"(SESSION_CONTEXT('USERCODE')) TB 
                       ON TB."BPLID" = IFNULL(TC."BPLId", 0)
                   WHERE TC."CardCode" = T0."CardCode"))
;

CREATE VIEW "SBODEMOUS"."AgentAll_Customer" AS
SELECT
  T0."CardCode",
  T0."CardName",
  T0."CardType",
  T0."Currency",
  T0."LicTradNum",
  T0."validFor",
  T2."GroupName",
  T3."SlpName",
  T8."descript" AS "Province",
  T9."descript" AS "Region",
  T0."GTSRegNum",
  T0."GTSBankAct",
  T0."GTSBilAddr",
  T0."ECVatGroup",
  T7."Name" AS "VatName",
  T0."Phone1",
  T0."Phone2",
  T0."E_Mail",
  T0."CntctPrsn",
  T10."Position" ,
  T10."Address" as  "CntAddress",
  T10."Tel1",
  T10."Cellolar",
  T10."E_MailL",
  T0."Address",
  T0."MailAddres" ,
  T4."PymntGroup",
  T5."ListName",
  T0."BankCountr",
  T0."BankCode",
  T6."BankName",
  T0."DflAccount",
  T0."DflSwift",
  T0."DflBranch",
  T0."UseShpdGd",
  T0."ConnBP",
  T11."CardName" AS "ConnBPName",
  T0."FatherType",
  T0."FatherCard",
  T12."CardName" AS "FatherName",
  T0."CreateDate",
  T0."UpdateDate" 
FROM OCRD T0 
LEFT JOIN OCRG T2 ON T0."GroupCode" = T2."GroupCode" AND T0."CardType" = T2."GroupType" 
LEFT JOIN OSLP T3 ON T0."SlpCode" = T3."SlpCode"
LEFT JOIN OCTG T4 ON T0."GroupNum"=T4."GroupNum"
LEFT JOIN OPLN T5 ON T0."ListNum"=T5."ListNum"
LEFT JOIN ODSC T6 ON T0."BankCode"=T6."BankCode"
LEFT JOIN OVTG T7 ON T0."ECVatGroup"=T7."Code"
LEFT JOIN OTER T8 ON T0."Territory"=T8."territryID"
LEFT JOIN OTER T9 ON T8."parent"=T9."territryID"
LEFT JOIN OCPR T10 ON T0."CntctPrsn"=T10."Name" AND T0."CardCode"=T10."CardCode" 
LEFT JOIN OCRD T11 ON T0."ConnBP"=T11."CardCode"
LEFT JOIN OCRD T12 ON T0."FatherCard"=T12."CardCode"
where  T0."CardType"='C'
;

