;

CREATE VIEW "SBODEMOUS"."AgentAll_ITM1" AS
SELECT 
T0."ItemCode",
T2."ItemName",
T3."ItmsGrpNam",
T0."PriceList",
T1."ListName",
T0."Currency",
T0."Price",
T0."Currency1",
T0."AddPrice1",
T0."Currency2",
T0."AddPrice2"
FROM ITM1 T0
LEFT JOIN OPLN T1 ON T0."PriceList"=T1."ListNum"
LEFT JOIN OITM T2 ON T0."ItemCode"=T2."ItemCode"
