;

CREATE VIEW "SBODEMOUS"."AgentAll_JournalEntry" AS
SELECT 
    T0."TransId",
    M0."Number",
    M0."TransType",
    T0."Line_ID", 
    T0."Account",
    T9."AcctName",
    T0."ShortName",
    T11."CardName",
    T11."CardType",
    T0."RefDate", 
    T0."LineMemo",
    T0."Debit", 
    T0."Credit", 
    T0."Debit"-"T0"."Credit" AS "LineBalance",
    T0."FCCurrency", 
    CASE WHEN IFNULL(T0."FCCurrency",T12."MainCurncy")=T12."MainCurncy" THEN 'Y' ELSE 'N' END AS "IsLocCurrency",
    T0."FCDebit",
    T0."FCCredit",
    T0."FCDebit"-"T0"."FCCredit" AS "LineBalanceFC",
    T0."ProfitCode",
    T2."PrcName",
    T0."OcrCode2",
    T3."PrcName" as "PrcName2",
    T0."OcrCode3",
    T4."PrcName" as "PrcName3",
    T0."OcrCode4",
    T5."PrcName" as "PrcName4",
    T0."OcrCode5",
    T6."PrcName" as "PrcName5",
    T0."Project", 
    T1."PrjName",
    T10."Code",
    T10."Category",
    T9."GroupMask",
    T0."BPLId",
    T8."BPLName"
FROM "JDT1" T0
LEFT JOIN "OJDT" M0 ON M0."TransId"=T0."TransId"
LEFT JOIN "OPRJ" T1 ON T0."Project"=T1."PrjCode"
LEFT JOIN "OPRC" T2 ON T0."ProfitCode"=T2."PrcCode"
LEFT JOIN "OPRC" T3 ON T0."OcrCode2"=T3."PrcCode"
LEFT JOIN "OPRC" T4 ON T0."OcrCode3"=T4."PrcCode"
LEFT JOIN "OPRC" T5 ON T0."OcrCode4"=T5."PrcCode"
LEFT JOIN "OPRC" T6 ON T0."OcrCode5"=T6."PrcCode"
LEFT JOIN "OBPL" T8 ON T0."BPLId"=T8."BPLId"
LEFT JOIN "OACT" T9 ON T0."Account"=T9."AcctCode"
LEFT JOIN "OFPR" T10 ON T0."FinncPriod" = T10."AbsEntry"
LEFT JOIN "OCRD" T11 ON T0."ShortName"=T11."CardCode"
INNER JOIN "AgentAll_USERRIGHT"(SESSION_CONTEXT('USERCODE')) TD ON TD.USERID=T0."UserSign"
INNER JOIN "AgentAll_USERBPL"(SESSION_CONTEXT('USERCODE')) TB ON TB.BPLID=IFNULL(T0."BPLId",0)
LEFT JOIN "OADM" T12 ON 1=1
;

CREATE VIEW "SBODEMOUS"."AgentAll_OACT" AS
