CREATE VIEW "SBODEMOUS"."AgentAll_ODLN" AS
SELECT
	 T0."DocNum",
	 T0."DocEntry",
	 T0."DocDate",
	 T0."DocStatus",
	 T0."DocType",
	 T0."ObjType",
	 T0."CardCode",
	 T0."CardName",
	 T5."GroupName",
	 T11."descript" AS "Province",
	 T12."descript" AS "Region",
	 T0."DocCur",
	 CASE WHEN T0."DocCur"=T13."MainCurncy" 
THEN 'Y' 
ELSE 'N' 
END AS "IsLocCurrency",
	 T0."DocRate" ,
	 T0."DiscPrcnt",
	 T2."SlpName",
	 T1."LineNum",
	 T1."LineStatus",
	 T1."BaseType",
	 T1."BaseEntry",
	 T1."BaseLine",
	 T1."ItemCode",
	 T1."SubCatNum",
	 T1."Dscription",
	 T1."AcctCode",
	 T6."AcctName",
	 T9."ItmsGrpNam",
	 T1."Quantity",
	 T1."OpenCreQty",
	 T1."WhsCode",
	 T7."WhsName",
	 T1."ShipDate",
	 T1."VatGroup",
	 T1."VatPrcnt",
	 T1."Currency",
	 CASE WHEN T1."Currency"=T13."MainCurncy" 
THEN 'Y' 
ELSE 'N' 
END AS "LineIsLocCurrency",
	 T1."Rate",
	 CASE WHEN T0."DiscPrcnt"<>0 
THEN (1-T0."DiscPrcnt"/100)* T1."Price" 
ELSE T1."Price" 
END AS "Price",
	 CASE WHEN T0."DiscPrcnt"<>0 
THEN (1-T0."DiscPrcnt"/100)* T1."PriceAfVAT" 
ELSE T1."PriceAfVAT" 
END AS "PriceAfVAT",
	 CASE WHEN T0."DiscPrcnt"<>0 
THEN (1-T0."DiscPrcnt"/100)*T1."LineTotal" 
ELSE T1."LineTotal" 
END AS "LineTotal",
	 CASE WHEN T0."DiscPrcnt"<>0 
THEN (1-T0."DiscPrcnt"/100)*T1."GTotal" 
ELSE T1."GTotal" 
END AS "GTotal",
	 CASE WHEN T0."DiscPrcnt"<>0 
THEN (1-T0."DiscPrcnt"/100)*T1."TotalFrgn" 
ELSE T1."TotalFrgn" 
END AS "TotalFrgn",
	 CASE WHEN T0."DiscPrcnt"<>0 
THEN (1-T0."DiscPrcnt"/100)*T1."GTotalFC" 
ELSE T1."GTotalFC" 
END AS "GTotalFC",
    CASE WHEN T0."DocCur"=T21."MainCurncy" AND T0."DiscPrcnt"<>0 THEN (1-T0."DiscPrcnt"/100)*T1."Price"*T1."OpenCreQty"
           WHEN T0."DocCur"=T21."MainCurncy" AND T0."DiscPrcnt"=0  THEN T1."Price"*T1."OpenCreQty"
     WHEN (T0."DocCur"<>T21."MainCurncy" AND T1."Currency"<>T21."MainCurncy") AND T0."DiscPrcnt"<>0 THEN (1-T0."DiscPrcnt"/100)*T1."Price"*T1."OpenCreQty"*T1."Rate" 
           WHEN (T0."DocCur"<>T21."MainCurncy" AND T1."Currency"<>T21."MainCurncy") AND T0."DiscPrcnt"=0  THEN T1."Price"*T1."OpenCreQty"*T1."Rate"  
     END AS "OpenLineTotal",
  CASE WHEN T0."DocCur"=T21."MainCurncy" AND T0."DiscPrcnt"<>0 THEN (1-T0."DiscPrcnt"/100)*T1."PriceAfVAT"*T1."OpenCreQty"
           WHEN T0."DocCur"=T21."MainCurncy" AND T0."DiscPrcnt"=0  THEN T1."PriceAfVAT"*T1."OpenCreQty"
     WHEN (T0."DocCur"<>T21."MainCurncy" AND T1."Currency"<>T21."MainCurncy") AND T0."DiscPrcnt"<>0 THEN (1-T0."DiscPrcnt"/100)*T1."PriceAfVAT"*T1."OpenCreQty"*T1."Rate" 
           WHEN (T0."DocCur"<>T21."MainCurncy" AND T1."Currency"<>T21."MainCurncy") AND T0."DiscPrcnt"=0  THEN T1."PriceAfVAT"*T1."OpenCreQty"*T1."Rate"  
     END AS "OpenGTotal",
  CASE WHEN T0."DocCur"<>T21."MainCurncy" AND T1."Currency"<>T21."MainCurncy" AND T0."DiscPrcnt"<>0 THEN (1-T0."DiscPrcnt"/100)*T1."Price"*T1."OpenCreQty" 
           WHEN T0."DocCur"<>T21."MainCurncy" AND T1."Currency"<>T21."MainCurncy" AND T0."DiscPrcnt"=0  THEN T1."Price"*T1."OpenCreQty" END AS "OpenTotalFrgn",
  CASE WHEN T0."DocCur"<>T21."MainCurncy" AND T1."Currency"<>T21."MainCurncy" AND T0."DiscPrcnt"<>0 THEN (1-T0."DiscPrcnt"/100)*T1."PriceAfVAT"*T1."OpenCreQty"
           WHEN T0."DocCur"<>T21."MainCurncy" AND T1."Currency"<>T21."MainCurncy"  AND T0."DiscPrcnt"=0  THEN T1."PriceAfVAT"*T1."OpenCreQty" END AS "OpenGTotalFC",
	 T1."Project",
	 T15."PrjName",
	 T1."OcrCode",
	 T16."PrcName" AS "CostCenterName1",
	 T1."OcrCode2",
	 T17."PrcName" AS "CostCenterName2",
	 T1."OcrCode3",
	 T18."PrcName" AS "CostCenterName3",
	 T1."OcrCode4",
	 T19."PrcName" AS "CostCenterName4",
	 T1."OcrCode5",
	 T20."PrcName" AS "CostCenterName5",
	 T10."Code",
	 T10."Category",
	 T0."BPLId",
	 T14."BPLName" 
FROM ODLN T0 
INNER JOIN DLN1 T1 ON T0."DocEntry"=T1."DocEntry" 
LEFT JOIN OSLP T2 ON T0."SlpCode"=T2."SlpCode" 
INNER JOIN OCRD T4 ON T0."CardCode"=T4."CardCode" 
LEFT JOIN OCRG T5 ON T4."GroupCode"=T5."GroupCode" 
LEFT JOIN OACT T6 ON T1."AcctCode"=T6."AcctCode" 
LEFT JOIN OWHS T7 ON T1."WhsCode"=T7."WhsCode" 
LEFT JOIN OITM T8 ON T1."ItemCode"=T8."ItemCode" 
LEFT JOIN OITB T9 ON T8."ItmsGrpCod"=T9."ItmsGrpCod" 
LEFT JOIN OFPR T10 ON T0."FinncPriod" = T10."AbsEntry" 
LEFT JOIN OTER T11 ON T4."Territory"=T11."territryID" 
LEFT JOIN OTER T12 ON T11."parent"=T12."territryID" 
LEFT JOIN OADM T13 ON T0."DocCur"=T13."MainCurncy" 
LEFT JOIN OBPL T14 ON T0."BPLId"=T14."BPLId" 
LEFT JOIN OPRJ T15 ON T1."Project" =T15."PrjCode" 
LEFT JOIN (SELECT
	 "PrcCode",
	"PrcName" 
	FROM OPRC 
	WHERE "DimCode"=1) T16 ON T1."OcrCode"=T16."PrcCode" 
LEFT JOIN (SELECT
	 "PrcCode",
	"PrcName" 
	FROM OPRC 
	WHERE "DimCode"=2) T17 ON T1."OcrCode2"=T17."PrcCode" 
LEFT JOIN (SELECT
	 "PrcCode",
	"PrcName" 
	FROM OPRC 
	WHERE "DimCode"=3) T18 ON T1."OcrCode3"=T18."PrcCode" 
LEFT JOIN (SELECT
	 "PrcCode",
	"PrcName" 
	FROM OPRC 
	WHERE "DimCode"=4) T19 ON T1."OcrCode4"=T19."PrcCode" 
LEFT JOIN (SELECT
	 "PrcCode",
	"PrcName" 
	FROM OPRC 
	WHERE "DimCode"=5) T20 ON T1."OcrCode5"=T20."PrcCode" 
LEFT JOIN OADM T21  ON 1=1 
INNER JOIN "AgentAll_USERRIGHT"(SESSION_CONTEXT('USERCODE')) TD ON TD.USERID=T0."UserSign" 
INNER JOIN "AgentAll_USERBPL"(SESSION_CONTEXT('USERCODE')) TB ON TB.BPLID=IFNULL(T0."BPLId",
	0) 
WHERE T0."CANCELED"='N'
;

