CREATE VIEW "SBODEMOUS"."AgentAll_OINV" AS
SELECT
  T0."DocNum",
  T0."DocEntry",
  T0."DocDate",
  T0."DocStatus",
  T0."DocType",
  T0."ObjType",
 T0."NumAtCard",
  T0."CardCode",
  T0."CardName",
  T5."GroupName",
  T11."descript" AS "Province",
  T12."descript" AS "Region",
  T0."DocCur",
  CASE WHEN T0."DocCur"=T13."MainCurncy" THEN 'Y' ELSE 'N' END AS "IsLocCurrency",
  T0."DocRate" ,
  T0."DiscPrcnt",
  T2."SlpName",
  T1."LineNum",
  T1."LineStatus",
  T1."BaseType",
  T1."BaseEntry",
  T1."BaseLine",
  T1."ItemCode",
  T1."SubCatNum",
  T1."Dscription",
  T1."AcctCode",
  T6."AcctName",
  T9."ItmsGrpNam" ,
  T1."Quantity",
  T1."OpenCreQty",
  T1."WhsCode",
  T7."WhsName",
  T1."ShipDate",
  T1."VatGroup",
  T1."VatPrcnt",
  T1."Currency",
  CASE WHEN T1."Currency"=T13."MainCurncy" THEN 'Y' ELSE 'N' END AS "LineIsLocCurrency",
  T1."Rate",
  CASE WHEN  T0."DiscPrcnt"<>0 THEN (1-T0."DiscPrcnt"/100)* T1."Price" ELSE  T1."Price" END AS "Price", 
  CASE WHEN  T0."DiscPrcnt"<>0 THEN (1-T0."DiscPrcnt"/100)* T1."PriceAfVAT" ELSE  T1."PriceAfVAT" END AS "PriceAfVAT",
  CASE WHEN  T0."DiscPrcnt"<>0 THEN (1-T0."DiscPrcnt"/100)*T1."LineTotal" ELSE T1."LineTotal" END AS "LineTotal",
  CASE WHEN  T0."DiscPrcnt"<>0 THEN (1-T0."DiscPrcnt"/100)*T1."GTotal" ELSE T1."GTotal" END AS "GTotal",
  CASE WHEN  T0."DiscPrcnt"<>0 THEN (1-T0."DiscPrcnt"/100)*T1."TotalFrgn" ELSE T1."TotalFrgn" END AS "TotalFrgn",
  CASE WHEN  T0."DiscPrcnt"<>0 THEN (1-T0."DiscPrcnt"/100)*T1."GTotalFC" ELSE T1."GTotalFC" END AS "GTotalFC",
  T1."Project",
  T15."PrjName",
  T1."OcrCode",
  T16."PrcName" AS "CostCenterName1",
  T1."OcrCode2",
  T17."PrcName" AS "CostCenterName2",
  T1."OcrCode3",
  T18."PrcName" AS "CostCenterName3",
  T1."OcrCode4",
  T19."PrcName" AS "CostCenterName4",
  T1."OcrCode5",
  T20."PrcName" AS "CostCenterName5",
  T10."Code",
  T10."Category",
  T0."BPLId",
  T14."BPLName" 
FROM OINV T0 
INNER JOIN INV1 T1 ON T0."DocEntry"=T1."DocEntry" 
LEFT JOIN OSLP T2 ON T0."SlpCode"=T2."SlpCode" 
INNER JOIN OCRD T4 ON T0."CardCode"=T4."CardCode" 
LEFT JOIN OCRG T5 ON T4."GroupCode"=T5."GroupCode" 
LEFT JOIN OACT T6 ON T1."AcctCode"=T6."AcctCode"
LEFT JOIN OWHS T7 ON T1."WhsCode"=T7."WhsCode" 
LEFT JOIN OITM T8 ON T1."ItemCode"=T8."ItemCode" 
LEFT JOIN OITB T9 ON T8."ItmsGrpCod"=T9."ItmsGrpCod" 
LEFT JOIN OFPR T10 ON T0."FinncPriod" = T10."AbsEntry" 
LEFT JOIN OTER T11 ON T4."Territory"=T11."territryID" 
LEFT JOIN OTER T12 ON T11."parent"=T12."territryID" 
LEFT JOIN OADM T13 ON T0."DocCur"=T13."MainCurncy"
LEFT JOIN OBPL T14 ON T0."BPLId"=T14."BPLId"
LEFT JOIN OPRJ T15 ON T1."Project" =T15."PrjCode"
LEFT  JOIN  (SELECT "PrcCode","PrcName" FROM  OPRC WHERE "DimCode"=1) T16 ON T1."OcrCode"=T16."PrcCode"
LEFT  JOIN  (SELECT "PrcCode","PrcName" FROM  OPRC WHERE "DimCode"=2) T17 ON T1."OcrCode2"=T17."PrcCode"
LEFT  JOIN  (SELECT "PrcCode","PrcName" FROM  OPRC WHERE "DimCode"=3) T18 ON T1."OcrCode3"=T18."PrcCode"
LEFT  JOIN  (SELECT "PrcCode","PrcName" FROM  OPRC WHERE "DimCode"=4) T19 ON T1."OcrCode4"=T19."PrcCode"
LEFT  JOIN  (SELECT "PrcCode","PrcName" FROM  OPRC WHERE "DimCode"=5) T20 ON T1."OcrCode5"=T20."PrcCode"
INNER JOIN "AgentAll_USERRIGHT"(SESSION_CONTEXT('USERCODE')) TD ON TD.USERID=T0."UserSign"
INNER JOIN "AgentAll_USERBPL"(SESSION_CONTEXT('USERCODE')) TB ON TB.BPLID=IFNULL(T0."BPLId",0)
WHERE T0.CANCELED='N'
;

CREATE VIEW "SBODEMOUS"."AgentAll_OITM" AS
SELECT
    T0."ItemCode", 
    T0."ItemName", 
    T0."FrgnName",
    CASE 
        WHEN T0."ItemType" = 'I' THEN 'Item'
        WHEN T0."ItemType" = 'L' THEN 'Labor' 
        WHEN T0."ItemType" = 'T' THEN 'Travel' 
    END AS "ItemType",
    T2."ItmsGrpNam", 
    T0."InvntItem",
    T0."SellItem",
    T0."PrchseItem",
    T4."FirmName",
    CASE 
        WHEN T0."ManSerNum" = 'Y' THEN 'Serial Number Managed'
        WHEN T0."ManBtchNum" = 'Y' THEN 'Batch Managed' 
        ELSE 'None' 
    END AS "IsManBtchSer",
    CASE 
        WHEN T0."MngMethod" = 'A' THEN 'Per Transaction'
        WHEN T0."MngMethod" = 'R' THEN 'Outbound Only' 
    END AS "MngMethod",
    T0."BuyUnitMsr", 
    T0."NumInBuy", 
    T0."VatGroupPu",
    T0."SuppCatNum",  
    T0."SalUnitMsr", 
    T0."NumInSale", 
    T0."VatGourpSa",
    T0."validFor",  
    T0."frozenFor", 
    T0."Spec", 
    T0."TaxCtg",
    T0."TaxCatCode",
    T3."Name" AS "TaxCatName",
    T0."InvntryUom", 
    CASE 
        WHEN T0."GLMethod" = 'W' THEN 'Warehouse'
        WHEN T0."GLMethod" = 'C' THEN 'Item Group' 
        WHEN T0."GLMethod" = 'L' THEN 'Item Level' 
    END AS "GLMethod",
    CASE 
        WHEN T0."EvalSystem" = 'A' THEN 'Moving Average'
        WHEN T0."EvalSystem" = 'S' THEN 'Standard Cost' 
        WHEN T0."EvalSystem" = 'F' THEN 'FIFO' 
        WHEN T0."EvalSystem" = 'B' THEN 'Batch/Serial' 
    END AS "EvalSystem",
    T0."ByWh",
    T0."MinLevel",
    T0."MaxLevel",
    CASE 
        WHEN T0."PlaningSys" = 'M' THEN 'MRP' 
        ELSE 'None' 
    END AS "PlaningSys",
    CASE 
        WHEN T0."PrcrmntMtd" = 'M' THEN 'Manufacture'
        WHEN T0."PrcrmntMtd" = 'B' THEN 'Purchase' 
    END AS "PrcrmntMtd",
    T0."OrdrMulti",
    T0."MinOrdrQty",
    T0."LeadTime",
    T0."Phantom",
    CASE 
        WHEN T0."IssueMthd" = 'B' THEN 'Backflush'
        WHEN T0."IssueMthd" = 'M' THEN 'Manual' 
    END AS "IssueMthd",
    T0."CreateDate",   
    T0."UpdateDate"
FROM "OITM" T0
LEFT JOIN "ITM1" T1 ON T1."PriceList" = '1' AND T1."ItemCode" = T0."ItemCode"
LEFT JOIN "OITB" T2 ON T0."ItmsGrpCod" = T2."ItmsGrpCod"
LEFT JOIN OTCC T3 ON T0."TaxCatCode" = T3."Code"
LEFT JOIN OMRC T4 ON T0."FirmCode" = T4."FirmCode"
WHERE T0."ItemCode" IS NOT NULL
;

CREATE VIEW "SBODEMOUS"."AgentAll_OIVL" AS
SELECT
  T0."DocDate",
  T0."TransType",
  T0."BASE_REF",
  T0."DocLineNum",
  T0."ItemCode",
  T1."ItemName",
  T2."ItmsGrpNam",
  T0."InQty",
  T0."OutQty" ,
  T0."LocCode",
  T3."WhsName",
  T3."BPLid",
  T4."BPLName" 
FROM OIVL T0 
INNER JOIN "OITM" T1 ON T0."ItemCode" = T1."ItemCode" 
LEFT JOIN "OITB" T2 ON T1."ItmsGrpCod" = T2."ItmsGrpCod"
LEFT JOIN "OWHS" T3 ON T0."LocCode"=T3."WhsCode"
LEFT JOIN "OBPL" T4 ON T3."BPLid"=T4."BPLId"
INNER JOIN "AgentAll_USERRIGHT"(SESSION_CONTEXT('USERCODE')) TD ON TD.USERID=T0."UserSign"
INNER JOIN "AgentAll_USERBPL"(SESSION_CONTEXT('USERCODE')) TB ON TB.BPLID=IFNULL(T4."BPLId",0)
;

CREATE VIEW "SBODEMOUS"."AgentAll_OPCH" AS
SELECT
  T0."DocNum",
  T0."DocEntry",
  T0."DocDate",
  T0."DocStatus",
  T0."DocType",
  T0."ObjType",
T0."NumAtCard",
  T0."CardCode",
  T0."CardName",
  T5."GroupName",
  T0."DocCur",
  CASE WHEN T0."DocCur"=T13."MainCurncy" THEN 'Y' ELSE 'N' END AS "IsLocCurrency",
  T0."DocRate" ,
  T0."DiscPrcnt",
  T2."SlpName",
  T1."LineNum",
  T1."LineStatus",
  T1."BaseType",
  T1."BaseEntry",
  T1."BaseLine",
  T1."ItemCode",
  T1."SubCatNum",
  T1."Dscription",
  T1."AcctCode",
  T11."AcctName",
  T9."ItmsGrpNam" ,
  T1."Quantity",
  T1."OpenCreQty",
  T1."WhsCode",
  T7."WhsName",
  T1."ShipDate",
  T1."VatGroup",
  T1."VatPrcnt",
  T1."Currency",
  CASE WHEN T1."Currency"=T13."MainCurncy" THEN 'Y' ELSE 'N' END AS "LineIsLocCurrency",
  T1."Rate",
 CASE WHEN  T0."DiscPrcnt"<>0 THEN (1-T0."DiscPrcnt"/100)* T1."Price" ELSE  T1."Price" END AS "Price", 
 CASE WHEN  T0."DiscPrcnt"<>0 THEN (1-T0."DiscPrcnt"/100)* T1."PriceAfVAT" ELSE  T1."PriceAfVAT" END AS "PriceAfVAT",
  CASE WHEN  T0."DiscPrcnt"<>0 THEN (1-T0."DiscPrcnt"/100)*T1."LineTotal" ELSE T1."LineTotal" END AS "LineTotal",
 CASE WHEN  T0."DiscPrcnt"<>0 THEN (1-T0."DiscPrcnt"/100)*T1."GTotal" ELSE T1."GTotal" END AS "GTotal",
 CASE WHEN  T0."DiscPrcnt"<>0 THEN (1-T0."DiscPrcnt"/100)*T1."TotalFrgn" ELSE T1."TotalFrgn" END AS "TotalFrgn",
 CASE WHEN  T0."DiscPrcnt"<>0 THEN (1-T0."DiscPrcnt"/100)*T1."GTotalFC" ELSE T1."GTotalFC" END AS "GTotalFC",
  T1."Project",
  T15."PrjName",
  T1."OcrCode",
  T16."PrcName" AS "CostCenterName1",
  T1."OcrCode2",
  T17."PrcName" AS "CostCenterName2",
  T1."OcrCode3",
  T18."PrcName" AS "CostCenterName3",
  T1."OcrCode4",
  T19."PrcName" AS "CostCenterName4",
  T1."OcrCode5",
  T20."PrcName" AS "CostCenterName5",
  T10."Code",
  T10."Category",
  T0."BPLId",
  T14."BPLName" 
FROM OPCH T0 
INNER JOIN PCH1 T1 ON T0."DocEntry"=T1."DocEntry" 
LEFT JOIN OSLP T2 ON T0."SlpCode"=T2."SlpCode" 
INNER JOIN OCRD T4 ON T0."CardCode"=T4."CardCode" 
LEFT JOIN OCRG T5 ON T4."GroupCode"=T5."GroupCode" 
LEFT JOIN OWHS T7 ON T1."WhsCode"=T7."WhsCode" 
LEFT JOIN OITM T8 ON T1."ItemCode"=T8."ItemCode" 
LEFT JOIN OITB T9 ON T8."ItmsGrpCod"=T9."ItmsGrpCod" 
LEFT JOIN OFPR T10 ON T0."FinncPriod" = T10."AbsEntry" 
LEFT JOIN OACT T11 ON T1."AcctCode"=T11."AcctCode"
LEFT JOIN OADM T13 ON T0."DocCur"=T13."MainCurncy"
LEFT JOIN OBPL T14 ON T0."BPLId"=T14."BPLId"
LEFT JOIN OPRJ T15 ON T1."Project" =T15."PrjCode"
LEFT  JOIN  (SELECT "PrcCode","PrcName" FROM  OPRC WHERE "DimCode"=1) T16 ON T1."OcrCode"=T16."PrcCode"
LEFT  JOIN  (SELECT "PrcCode","PrcName" FROM  OPRC WHERE "DimCode"=2) T17 ON T1."OcrCode2"=T17."PrcCode"
LEFT  JOIN  (SELECT "PrcCode","PrcName" FROM  OPRC WHERE "DimCode"=3) T18 ON T1."OcrCode3"=T18."PrcCode"
LEFT  JOIN  (SELECT "PrcCode","PrcName" FROM  OPRC WHERE "DimCode"=4) T19 ON T1."OcrCode4"=T19."PrcCode"
LEFT  JOIN  (SELECT "PrcCode","PrcName" FROM  OPRC WHERE "DimCode"=5) T20 ON T1."OcrCode5"=T20."PrcCode"
INNER JOIN "AgentAll_USERRIGHT"(SESSION_CONTEXT('USERCODE')) TD ON TD.USERID=T0."UserSign"
INNER JOIN "AgentAll_USERBPL"(SESSION_CONTEXT('USERCODE')) TB ON TB.BPLID=IFNULL(T0."BPLId",0)
WHERE T0.CANCELED='N'
;

CREATE VIEW "SBODEMOUS"."AgentAll_OPDN" AS
SELECT
 T0."DocNum",
 T0."DocEntry",
 T0."DocDate",
 T0."DocStatus",
 T0."DocType",
 T0."ObjType",
 T0."CardCode",
 T0."CardName",
 T5."GroupName",
 T0."DocCur",
 CASE WHEN T0."DocCur"=T13."MainCurncy" THEN 'Y' ELSE 'N' END AS "IsLocCurrency",
 T0."DocRate" ,
 T0."DiscPrcnt",
 T2."SlpName",
 T1."LineNum",
 T1."LineStatus",
 T1."BaseType",
 T1."BaseEntry",
 T1."BaseLine",
 T1."ItemCode",
 T1."SubCatNum",
 T1."Dscription",
 T1."AcctCode",
 T11."AcctName",
 T9."ItmsGrpNam" ,
 T1."Quantity" ,
 T1."OpenCreQty" ,
 T1."WhsCode",
 T7."WhsName",
 T1."ShipDate",
 T1."VatGroup",
 T1."VatPrcnt",
 T1."Currency",
 CASE WHEN T1."Currency"=T13."MainCurncy" THEN 'Y' ELSE 'N' END AS "LineIsLocCurrency",
 T1."Rate",
 CASE WHEN  T0."DiscPrcnt"<>0 THEN (1-T0."DiscPrcnt"/100)* T1."Price" ELSE  T1."Price" END AS "Price", 
 CASE WHEN  T0."DiscPrcnt"<>0 THEN (1-T0."DiscPrcnt"/100)* T1."PriceAfVAT" ELSE  T1."PriceAfVAT" END AS "PriceAfVAT",
 CASE WHEN  T0."DiscPrcnt"<>0 THEN (1-T0."DiscPrcnt"/100)*T1."LineTotal" ELSE T1."LineTotal" END AS "LineTotal",
 CASE WHEN  T0."DiscPrcnt"<>0 THEN (1-T0."DiscPrcnt"/100)*T1."GTotal" ELSE T1."GTotal" END AS "GTotal",
 CASE WHEN  T0."DiscPrcnt"<>0 THEN (1-T0."DiscPrcnt"/100)*T1."TotalFrgn" ELSE T1."TotalFrgn" END AS "TotalFrgn",
 CASE WHEN  T0."DiscPrcnt"<>0 THEN (1-T0."DiscPrcnt"/100)*T1."GTotalFC" ELSE T1."GTotalFC" END AS "GTotalFC",
      CASE WHEN T0."DocCur"=T21."MainCurncy" AND T0."DiscPrcnt"<>0 THEN (1-T0."DiscPrcnt"/100)*T1."Price"*T1."OpenQty"
           WHEN T0."DocCur"=T21."MainCurncy" AND T0."DiscPrcnt"=0  THEN T1."Price"*T1."OpenQty"
     WHEN (T0."DocCur"<>T21."MainCurncy" AND T1."Currency"<>T21."MainCurncy") AND T0."DiscPrcnt"<>0 THEN (1-T0."DiscPrcnt"/100)*T1."Price"*T1."OpenQty"*T1."Rate" 
           WHEN (T0."DocCur"<>T21."MainCurncy" AND T1."Currency"<>T21."MainCurncy") AND T0."DiscPrcnt"=0  THEN T1."Price"*T1."OpenQty"*T1."Rate"  
     END AS "OpenLineTotal",
  CASE WHEN T0."DocCur"=T21."MainCurncy" AND T0."DiscPrcnt"<>0 THEN (1-T0."DiscPrcnt"/100)*T1."PriceAfVAT"*T1."OpenQty"
           WHEN T0."DocCur"=T21."MainCurncy" AND T0."DiscPrcnt"=0  THEN T1."PriceAfVAT"*T1."OpenQty"
     WHEN (T0."DocCur"<>T21."MainCurncy" AND T1."Currency"<>T21."MainCurncy") AND T0."DiscPrcnt"<>0 THEN (1-T0."DiscPrcnt"/100)*T1."PriceAfVAT"*T1."OpenQty"*T1."Rate" 
           WHEN (T0."DocCur"<>T21."MainCurncy" AND T1."Currency"<>T21."MainCurncy") AND T0."DiscPrcnt"=0  THEN T1."PriceAfVAT"*T1."OpenQty"*T1."Rate"  
     END AS "OpenGTotal",
  CASE WHEN T0."DocCur"<>T21."MainCurncy" AND T1."Currency"<>T21."MainCurncy" AND T0."DiscPrcnt"<>0 THEN (1-T0."DiscPrcnt"/100)*T1."Price"*T1."OpenQty" 
           WHEN T0."DocCur"<>T21."MainCurncy" AND T1."Currency"<>T21."MainCurncy" AND T0."DiscPrcnt"=0  THEN T1."Price"*T1."OpenQty" END AS "OpenTotalFrgn",
  CASE WHEN T0."DocCur"<>T21."MainCurncy" AND T1."Currency"<>T21."MainCurncy" AND T0."DiscPrcnt"<>0 THEN (1-T0."DiscPrcnt"/100)*T1."PriceAfVAT"*T1."OpenQty"
           WHEN T0."DocCur"<>T21."MainCurncy" AND T1."Currency"<>T21."MainCurncy"  AND T0."DiscPrcnt"=0  THEN T1."PriceAfVAT"*T1."OpenQty" END AS "OpenGTotalFC",
 T1."Project",
 T15."PrjName",
 T1."OcrCode",
 T16."PrcName" AS "CostCenterName1",
 T1."OcrCode2",
 T17."PrcName" AS "CostCenterName2",
 T1."OcrCode3",
 T18."PrcName" AS "CostCenterName3",
 T1."OcrCode4",
 T19."PrcName" AS "CostCenterName4",
 T1."OcrCode5",
 T20."PrcName" AS "CostCenterName5",
 T10."Code",
 T10."Category",
 T0."BPLId",
 T14."BPLName"
FROM OPDN T0 
INNER JOIN PDN1 T1 ON T0."DocEntry"=T1."DocEntry" 
LEFT JOIN OSLP T2 ON T0."SlpCode"=T2."SlpCode" 
INNER JOIN OCRD T4 ON T0."CardCode"=T4."CardCode" 
LEFT JOIN OCRG T5 ON T4."GroupCode"=T5."GroupCode" 
LEFT JOIN OWHS T7 ON T1."WhsCode"=T7."WhsCode" 
LEFT JOIN OITM T8 ON T1."ItemCode"=T8."ItemCode" 
LEFT JOIN OITB T9 ON T8."ItmsGrpCod"=T9."ItmsGrpCod" 
LEFT JOIN OFPR T10 ON T0."FinncPriod" = T10."AbsEntry" 
LEFT JOIN OACT T11 ON T1."AcctCode"=T11."AcctCode"
LEFT JOIN OADM T13 ON T0."DocCur"=T13."MainCurncy"
LEFT JOIN OBPL T14 ON T0."BPLId"=T14."BPLId"
LEFT JOIN OPRJ T15 ON T1."Project" =T15."PrjCode"
LEFT  JOIN  (SELECT "PrcCode","PrcName" FROM  OPRC WHERE "DimCode"=1) T16 ON T1."OcrCode"=T16."PrcCode"
LEFT  JOIN  (SELECT "PrcCode","PrcName" FROM  OPRC WHERE "DimCode"=2) T17 ON T1."OcrCode2"=T17."PrcCode"
LEFT  JOIN  (SELECT "PrcCode","PrcName" FROM  OPRC WHERE "DimCode"=3) T18 ON T1."OcrCode3"=T18."PrcCode"
LEFT  JOIN  (SELECT "PrcCode","PrcName" FROM  OPRC WHERE "DimCode"=4) T19 ON T1."OcrCode4"=T19."PrcCode"
LEFT  JOIN  (SELECT "PrcCode","PrcName" FROM  OPRC WHERE "DimCode"=5) T20 ON T1."OcrCode5"=T20."PrcCode"
LEFT JOIN OADM T21  ON 1=1 
INNER JOIN "AgentAll_USERRIGHT"(SESSION_CONTEXT('USERCODE')) TD ON TD.USERID=T0."UserSign"
INNER JOIN "AgentAll_USERBPL"(SESSION_CONTEXT('USERCODE')) TB ON TB.BPLID=IFNULL(T0."BPLId",0)
WHERE T0.CANCELED='N'
;

CREATE VIEW "SBODEMOUS"."AgentAll_OPKL" AS
SELECT
 T0."AbsEntry",
 T0. "PickDate",
 T0."Canceled",
 T0."CreateDate",
 T0."Status",
 T1."BaseObject",
 T1."OrderEntry",
 T1."OrderLine" ,
 T3."CardCode",
 T3."CardName",
 T4."SlpName",
 T2."ItemCode",
 T2."Dscription",
 T1."RelQtty",
 T1."PickQtty",
 T1."PickStatus" ,
 T3."BPLId",
 T5."BPLName"
FROM "OPKL" T0 
INNER JOIN "PKL1" T1 ON T0."AbsEntry"=T1."AbsEntry" 
INNER JOIN "RDR1" T2 ON T1."OrderEntry"=T2."DocEntry" AND T1."OrderLine"=T2."LineNum" 
LEFT JOIN "ORDR" T3 ON T2."DocEntry"=T3."DocEntry"
LEFT JOIN "OSLP" T4 ON T3."SlpCode"=T4."SlpCode"
LEFT JOIN OBPL T5 ON T3."BPLId"=T5."BPLId"
INNER JOIN "AgentAll_USERRIGHT"(SESSION_CONTEXT('USERCODE')) TD ON TD.USERID=T0."UserSign"
INNER JOIN "AgentAll_USERBPL"(SESSION_CONTEXT('USERCODE')) TB ON TB.BPLID=IFNULL(T3."BPLId",0)
WHERE T1."BaseObject"='17'
;

