CREATE VIEW "SBODEMOUS"."AgentAll_OPOR" AS
SELECT
	 T0."DocNum",
	 T0."DocEntry",
	 T0."DocDate",
	 T0."DocStatus",
	 T0."DocType",
	 T0."ObjType",
	 T0."NumAtCard",
	 T0."CardCode",
	 T0."CardName",
	 T5."GroupName",
	 T0."DocCur",
	 T0."Comments",
	 T13."MainCurncy",
	 CASE WHEN T0."DocCur"=T13."MainCurncy" 
THEN 'Y' 
ELSE 'N' 
END AS "IsLocCurrency",
	 T0."DocRate" ,
	 T0."DiscPrcnt",
	 T2."SlpName",
	 T1."LineNum",
	 T1."LineStatus",
	 T1."BaseType",
	 T1."BaseEntry",
	 T1."BaseLine",
	 T1."ItemCode",
	 T1."SubCatNum",
	 T1."Dscription",
	 T1."AcctCode",
	 T11."AcctName",
	 T9."ItmsGrpNam" ,
	 T1."Quantity",
	 T1."OpenQty",
	 T1."WhsCode",
	 T7."WhsName",
	 T1."ShipDate",
	 T1."VatGroup",
	 T1."VatPrcnt",
	 T1."Currency",
	 CASE WHEN T1."Currency"=T13."MainCurncy" 
THEN 'Y' 
ELSE 'N' 
END AS "LineIsLocCurrency",
	 T1."Rate",
	 CASE WHEN T0."DiscPrcnt"<>0 
THEN (1-T0."DiscPrcnt"/100)* T1."Price" 
ELSE T1."Price" 
END AS "Price",
	 CASE WHEN T0."DiscPrcnt"<>0 
THEN (1-T0."DiscPrcnt"/100)* T1."PriceAfVAT" 
ELSE T1."PriceAfVAT" 
END AS "PriceAfVAT",
	 CASE WHEN T0."DiscPrcnt"<>0 
THEN (1-T0."DiscPrcnt"/100)*T1."LineTotal" 
ELSE T1."LineTotal" 
END AS "LineTotal",
	 CASE WHEN T0."DiscPrcnt"<>0 
THEN (1-T0."DiscPrcnt"/100)*T1."GTotal" 
ELSE T1."GTotal" 
END AS "GTotal",
	 CASE WHEN T0."DiscPrcnt"<>0 
THEN (1-T0."DiscPrcnt"/100)*T1."TotalFrgn" 
ELSE T1."TotalFrgn" 
END AS "TotalFrgn",
	 CASE WHEN T0."DiscPrcnt"<>0 
THEN (1-T0."DiscPrcnt"/100)*T1."GTotalFC" 
ELSE T1."GTotalFC" 
END AS "GTotalFC",
	 CASE WHEN T0."DocCur"=T21."MainCurncy" 
AND T0."DiscPrcnt"<>0 
THEN (1-T0."DiscPrcnt"/100)*T1."Price"*T1."OpenQty" WHEN T0."DocCur"=T21."MainCurncy" 
AND T0."DiscPrcnt"=0 
THEN T1."Price"*T1."OpenQty" WHEN (T0."DocCur"<>T21."MainCurncy" 
	AND T1."Currency"<>T21."MainCurncy") 
AND T0."DiscPrcnt"<>0 
THEN (1-T0."DiscPrcnt"/100)*T1."Price"*T1."OpenQty"*T1."Rate" WHEN (T0."DocCur"<>T21."MainCurncy" 
	AND T1."Currency"<>T21."MainCurncy") 
AND T0."DiscPrcnt"=0 
THEN T1."Price"*T1."OpenQty"*T1."Rate" 
END AS "OpenLineTotal",
	 CASE WHEN T0."DocCur"=T21."MainCurncy" 
AND T0."DiscPrcnt"<>0 
THEN (1-T0."DiscPrcnt"/100)*T1."PriceAfVAT"*T1."OpenQty" WHEN T0."DocCur"=T21."MainCurncy" 
AND T0."DiscPrcnt"=0 
THEN T1."PriceAfVAT"*T1."OpenQty" WHEN (T0."DocCur"<>T21."MainCurncy" 
	AND T1."Currency"<>T21."MainCurncy") 
AND T0."DiscPrcnt"<>0 
THEN (1-T0."DiscPrcnt"/100)*T1."PriceAfVAT"*T1."OpenQty"*T1."Rate" WHEN (T0."DocCur"<>T21."MainCurncy" 
	AND T1."Currency"<>T21."MainCurncy") 
AND T0."DiscPrcnt"=0 
THEN T1."PriceAfVAT"*T1."OpenQty"*T1."Rate" 
END AS "OpenGTotal",
	 CASE WHEN T0."DocCur"<>T21."MainCurncy" 
AND T1."Currency"<>T21."MainCurncy" 
AND T0."DiscPrcnt"<>0 
THEN (1-T0."DiscPrcnt"/100)*T1."Price"*T1."OpenQty" WHEN T0."DocCur"<>T21."MainCurncy" 
AND T1."Currency"<>T21."MainCurncy" 
AND T0."DiscPrcnt"=0 
THEN T1."Price"*T1."OpenQty" 
END AS "OpenTotalFrgn",
	 CASE WHEN T0."DocCur"<>T21."MainCurncy" 
AND T1."Currency"<>T21."MainCurncy" 
AND T0."DiscPrcnt"<>0 
THEN (1-T0."DiscPrcnt"/100)*T1."PriceAfVAT"*T1."OpenQty" WHEN T0."DocCur"<>T21."MainCurncy" 
AND T1."Currency"<>T21."MainCurncy" 
AND T0."DiscPrcnt"=0 
THEN T1."PriceAfVAT"*T1."OpenQty" 
END AS "OpenGTotalFC",
	 T1."Project",
	 T15."PrjName",
	 T1."OcrCode",
	 T16."PrcName" AS "CostCenterName1",
	 T1."OcrCode2",
	 T17."PrcName" AS "CostCenterName2",
	 T1."OcrCode3",
	 T18."PrcName" AS "CostCenterName3",
	 T1."OcrCode4",
	 T19."PrcName" AS "CostCenterName4",
	 T1."OcrCode5",
	 T20."PrcName" AS "CostCenterName5",
	 T10."Code",
	 T10."Category",
	 T0."BPLId",
	 T14."BPLName" 
FROM OPOR T0 
INNER JOIN POR1 T1 ON T0."DocEntry"=T1."DocEntry" 
LEFT JOIN OSLP T2 ON T0."SlpCode"=T2."SlpCode" 
INNER JOIN OCRD T4 ON T0."CardCode"=T4."CardCode" 
LEFT JOIN OCRG T5 ON T4."GroupCode"=T5."GroupCode" 
LEFT JOIN OWHS T7 ON T1."WhsCode"=T7."WhsCode" 
LEFT JOIN OITM T8 ON T1."ItemCode"=T8."ItemCode" 
LEFT JOIN OITB T9 ON T8."ItmsGrpCod"=T9."ItmsGrpCod" 
LEFT JOIN OFPR T10 ON T0."FinncPriod" = T10."AbsEntry" 
LEFT JOIN OACT T11 ON T1."AcctCode"=T11."AcctCode" 
LEFT JOIN OADM T13 ON T0."DocCur"=T13."MainCurncy" 
LEFT JOIN OBPL T14 ON T0."BPLId"=T14."BPLId" 
LEFT JOIN OPRJ T15 ON T1."Project" =T15."PrjCode" 
LEFT JOIN (SELECT
	 "PrcCode",
	 "PrcName" 
	FROM OPRC 
	WHERE "DimCode"=1) T16 ON T1."OcrCode"=T16."PrcCode" 
LEFT JOIN (SELECT
	 "PrcCode",
	 "PrcName" 
	FROM OPRC 
	WHERE "DimCode"=2) T17 ON T1."OcrCode2"=T17."PrcCode" 
LEFT JOIN (SELECT
	 "PrcCode",
	 "PrcName" 
	FROM OPRC 
	WHERE "DimCode"=3) T18 ON T1."OcrCode3"=T18."PrcCode" 
LEFT JOIN (SELECT
	 "PrcCode",
	 "PrcName" 
	FROM OPRC 
	WHERE "DimCode"=4) T19 ON T1."OcrCode4"=T19."PrcCode" 
LEFT JOIN (SELECT
	 "PrcCode",
	 "PrcName" 
	FROM OPRC 
	WHERE "DimCode"=5) T20 ON T1."OcrCode5"=T20."PrcCode" 
LEFT JOIN OADM T21 ON 1=1 
INNER JOIN "AgentAll_USERRIGHT"(SESSION_CONTEXT('USERCODE')) TD ON TD.USERID=T0."UserSign" 
INNER JOIN "AgentAll_USERBPL"(SESSION_CONTEXT('USERCODE')) TB ON TB.BPLID=IFNULL(T0."BPLId",
	 0) 
WHERE T0.CANCELED='N'
;

CREATE VIEW "SBODEMOUS"."AgentAll_OPRC" AS
SELECT
	 T0."DocNum",
	T0."DocEntry",
	T0."DocDate",
	 T0."DocStatus",
	T0."CardCode",
	T0."CardName",
	T5."GroupName",
	T0."DocCur",
	T0."DocRate" ,
	 T2."SlpName",
	T1."LineNum",
	T1."LineStatus",
	T1."ItemCode",
	T1."SubCatNum",
	T1."Dscription",
	T9."ItmsGrpNam" ,
	-T1."Quantity" AS "Quantity" ,
	T7."WhsName",
	T1."VatPrcnt",
	T1."Price",
	T1."PriceAfVAT",
	-T1."LineTotal" AS "LineTotal",
	-T1."GTotal" AS "GTotal",
	-T1."TotalFrgn" AS "TotalFrgn",
	-T1."GTotalFC" AS "GTotalFC",
	 T11."Reason",
	T10."Code",
	T10."Category" 
FROM ORPC T0 
INNER JOIN RPC1 T1 ON T0."DocEntry"=T1."DocEntry" 
LEFT JOIN OSLP T2 ON T0."SlpCode"=T2."SlpCode" 
INNER JOIN OCRD T4 ON T0."CardCode"=T4."CardCode" 
LEFT JOIN OCRG T5 ON T4."GroupCode"=T5."GroupCode" 
INNER JOIN OWHS T7 ON T1."WhsCode"=T7."WhsCode" 
INNER JOIN OITM T8 ON T1."ItemCode"=T8."ItemCode" 
LEFT JOIN OITB T9 ON T8."ItmsGrpCod"=T9."ItmsGrpCod" 
LEFT JOIN OFPR T10 ON T0."FinncPriod" = T10."AbsEntry" 
LEFT JOIN ORER T11 ON T1."ReturnRsn"=T11."AbsEntry" 
WHERE T0.CANCELED='N' 
AND T0."DocType"='I'
;

CREATE VIEW "SBODEMOUS"."AgentAll_OQUT" AS
SELECT
	 T0."DocNum",
	 T0."DocEntry",
	 T0."DocDate",
	 T0."DocDueDate",
	 T0."DocStatus",
	 T0."DocType",
	 T0."ObjType",
	 T0."NumAtCard",
	 T0."CardCode",
	 T0."CardName",
	 T0."GroupNum",
	 T14."PymntGroup",
	 T5."GroupName",
	 T11."descript" AS "Province",
	 T12."descript" AS "Region",
	 T0."DocCur",
	 T0."Comments",
	 T21."MainCurncy",
	 CASE WHEN T0."DocCur"=T21."MainCurncy" 
THEN 'Y' 
ELSE 'N' 
END AS "IsLocCurrency",
	 T0."DocRate" ,
	 T0."DiscPrcnt",
	 T2."SlpName",
	 T2."Email",
	 T1."LineNum",
	 T1."LineStatus",
	 T1."BaseType",
	 T1."BaseEntry",
	 T1."BaseLine",
	 T1."ItemCode",
	 T1."SubCatNum",
	 T1."Dscription",
	 T1."AcctCode",
	 T6."AcctName",
	 T9."ItmsGrpNam" ,
	 T1."Quantity",
	 T1."OpenQty",
	 T1."PickOty",
	 T1."PickIdNo",
	 T1."WhsCode",
	 T7."WhsName",
	 T1."ShipDate",
	 T1."VatGroup",
	 T1."VatPrcnt",
	 T1."Currency",
	 CASE WHEN T1."Currency"=T21."MainCurncy" 
THEN 'Y' 
ELSE 'N' 
END AS "LineIsLocCurrency",
	 T1."Rate",
	 CASE WHEN T0."DiscPrcnt"<>0 
THEN (1-T0."DiscPrcnt"/100)* T1."Price" 
ELSE T1."Price" 
END AS "Price",
	 CASE WHEN T0."DiscPrcnt"<>0 
THEN (1-T0."DiscPrcnt"/100)* T1."PriceAfVAT" 
ELSE T1."PriceAfVAT" 
END AS "PriceAfVAT",
	 CASE WHEN T0."DiscPrcnt"<>0 
THEN (1-T0."DiscPrcnt"/100)*T1."LineTotal" 
ELSE T1."LineTotal" 
END AS "LineTotal",
	 CASE WHEN T0."DiscPrcnt"<>0 
THEN (1-T0."DiscPrcnt"/100)*T1."GTotal" 
ELSE T1."GTotal" 
END AS "GTotal",
	 CASE WHEN T0."DiscPrcnt"<>0 
THEN (1-T0."DiscPrcnt"/100)*T1."TotalFrgn" 
ELSE T1."TotalFrgn" 
END AS "TotalFrgn",
	 CASE WHEN T0."DiscPrcnt"<>0 
THEN (1-T0."DiscPrcnt"/100)*T1."GTotalFC" 
ELSE T1."GTotalFC" 
END AS "GTotalFC",
	 CASE WHEN T0."DocCur"=T21."MainCurncy" 
AND T0."DiscPrcnt"<>0 
THEN (1-T0."DiscPrcnt"/100)*T1."Price"*T1."OpenQty" WHEN T0."DocCur"=T21."MainCurncy" 
AND T0."DiscPrcnt"=0 
THEN T1."Price"*T1."OpenQty" WHEN (T0."DocCur"<>T21."MainCurncy" 
	AND T1."Currency"<>T21."MainCurncy") 
AND T0."DiscPrcnt"<>0 
THEN (1-T0."DiscPrcnt"/100)*T1."Price"*T1."OpenQty"*T1."Rate" WHEN (T0."DocCur"<>T21."MainCurncy" 
	AND T1."Currency"<>T21."MainCurncy") 
AND T0."DiscPrcnt"=0 
THEN T1."Price"*T1."OpenQty"*T1."Rate" 
END AS "OpenLineTotal",
	 CASE WHEN T0."DocCur"=T21."MainCurncy" 
AND T0."DiscPrcnt"<>0 
THEN (1-T0."DiscPrcnt"/100)*T1."PriceAfVAT"*T1."OpenQty" WHEN T0."DocCur"=T21."MainCurncy" 
AND T0."DiscPrcnt"=0 
THEN T1."PriceAfVAT"*T1."OpenQty" WHEN (T0."DocCur"<>T21."MainCurncy" 
	AND T1."Currency"<>T21."MainCurncy") 
AND T0."DiscPrcnt"<>0 
THEN (1-T0."DiscPrcnt"/100)*T1."PriceAfVAT"*T1."OpenQty"*T1."Rate" WHEN (T0."DocCur"<>T21."MainCurncy" 
	AND T1."Currency"<>T21."MainCurncy") 
AND T0."DiscPrcnt"=0 
THEN T1."PriceAfVAT"*T1."OpenQty"*T1."Rate" 
END AS "OpenGTotal",
	 CASE WHEN T0."DocCur"<>T21."MainCurncy" 
AND T1."Currency"<>T21."MainCurncy" 
AND T0."DiscPrcnt"<>0 
THEN (1-T0."DiscPrcnt"/100)*T1."Price"*T1."OpenQty" WHEN T0."DocCur"<>T21."MainCurncy" 
AND T1."Currency"<>T21."MainCurncy" 
AND T0."DiscPrcnt"=0 
THEN T1."Price"*T1."OpenQty" 
END AS "OpenTotalFrgn",
	 CASE WHEN T0."DocCur"<>T21."MainCurncy" 
AND T1."Currency"<>T21."MainCurncy" 
AND T0."DiscPrcnt"<>0 
THEN (1-T0."DiscPrcnt"/100)*T1."PriceAfVAT"*T1."OpenQty" WHEN T0."DocCur"<>T21."MainCurncy" 
AND T1."Currency"<>T21."MainCurncy" 
AND T0."DiscPrcnt"=0 
THEN T1."PriceAfVAT"*T1."OpenQty" 
END AS "OpenGTotalFC",
	 T1."Project",
	 T13."PrjName",
	 T1."OcrCode",
	 T16."PrcName" AS "CostCenterName1",
	 T1."OcrCode2",
	 T17."PrcName" AS "CostCenterName2",
	 T1."OcrCode3",
	 T18."PrcName" AS "CostCenterName3",
	 T1."OcrCode4",
	 T19."PrcName" AS "CostCenterName4",
	 T1."OcrCode5",
	 T20."PrcName" AS "CostCenterName5",
	 T10."Code",
	 T10."Category",
	 T0."BPLId",
	 T22."BPLName" ,
	 T8."AvgPrice",
	 T8."LastPurPrc",
	 CASE WHEN T1."Currency"=T21."MainCurncy" 
then T0."GrosProfit" 
else T0."GrosProfFC" 
end as "GrosProfit",
	 CASE WHEN T1."Currency"=T21."MainCurncy" 
then T0."DocTotal" 
else T0."DocTotalFC" 
end as DocTotal 
FROM OQUT T0 
INNER JOIN QUT1 T1 ON T0."DocEntry"=T1."DocEntry" 
LEFT JOIN OSLP T2 ON T0."SlpCode"=T2."SlpCode" 
INNER JOIN OCRD T4 ON T0."CardCode"=T4."CardCode" 
LEFT JOIN OCRG T5 ON T4."GroupCode"=T5."GroupCode" 
LEFT JOIN OACT T6 ON T1."AcctCode"=T6."AcctCode" 
LEFT JOIN OWHS T7 ON T1."WhsCode"=T7."WhsCode" 
LEFT JOIN OITM T8 ON T1."ItemCode"=T8."ItemCode" 
LEFT JOIN OITB T9 ON T8."ItmsGrpCod"=T9."ItmsGrpCod" 
LEFT JOIN OFPR T10 ON T0."FinncPriod" = T10."AbsEntry" 
LEFT JOIN OTER T11 ON T4."Territory"=T11."territryID" 
LEFT JOIN OTER T12 ON T11."parent"=T12."territryID" 
LEFT JOIN OPRJ T13 ON T1."Project"=T13."PrjCode" 
LEFT JOIN OCTG T14 ON T14."GroupNum"= T0."GroupNum" 
LEFT JOIN (SELECT
	 "PrcCode",
	 "PrcName" 
	FROM OPRC 
	WHERE "DimCode"=1) T16 ON T1."OcrCode"=T16."PrcCode" 
LEFT JOIN (SELECT
	 "PrcCode",
	 "PrcName" 
	FROM OPRC 
	WHERE "DimCode"=2) T17 ON T1."OcrCode2"=T17."PrcCode" 
LEFT JOIN (SELECT
	 "PrcCode",
	 "PrcName" 
	FROM OPRC 
	WHERE "DimCode"=3) T18 ON T1."OcrCode3"=T18."PrcCode" 
LEFT JOIN (SELECT
	 "PrcCode",
	 "PrcName" 
	FROM OPRC 
	WHERE "DimCode"=4) T19 ON T1."OcrCode4"=T19."PrcCode" 
LEFT JOIN (SELECT
	 "PrcCode",
	 "PrcName" 
	FROM OPRC 
	WHERE "DimCode"=5) T20 ON T1."OcrCode5"=T20."PrcCode" 
LEFT JOIN OADM T21 ON 1=1 
LEFT JOIN OBPL T22 ON T0."BPLId"=T22."BPLId" 
INNER JOIN "AgentAll_USERRIGHT"(SESSION_CONTEXT('USERCODE')) TD ON TD.USERID=T0."UserSign" 
INNER JOIN "AgentAll_USERBPL"(SESSION_CONTEXT('USERCODE')) TB ON TB.BPLID=IFNULL(T22."BPLId",
	 0) 
WHERE T0.CANCELED='N'
;

CREATE VIEW "SBODEMOUS"."AgentAll_ORCT" AS
SELECT T0."DocNum", T0."DocType", T0."Canceled", T0."DocDate", T0."CardCode", T0."CardName", 
T0."Comments", T0."JrnlMemo", T0."TransId" , 
T0."DocCurr", 
 CASE WHEN T0."DocCurr"=T3."MainCurncy" THEN 'Y' ELSE 'N' END AS "IsLocCurrency",
T0."DocRate", T0."DocTotal", T0."DocTotalFC",
T0."CashSum",T0."CashSumFC",T0."CreditSum",T0."CredSumFC",
T0."CheckSum",T0."CheckSumFC",T0."TrsfrSum",T0."TrsfrSumFC",T0."NoDocSum",T0."NoDocSumFC",
T2."Code",
T2."Category",
T0."BPLId",
T1."BPLName" 
FROM ORCT T0
LEFT JOIN OBPL T1 ON T0."BPLId" = T1."BPLId"
LEFT JOIN OFPR T2 ON T0."FinncPriod" = T2."AbsEntry" 
LEFT JOIN OADM T3 ON T0."DocCurr"=T3."MainCurncy"
INNER JOIN "AgentAll_USERRIGHT"(SESSION_CONTEXT('USERCODE')) TD ON TD.USERID=T0."UserSign"
INNER JOIN "AgentAll_USERBPL"(SESSION_CONTEXT('USERCODE')) TB ON TB.BPLID=IFNULL(T0."BPLId",0)
;

CREATE VIEW "SBODEMOUS"."AgentAll_ORDN" AS
SELECT
 T0."DocNum",
 T0."DocEntry",
 T0."DocDate",
 T0."DocStatus",
 T0."DocType",
 T0."ObjType",
 T0."CardCode",
 T0."CardName",
 T5."GroupName",
 T11."descript" AS "Province",
 T12."descript" AS "Region",
 T0."DocCur",
 CASE WHEN T0."DocCur"=T14."MainCurncy" THEN 'Y' ELSE 'N' END AS "IsLocCurrency",
 T0."DocRate" ,
 T0."DiscPrcnt",
 T2."SlpName",
 T1."LineNum",
 T1."LineStatus",
 T1."BaseType",
 T1."BaseEntry",
 T1."BaseLine",
 T1."ItemCode",
 T1."SubCatNum",
 T1."Dscription",
 T1."AcctCode",
 T6."AcctName",
 T9."ItmsGrpNam" ,
 -T1."Quantity" AS "Quantity" ,
 T1."OpenCreQty",
 T1."WhsCode",
 T7."WhsName",
 T1."ShipDate",
 T1."VatGroup",
 T1."VatPrcnt",
 T1."Currency",
 CASE WHEN T1."Currency"=T14."MainCurncy" THEN 'Y' ELSE 'N' END AS "LineIsLocCurrency",
 T1."Rate",
 CASE WHEN  T0."DiscPrcnt"<>0 THEN (1-T0."DiscPrcnt"/100)* T1."Price" ELSE  T1."Price" END AS "Price", 
 CASE WHEN  T0."DiscPrcnt"<>0 THEN (1-T0."DiscPrcnt"/100)* T1."PriceAfVAT" ELSE  T1."PriceAfVAT" END AS "PriceAfVAT",
 CASE WHEN  T0."DiscPrcnt"<>0 THEN (1-T0."DiscPrcnt"/100)*T1."LineTotal" ELSE T1."LineTotal" END AS "LineTotal",
 CASE WHEN  T0."DiscPrcnt"<>0 THEN (1-T0."DiscPrcnt"/100)*T1."GTotal" ELSE T1."GTotal" END AS "GTotal",
 CASE WHEN  T0."DiscPrcnt"<>0 THEN (1-T0."DiscPrcnt"/100)*T1."TotalFrgn" ELSE T1."TotalFrgn" END AS "TotalFrgn",
 CASE WHEN  T0."DiscPrcnt"<>0 THEN (1-T0."DiscPrcnt"/100)*T1."GTotalFC" ELSE T1."GTotalFC" END AS "GTotalFC",
 T13."Reason",
  T1."Project",
 T21."PrjName",
 T1."OcrCode",
 T16."PrcName" AS "CostCenterName1",
 T1."OcrCode2",
 T17."PrcName" AS "CostCenterName2",
 T1."OcrCode3",
 T18."PrcName" AS "CostCenterName3",
 T1."OcrCode4",
 T19."PrcName" AS "CostCenterName4",
 T1."OcrCode5",
 T20."PrcName" AS "CostCenterName5",
 T10."Code",
 T10."Category" ,
 T0."BPLId",
 T15."BPLName"
FROM ORDN T0 
INNER JOIN RDN1 T1 ON T0."DocEntry"=T1."DocEntry" 
LEFT JOIN OSLP T2 ON T0."SlpCode"=T2."SlpCode" 
INNER JOIN OCRD T4 ON T0."CardCode"=T4."CardCode" 
LEFT JOIN OCRG T5 ON T4."GroupCode"=T5."GroupCode" 
LEFT JOIN OACT T6 ON T1."AcctCode"=T6."AcctCode"
LEFT JOIN OWHS T7 ON T1."WhsCode"=T7."WhsCode" 
LEFT JOIN OITM T8 ON T1."ItemCode"=T8."ItemCode" 
LEFT JOIN OITB T9 ON T8."ItmsGrpCod"=T9."ItmsGrpCod" 
LEFT JOIN OFPR T10 ON T0."FinncPriod" = T10."AbsEntry" 
LEFT JOIN OTER T11 ON T4."Territory"=T11."territryID" 
LEFT JOIN OTER T12 ON T11."parent"=T12."territryID" 
LEFT JOIN ORER T13 ON T1."ReturnRsn"=T13."AbsEntry" 
LEFT JOIN OADM T14 ON T0."DocCur"=T14."MainCurncy"
LEFT JOIN OBPL T15 ON T0."BPLId"=T15."BPLId"
LEFT  JOIN  (SELECT "PrcCode","PrcName" FROM  OPRC WHERE "DimCode"=1) T16 ON T1."OcrCode"=T16."PrcCode"
LEFT  JOIN  (SELECT "PrcCode","PrcName" FROM  OPRC WHERE "DimCode"=2) T17 ON T1."OcrCode2"=T17."PrcCode"
LEFT  JOIN  (SELECT "PrcCode","PrcName" FROM  OPRC WHERE "DimCode"=3) T18 ON T1."OcrCode3"=T18."PrcCode"
LEFT  JOIN  (SELECT "PrcCode","PrcName" FROM  OPRC WHERE "DimCode"=4) T19 ON T1."OcrCode4"=T19."PrcCode"
LEFT  JOIN  (SELECT "PrcCode","PrcName" FROM  OPRC WHERE "DimCode"=5) T20 ON T1."OcrCode5"=T20."PrcCode"
LEFT JOIN OPRJ T21 ON T1."Project" =T21."PrjCode"
INNER JOIN "AgentAll_USERRIGHT"(SESSION_CONTEXT('USERCODE')) TD ON TD.USERID=T0."UserSign"
INNER JOIN "AgentAll_USERBPL"(SESSION_CONTEXT('USERCODE')) TB ON TB.BPLID=IFNULL(T0."BPLId",0)
WHERE T0.CANCELED='N'
;

