CREATE VIEW "SBODEMOUS"."AgentAll_OSPP" AS
SELECT 
T0."ItemCode", 
T2."ItemName",
T3."ItmsGrpNam",
T0."CardCode", 
T4."CardName",
T5."GroupName",
T4."CardType",
T0."Price", 
T0."Currency", 
T0."Valid", 
T0."ValidFrom", 
T0."ValidTo" 
FROM OSPP T0
LEFT JOIN OITM T2 ON T0."ItemCode"=T2."ItemCode"
LEFT JOIN OITB T3 ON T2."ItmsGrpCod"=T3."ItmsGrpCod"
LEFT JOIN OCRD T4 ON T0."CardCode"=T4."CardCode"
LEFT JOIN OCRG T5 ON T4."GroupCode"=T5."GroupCode"
;

CREATE VIEW "SBODEMOUS"."AgentAll_OVPM" AS
SELECT T0."DocNum", T0."DocType", T0."Canceled", T0."DocDate", T0."CardCode", T0."CardName", 
T0."Comments", T0."JrnlMemo", T0."TransId" , 
T0."DocCurr", 
 CASE WHEN T0."DocCurr"=T3."MainCurncy" THEN 'Y' ELSE 'N' END AS "IsLocCurrency",
T0."DocRate", T0."DocTotal", T0."DocTotalFC",
T0."CashSum",T0."CashSumFC",T0."CreditSum",T0."CredSumFC",
T0."CheckSum",T0."CheckSumFC",T0."TrsfrSum",T0."TrsfrSumFC",T0."NoDocSum",T0."NoDocSumFC",
T2."Code",
T2."Category",
T0."BPLId",
T1."BPLName" 
FROM OVPM T0
LEFT JOIN OBPL T1 ON T0."BPLId" = T1."BPLId"
LEFT JOIN OFPR T2 ON T0."FinncPriod" = T2."AbsEntry" 
LEFT JOIN OADM T3 ON T0."DocCurr"=T3."MainCurncy" 
INNER JOIN "AgentAll_USERRIGHT"(SESSION_CONTEXT('USERCODE')) TD ON TD.USERID=T0."UserSign"
INNER JOIN "AgentAll_USERBPL"(SESSION_CONTEXT('USERCODE')) TB ON TB.BPLID=IFNULL(T0."BPLId",0)
;

CREATE VIEW "SBODEMOUS"."AgentAll_OWDD" AS
SELECT  
    T0."WddCode",
    T0."WtmCode", 
    T0."OwnerID", 
    T0."ObjType", 
    T0."DocDate", 
    T0."CurrStep", 
    T0."Status", 
    T0."Remarks", 
    T0."UserSign", 
    T0."CreateDate", 
    T0."CreateTime", 
    T0."IsDraft", 
    T0."DraftType", 
    T0."DraftEntry", 
    T0."ProcessID", 
    T0."ProcesStat", 
    T0."StpUpdated", 
    T0."DocEntry",
    T2."Email",
    T2."SlpName",
    T1."WddStatus"
FROM "OWDD" T0
INNER JOIN "ODRF" T1 
    ON T0."DraftType" = '112' 
    AND T0."DraftEntry" = T1."DocEntry"
INNER JOIN "WDD1" TW 
    ON TW."WddCode" = T0."WddCode" 
    AND TW."StepCode" = T0."CurrStep"
INNER JOIN "OSLP" T2 
    ON T2."SlpCode" = T1."SlpCode"
WHERE T0."DocEntry" IS NULL 
    AND T1."WddStatus" IN ('Y', 'N')
    AND T0."Status" = 'Y'
;

CREATE VIEW "SBODEMOUS"."AgentAll_OWHS" AS
SELECT
    T0."WhsCode",
    T0."WhsName",
    T0."Inactive",
    T1."Location",
 T0."DropShip",
 T0."NegStckAct",
 T0."BinActivat",
    T0."createDate",
    T0."updateDate"
FROM "OWHS" T0
LEFT JOIN OLCT T1 ON T0."Location"=T1."Code"
;

CREATE VIEW "SBODEMOUS"."AgentAll_OWOR" AS
SELECT 
    T0."DocNum", 
    T0."PostDate", 
    T0."StartDate",
    T0."DueDate", 
    T0."CloseDate", 
    T0."RlsDate",
    CASE 
        WHEN T0."OriginType" = 'S' THEN 'Sales'
        WHEN T0."OriginType" = 'M' THEN 'Production' 
        WHEN T0."OriginType" = 'R' THEN 'MRP' 
    END AS "OriginType",
    T0."OriginNum",
    T0."CardCode",
    T2."CardName", 
    CASE 
        WHEN T0."Type" = 'S' THEN 'Standard'
        WHEN T0."Type" = 'P' THEN 'Special' 
        WHEN T0."Type" = 'D' THEN 'Disassembly' 
    END AS "Type", 
    CASE 
        WHEN T0."Status" = 'L' THEN 'Closed'
        WHEN T0."Status" = 'P' THEN 'Planned' 
        WHEN T0."Status" = 'R' THEN 'Released' 
        WHEN T0."Status" = 'C' THEN 'Canceled' 
    END AS "Status", 
    T0."Priority",
    T0."ItemCode", 
    T3."ItemName", 
    T4."ItmsGrpNam",
    T0."Warehouse",
    T1."WhsName",
    T0."PlannedQty",
    T0."CmpltQty",
    T0."RjctQty",
    T0."Project",
    T8."BPLName",
    T0."OcrCode",
    T10."PrcName" AS "CostCenterName1",
    T0."OcrCode2",
    T11."PrcName" AS "CostCenterName2",
    T0."OcrCode3",
    T12."PrcName" AS "CostCenterName3",
    T0."OcrCode4",
    T13."PrcName" AS "CostCenterName4",
    T0."OcrCode5",
    T14."PrcName" AS "CostCenterName5",
    T1."BPLid",
    T5."PrjName"
FROM OWOR T0 
LEFT JOIN OWHS T1 ON T0."Warehouse" = T1."WhsCode"
LEFT JOIN OCRD T2 ON T0."CardCode" = T2."CardCode"
LEFT JOIN OITM T3 ON T0."ItemCode" = T3."ItemCode"
LEFT JOIN OITB T4 ON T3."ItmsGrpCod" = T4."ItmsGrpCod"
LEFT JOIN OPRJ T5 ON T0."Project" = T5."PrjCode"
LEFT JOIN OBPL T8 ON T1."BPLid" = T8."BPLId"
LEFT JOIN (SELECT "PrcCode", "PrcName" FROM "OPRC" WHERE "DimCode" = 1) T10 ON T0."OcrCode" = T10."PrcCode"
LEFT JOIN (SELECT "PrcCode", "PrcName" FROM "OPRC" WHERE "DimCode" = 2) T11 ON T0."OcrCode2" = T11."PrcCode"
LEFT JOIN (SELECT "PrcCode", "PrcName" FROM "OPRC" WHERE "DimCode" = 3) T12 ON T0."OcrCode3" = T12."PrcCode"
LEFT JOIN (SELECT "PrcCode", "PrcName" FROM "OPRC" WHERE "DimCode" = 4) T13 ON T0."OcrCode4" = T13."PrcCode"
LEFT JOIN (SELECT "PrcCode", "PrcName" FROM "OPRC" WHERE "DimCode" = 5) T14 ON T0."OcrCode5" = T14."PrcCode"
INNER JOIN "AgentAll_USERRIGHT"(SESSION_CONTEXT('USERCODE')) TD ON TD.USERID=T0."UserSign"
INNER JOIN "AgentAll_USERBPL"(SESSION_CONTEXT('USERCODE')) TB ON TB.BPLID=IFNULL(T8."BPLId",0)
;

CREATE VIEW "SBODEMOUS"."AgentAll_OWORCost" AS
SELECT
	 T0."DocNum",
	 T0."Status",
	 T0."OriginNum" ,
	 T0. "PostDate",
	 T0."Warehouse",
	 T6."WhsName",
	 T0."ItemCode",
	 T0."ProdName",
	 T0."PlannedQty",
	 T1."ProdQuantity",
	 CASE WHEN IFNULL(T1."ProdQuantity",
	0)>IFNULL(T0."PlannedQty",
	0) 
THEN '***' 
ELSE '' 
END AS "OverRecFlag",
	 T1."ProdTotalLC" ,
	 T1."ProdTotalLC"/T1."ProdQuantity" AS "PerProdTotalLC",
	 T2."ChidTotalLC" ,
	 T3."ResuTotalLC" ,
	 T4."AddtTotalLC",
	 IFNULL(T2."ChidTotalLC",
	0)+IFNULL(T3."ResuTotalLC" ,
	0)+IFNULL(T4."AddtTotalLC",
	0) AS "TotalCostFC",
	 T5."DiffTotalLC",
	 T0."Project",
	 T9."PrjName",
	 T0."OcrCode",
	 T10."PrcName" AS "CostCenterName1",
	 T0."OcrCode2",
	 T11."PrcName" AS "CostCenterName2",
	 T0."OcrCode3",
	 T12."PrcName" AS "CostCenterName3",
	 T0."OcrCode4",
	 T13."PrcName" AS "CostCenterName4",
	 T0."OcrCode5",
	 T14."PrcName" AS "CostCenterName5",
	 T6."BPLid",
	 T8."BPLName" 
FROM "OWOR" T0 
LEFT JOIN (SELECT
	 "WOR",
	SUM("Quantity") AS "ProdQuantity",
	SUM("TotalLC") AS "ProdTotalLC" 
	FROM "B1_ProductionContributionView" 
	WHERE "AppObjType"='P' 
	AND "TransType"=59 
	GROUP BY "WOR" ) T1 ON T0."DocEntry" = T1."WOR" 
LEFT JOIN (SELECT
	 "WOR",
	-SUM("TotalLC") AS "ChidTotalLC" 
	FROM "B1_ProductionContributionView" 
	WHERE "AppObjType"='C' 
	AND "ItemType"=4 
	AND "IsInventory"='Y' 
	AND "TransType"=60 
	GROUP BY "WOR" ) T2 ON T0."DocEntry" = T2."WOR" 
LEFT JOIN (SELECT
	 "WOR",
	-SUM("TotalLC") AS "ResuTotalLC" 
	FROM "B1_ProductionContributionView" 
	WHERE "AppObjType"='C' 
	AND "ItemType"=290 
	AND "IsInventory"='N' 
	AND "TransType"=60 
	GROUP BY "WOR" ) T3 ON T0."DocEntry" = T3."WOR" 
LEFT JOIN (SELECT
	 "WOR",
	-SUM("TotalLC") AS "AddtTotalLC" 
	FROM "B1_ProductionContributionView" 
	WHERE "AppObjType"='C' 
	AND "ItemType"=4 
	AND "IsInventory"='N' 
	AND "TransType"=202 
	GROUP BY "WOR" ) T4 ON T0."DocEntry" = T4."WOR" 
LEFT JOIN (SELECT
	 "WOR",
	-SUM("TotalLC") AS "DiffTotalLC" 
	FROM "B1_ProductionContributionView" 
	WHERE "AppObjType"='W' 
	GROUP BY "WOR" ) T5 ON T0."DocEntry" = T5."WOR" 
LEFT JOIN "OWHS" T6 ON T0."Warehouse"=T6."WhsCode" 
LEFT JOIN OBPL T8 ON T6."BPLid"=T8."BPLId" 
LEFT JOIN OPRJ T9 ON T0."Project"=T9."PrjCode" 
LEFT JOIN (SELECT
	 "PrcCode",
	"PrcName" 
	FROM OPRC 
	WHERE "DimCode"=1) T10 ON T0."OcrCode"=T10."PrcCode" 
LEFT JOIN (SELECT
	 "PrcCode",
	"PrcName" 
	FROM OPRC 
	WHERE "DimCode"=2) T11 ON T0."OcrCode2"=T11."PrcCode" 
LEFT JOIN (SELECT
	 "PrcCode",
	"PrcName" 
	FROM OPRC 
	WHERE "DimCode"=3) T12 ON T0."OcrCode3"=T12."PrcCode" 
LEFT JOIN (SELECT
	 "PrcCode",
	"PrcName" 
	FROM OPRC 
	WHERE "DimCode"=4) T13 ON T0."OcrCode4"=T13."PrcCode" 
LEFT JOIN (SELECT
	 "PrcCode",
	"PrcName" 
	FROM OPRC 
	WHERE "DimCode"=5) T14 ON T0."OcrCode5"=T14."PrcCode" 
INNER JOIN "AgentAll_USERRIGHT"(SESSION_CONTEXT('USERCODE')) TD ON TD.USERID=T0."UserSign" 
INNER JOIN "AgentAll_USERBPL"(SESSION_CONTEXT('USERCODE')) TB ON TB.BPLID=IFNULL(T8."BPLId",
	0) 
WHERE T0."Status"='L'
;

CREATE VIEW "SBODEMOUS"."AgentAll_OWORDetail" AS
SELECT 
    T0."DocNum", 
    T0."PostDate", 
    T0."StartDate",
    T0."DueDate",
    CASE 
        WHEN T0."Type" = 'S' THEN 'Standard'
        WHEN T0."Type" = 'P' THEN 'Special'  
        WHEN T0."Type" = 'D' THEN 'Disassembly'  
    END AS "Type", 
    CASE 
        WHEN T0."Status" = 'L' THEN 'Closed'
        WHEN T0."Status" = 'P' THEN 'Planned'  
        WHEN T0."Status" = 'R' THEN 'Released'  
        WHEN T0."Status" = 'C' THEN 'Canceled' 
    END AS "Status", 
    T0."ItemCode", 
    T2."ItemName",
    T1."ItemCode" AS "ChildItemCode",
    T3."ItemName" AS "ChildItemName",
    T4."ItmsGrpNam" AS "ChildItemGrp",
    T1."wareHouse",
    T5."WhsName",
    T1."BaseQty",
    T1."PlannedQty",
    T1."AdditQty",
    T1."IssuedQty", 
    CASE 
        WHEN T1."PlannedQty" > 0 AND T1."PlannedQty" - T1."IssuedQty" < 0 
        THEN T1."IssuedQty" - T1."PlannedQty" 
        ELSE 0 
    END AS "OverIssuedQty",
    CASE 
        WHEN T1."PlannedQty" > 0 AND T1."PlannedQty" - T1."IssuedQty" < 0 
        THEN ' ***'  
        ELSE ' ' 
    END AS "OverIssuedFlag",
    CASE 
        WHEN T1."IssueType" = 'M' THEN 'Manual'
        ELSE 'Backflush' 
    END AS "IssueType", 
    CASE 
        WHEN T0."Type" <> 'D' AND T0."Status" <> 'L' 
        THEN T1."PlannedQty" - T1."IssuedQty" 
        ELSE 0 
    END AS "ShortageQty",
    T6."OnHand",
    T6."OnHand" + T6."OnOrder" - T6."IsCommited" AS "AvailableQty",
    T7."BPLid",
    T8."BPLName"
FROM OWOR T0 
LEFT JOIN WOR1 T1 ON T0."DocEntry" = T1."DocEntry"
LEFT JOIN OITM T2 ON T0."ItemCode" = T2."ItemCode"
LEFT JOIN OITM T3 ON T1."ItemCode" = T3."ItemCode"
LEFT JOIN OITB T4 ON T3."ItmsGrpCod" = T4."ItmsGrpCod"
LEFT JOIN OWHS T5 ON T1."wareHouse" = T5."WhsCode"
LEFT JOIN OITW T6 ON T1."wareHouse" = T6."WhsCode" AND T1."ItemCode" = T6."ItemCode"
LEFT JOIN OWHS T7 ON T0."Warehouse" = T7."WhsCode"
LEFT JOIN OBPL T8 ON T7."BPLid" = T8."BPLId"
INNER JOIN "AgentAll_USERRIGHT"(SESSION_CONTEXT('USERCODE')) TD ON TD.USERID=T0."UserSign"
INNER JOIN "AgentAll_USERBPL"(SESSION_CONTEXT('USERCODE')) TB ON TB.BPLID=IFNULL(T8."BPLId",0)
;

CREATE VIEW "SBODEMOUS"."AgentAll_OWTQ" AS
SELECT 
T0."DocNum", 
T0."DocDate", 
T0."Comments", 
T0."CardCode", 
T0."CardName", 
T11."GroupName", 
T0."Address", 
T7."Name" AS "CntctName", 
T1."ObjType", 
T1."BaseType",
T1."BaseEntry",
T1."BaseLine", 
T1."ItemCode", 
T1."Dscription", 
T5."ItmsGrpNam", 
T1."Quantity", 
T1."Price", 
T1."LineTotal", 
T1."FromWhsCod", 
T8."WhsName" AS "FromWhsName", 
T1."WhsCode" AS "ToWhsCode", 
T9."WhsName" AS "ToWhsName", 
T1."Currency", 
CASE WHEN T0."DocCur" = T2."MainCurncy" THEN 'Y' ELSE 'N' END AS "IsLocCurrency", 
T1."Project",
T15."PrjName",
T1."OcrCode",
T16."PrcName" AS "CostCenterName1",
T1."OcrCode2",
T17."PrcName" AS "CostCenterName2",
T1."OcrCode3",
T18."PrcName" AS "CostCenterName3",
T1."OcrCode4",
T19."PrcName" AS "CostCenterName4",
T1."OcrCode5",
T20."PrcName" AS "CostCenterName5",
T6."Code", 
T6."Category",
T0."BPLId", 
T3."BPLName"
FROM "OWTQ" T0
LEFT JOIN "WTQ1" T1 ON T0."DocEntry" = T1."DocEntry"
LEFT JOIN "OADM" T2 ON T0."DocCur" = T2."MainCurncy"
LEFT JOIN "OBPL" T3 ON T0."BPLId" = T3."BPLId"
LEFT JOIN "OITM" T4 ON T1."ItemCode" = T4."ItemCode"
LEFT JOIN "OITB" T5 ON T4."ItmsGrpCod" = T5."ItmsGrpCod"
LEFT JOIN "OFPR" T6 ON T0."FinncPriod" = T6."AbsEntry" 
LEFT JOIN "OCPR" T7 ON T0."CardCode" = T7."CardCode" AND T0."CntctCode" = T7."CntctCode"
LEFT JOIN "OWHS" T8 ON T1."FromWhsCod" = T8."WhsCode"
LEFT JOIN "OWHS" T9 ON T1."WhsCode" = T9."WhsCode"
LEFT JOIN "OCRD" T10 ON T0."CardCode" = T10."CardCode" 
LEFT JOIN "OCRG" T11 ON T10."GroupCode" = T11."GroupCode" 
LEFT JOIN OPRJ T15 ON T1."Project" =T15."PrjCode"
LEFT  JOIN  (SELECT "PrcCode","PrcName" FROM  OPRC WHERE "DimCode"=1) T16 ON T1."OcrCode"=T16."PrcCode"
LEFT  JOIN  (SELECT "PrcCode","PrcName" FROM  OPRC WHERE "DimCode"=2) T17 ON T1."OcrCode2"=T17."PrcCode"
LEFT  JOIN  (SELECT "PrcCode","PrcName" FROM  OPRC WHERE "DimCode"=3) T18 ON T1."OcrCode3"=T18."PrcCode"
LEFT  JOIN  (SELECT "PrcCode","PrcName" FROM  OPRC WHERE "DimCode"=4) T19 ON T1."OcrCode4"=T19."PrcCode"
LEFT  JOIN  (SELECT "PrcCode","PrcName" FROM  OPRC WHERE "DimCode"=5) T20 ON T1."OcrCode5"=T20."PrcCode"
INNER JOIN "AgentAll_USERRIGHT"(SESSION_CONTEXT('USERCODE')) TD ON TD.USERID=T0."UserSign"
INNER JOIN "AgentAll_USERBPL"(SESSION_CONTEXT('USERCODE')) TB ON TB.BPLID=IFNULL(T0."BPLId",0)
WHERE T0.CANCELED='N'
;

