T0."CardName", 
T11."GroupName", 
T0."Address", 
T7."Name" AS "CntctName", 
T1."ObjType", 
T1."BaseType",
T1."BaseEntry",
T1."BaseLine", 
T1."ItemCode", 
T1."Dscription", 
T5."ItmsGrpNam", 
T1."Quantity", 
T1."Price", 
T1."LineTotal", 
T1."FromWhsCod", 
T8."WhsName" AS "FromWhsName", 
T1."WhsCode" AS "ToWhsCode", 
T9."WhsName" AS "ToWhsName", 
T1."Currency", 
CASE WHEN T0."DocCur" = T2."MainCurncy" THEN 'Y' ELSE 'N' END AS "IsLocCurrency", 
T1."Project",
T15."PrjName",
T1."OcrCode",
T16."PrcName" AS "CostCenterName1",
