CREATE VIEW "SBODEMOUS"."AgentAll_PurchaseTimelyDelRate" AS
SELECT 
    "T0"."DocNum",
    "T0"."DocEntry",
    "T0"."DocDate",
    "T0"."DocStatus",
    "T0"."CardCode",
    "T0"."CardName",
    "T5"."GroupName",
    "T2"."SlpName",
    "T1"."TargetType",
    "T1"."LineStatus",
    "T1"."LinManClsd", 
    "T1"."LineNum",
    "T1"."ItemCode",
    "T1"."SubCatNum",
    "T1"."Dscription",
    "T9"."ItmsGrpNam",
    "T1"."Quantity",
    "T1"."OpenQty",
    "T7"."WhsName",
    "T1"."ShipDate",
    "T15"."TimelyDelQty",
    "T16"."DelayedDelQty",
    "T10"."Code",
    "T10"."Category",
    "T0"."BPLId",
    "T14"."BPLName"
FROM "OPOR" "T0" 
INNER JOIN "POR1" "T1" ON "T0"."DocEntry"="T1"."DocEntry" 
LEFT JOIN "OSLP" "T2" ON "T0"."SlpCode"="T2"."SlpCode" 
INNER JOIN "OCRD" "T4" ON "T0"."CardCode"="T4"."CardCode" 
LEFT JOIN "OCRG" "T5" ON "T4"."GroupCode"="T5"."GroupCode" 
INNER JOIN "OWHS" "T7" ON "T1"."WhsCode"="T7"."WhsCode" 
INNER JOIN "OITM" "T8" ON "T1"."ItemCode"="T8"."ItemCode" 
LEFT JOIN "OITB" "T9" ON "T8"."ItmsGrpCod"="T9"."ItmsGrpCod" 
LEFT JOIN "OFPR" "T10" ON "T0"."FinncPriod" = "T10"."AbsEntry" 
LEFT JOIN "OBPL" "T14" ON "T0"."BPLId"="T14"."BPLId"
INNER JOIN "AgentAll_USERRIGHT"(SESSION_CONTEXT('USERCODE')) TD ON TD.USERID=T0."UserSign"
INNER JOIN "AgentAll_USERBPL"(SESSION_CONTEXT('USERCODE')) TB ON TB.BPLID=IFNULL(T0."BPLId",0)
LEFT JOIN (
    SELECT 
        "T3"."DocEntry",
        "T3"."LineNum",
        "T3"."ItemCode",
        SUM("T1"."Quantity") AS "TimelyDelQty"
    FROM "PDN1" "T1"
    LEFT JOIN "OPDN" "T2" ON "T2"."DocEntry"="T1"."DocEntry"
    LEFT JOIN "POR1" "T3" ON "T3"."DocEntry"="T1"."BaseEntry" AND "T3"."LineNum"="T1"."BaseLine"
    WHERE "T1"."BaseType"=22 AND "T2"."CANCELED"='N' AND "T2"."DocDate"<="T3"."ShipDate"
    GROUP BY "T3"."DocEntry", "T3"."LineNum", "T3"."ItemCode"
) "T15" ON "T1"."DocEntry"="T15"."DocEntry" AND "T1"."LineNum"="T15"."LineNum"

LEFT JOIN (
    SELECT 
        "T3"."DocEntry",
        "T3"."LineNum",
        "T3"."ItemCode",
        SUM("T1"."Quantity") AS "DelayedDelQty"
    FROM "PDN1" "T1"
    LEFT JOIN "OPDN" "T2" ON "T2"."DocEntry"="T1"."DocEntry"
    LEFT JOIN "POR1" "T3" ON "T3"."DocEntry"="T1"."BaseEntry" AND "T3"."LineNum"="T1"."BaseLine"
    WHERE "T1"."BaseType"=22 AND "T2"."CANCELED"='N' AND "T2"."DocDate">"T3"."ShipDate"
    GROUP BY "T3"."DocEntry", "T3"."LineNum", "T3"."ItemCode"
) "T16" ON "T1"."DocEntry"="T16"."DocEntry" AND "T1"."LineNum"="T16"."LineNum"

WHERE "T0"."CANCELED"='N' 
AND "T0"."DocType"='I' 
AND CAST("T1"."DocEntry" AS NVARCHAR)||CAST("T1"."LineNum" AS NVARCHAR)||"T1"."ItemCode" 
NOT IN (
    SELECT CAST("DocEntry" AS NVARCHAR)||CAST("LineNum" AS NVARCHAR)||"ItemCode" 
    FROM "POR1" 
    WHERE "LinManClsd"='Y' AND "TargetType"='-1' AND "LineStatus"='C'
)
;

CREATE VIEW "SBODEMOUS"."AgentAll_STOCK" AS
SELECT
  T0."ItemCode",
  T0."ItemName",
  T0."ItmsGrpCod",
  T0."ByWh",
  T0."MinLevel",
  T3."ItmsGrpNam",
  T1."WhsCode",
  T2."WhsName",
  T1."OnHand",
  T1."OnOrder",
  T1."IsCommited" ,
  T1."OnHand"+T1."OnOrder"-T1."IsCommited" AS "Available",
  T1."AvgPrice" ,
  T1."MinStock",
  T2."BPLid",
  T4."BPLName"
FROM OITM T0 
INNER JOIN OITW T1 ON T0."ItemCode" = T1."ItemCode" 
LEFT JOIN OWHS T2 ON T1."WhsCode" = T2."WhsCode" 
LEFT JOIN OITB T3 ON T0."ItmsGrpCod" = T3."ItmsGrpCod" 
LEFT JOIN OBPL T4 ON T2."BPLid"=T4."BPLId"
INNER JOIN "AgentAll_USERRIGHT"(SESSION_CONTEXT('USERCODE')) TD ON TD.USERID=T0."UserSign"
INNER JOIN "AgentAll_USERBPL"(SESSION_CONTEXT('USERCODE')) TB ON TB.BPLID=IFNULL(T4."BPLId",0)
WHERE T0."ItemType" ='I'
;

CREATE VIEW "SBODEMOUS"."AgentAll_SalesRevenueCost" AS
(((((((((SELECT 'Direct A/R Invoice' AS "TransType",T0."DocType",T0."DocNum",T0."CardCode",T0."CardName",T23."GroupName"
,T26."descript" AS "Province", T27."descript" AS "Region",T0."NumAtCard",T28."SlpName",T0."Comments"
,T1."BaseType",T1."BaseEntry",T1."BaseLine",null AS "SONumber",null AS "SODocDate"
,T1."ItemCode",T1."Dscription",T25."ItmsGrpNam" ,T1."LineTotal",T20."CogsVal" AS "SalesCost",null AS "isIns"
,T1."Project" ,T17."PrjName" ,
T1."OcrCode",T10."PrcName" AS "CostCenterName1",
T1."OcrCode2",T11."PrcName" AS "CostCenterName2",
T1."OcrCode3",T12."PrcName" AS "CostCenterName3",
T1."OcrCode4",T13."PrcName" AS "CostCenterName4",
T1."OcrCode5",T14."PrcName" AS "CostCenterName5",
T16."Code",T16."Category",T0."BPLId",T21."BPLName"
FROM "OINV" T0
INNER JOIN "INV1" T1 ON T0."DocEntry"=T1."DocEntry"
INNER JOIN OCRD T22 ON T0."CardCode"=T22."CardCode" 
LEFT JOIN OCRG T23 ON T22."GroupCode"=T23."GroupCode" 
LEFT JOIN OITM T24 ON T1."ItemCode"=T24."ItemCode" 
LEFT JOIN OITB T25 ON T24."ItmsGrpCod"=T25."ItmsGrpCod" 
LEFT JOIN OTER T26 ON T22."Territory"=T26."territryID" 
LEFT JOIN OTER T27 ON T26."parent"=T27."territryID" 
LEFT JOIN OSLP T28 ON T0."SlpCode"=T28."SlpCode" 
LEFT  JOIN  (SELECT "PrcCode","PrcName" FROM  OPRC WHERE "DimCode"=1) T10 ON T1."OcrCode"=T10."PrcCode"
LEFT  JOIN  (SELECT "PrcCode","PrcName" FROM  OPRC WHERE "DimCode"=2) T11 ON T1."OcrCode2"=T11."PrcCode"
LEFT  JOIN  (SELECT "PrcCode","PrcName" FROM  OPRC WHERE "DimCode"=3) T12 ON T1."OcrCode3"=T12."PrcCode"
LEFT  JOIN  (SELECT "PrcCode","PrcName" FROM  OPRC WHERE "DimCode"=4) T13 ON T1."OcrCode4"=T13."PrcCode"
LEFT  JOIN  (SELECT "PrcCode","PrcName" FROM  OPRC WHERE "DimCode"=5) T14 ON T1."OcrCode5"=T14."PrcCode"
LEFT JOIN "OFPR"  T16 ON T0."FinncPriod" = T16."AbsEntry" 
LEFT JOIN "OPRJ"  T17 ON T1."Project" = T17."PrjCode" 
LEFT JOIN (SELECT * FROM "OINM" WHERE "TransType"=13) T20 ON T0."DocNum"=T20."BASE_REF"  AND T1."LineNum"=T20."DocLineNum"
LEFT JOIN OBPL T21 ON T0."BPLId"=T21."BPLId"
INNER JOIN "AgentAll_USERRIGHT"(SESSION_CONTEXT('USERCODE')) TD ON TD.USERID=T0."UserSign"
INNER JOIN "AgentAll_USERBPL"(SESSION_CONTEXT('USERCODE')) TB ON TB.BPLID=IFNULL(T0."BPLId",0)
WHERE   T1."BaseType"='-1') UNION ALL (SELECT 'A/R Invoice based on Delivery' AS "TransType",T0."DocType",T0."DocNum",T0."CardCode",T0."CardName",T23."GroupName"
,T26."descript" AS "Province", T27."descript" AS "Region",T0."NumAtCard",T28."SlpName",T0."Comments"
,T1."BaseType",T1."BaseEntry",T1."BaseLine",T4."DocNum" AS "SONumber",T4."DocDate" AS "SODocDate"
,T1."ItemCode",T1."Dscription",T25."ItmsGrpNam" ,T1."LineTotal",T20."CogsVal" AS "SalesCost",null AS "isIns"
,T1."Project" ,T17."PrjName" ,
T1."OcrCode",T10."PrcName" AS "CostCenterName1",
T1."OcrCode2",T11."PrcName" AS "CostCenterName2",
T1."OcrCode3",T12."PrcName" AS "CostCenterName3",
T1."OcrCode4",T13."PrcName" AS "CostCenterName4",
T1."OcrCode5",T14."PrcName" AS "CostCenterName5",
T16."Code",T16."Category",T0."BPLId",T21."BPLName"
FROM "OINV" T0
INNER JOIN "INV1" T1 ON T0."DocEntry"=T1."DocEntry"
LEFT JOIN "DLN1" T2 ON T1."BaseEntry"=T2."DocEntry" AND  T1."BaseLine"=T2."LineNum"
LEFT JOIN "ODLN" TN ON TN."DocEntry"=T2."DocEntry" 
LEFT JOIN "RDR1" T3 ON T2."BaseEntry"=T3."DocEntry" AND  T2."BaseLine"=T3."LineNum"
LEFT JOIN "ORDR" T4 ON T3."DocEntry"=T4."DocEntry" 
