						WHEN 'N' THEN
							(T0."DocTotal" - T0."PaidToDate")
						WHEN 'Y' THEN
							0
					END
			 END								AS "Credit",
			 CASE T0."ObjType"
				WHEN '20' THEN
					'EF'
				WHEN '21' THEN
					'EF'
				WHEN '19' THEN
					'EF'
				WHEN '16' THEN
					'SF'
				WHEN '14' THEN
					'SF'
			 END								AS "Group",
			 0									AS "PredictFlag",
			 T3."AvrageLate",
			 CASE T0."ObjType"
				WHEN '20' THEN
					IFNULL(T2."HldCode", '')
				WHEN '21' THEN
					IFNULL(T2."HldCode", '')
				WHEN '19' THEN
					IFNULL(T2."HldCode", '')
				WHEN '16' THEN
					IFNULL(T3."HldCode", '')
				WHEN '14' THEN
					IFNULL(T3."HldCode", '')
			 END								AS "HldCode"
	    FROM "ODRF" T0
   LEFT JOIN "ORCP" T1
