	         T0."TaxDate", 
	         T0."ClsDate", 
	         T0."PayDuMonth", 
	         T0."ExtraMonth", 
	         T0."ExtraDays", 
			 0									AS "TolDays", 
	         T0."GroupNum",  
			 T2."InstlmntID"					AS "InstID", 
			 IFNULL(T0."Installmnt", 0)			AS "InstNum", 
			 0                            		AS "InstMonth", 
			 0                            		AS "InstDays", 
			 100								AS "InstPrcnt", 
			 T0."Installmnt",
	         T2."DueDate"						AS "DocDueDate", 
			 CASE	T0."ObjType" 
				WHEN '204' THEN
					0
				WHEN '18' THEN
					0
				WHEN '163' THEN
					CASE T3."NegAmount" 
						WHEN 'N' THEN
							(T2."InsTotal" - T2."PaidToDate")
						WHEN 'Y' THEN
							0
					END
				WHEN '164' THEN
					0
				WHEN '203' THEN
					(T2."InsTotal" - T2."PaidToDate")
				WHEN '13' THEN
					(T2."InsTotal" - T2."PaidToDate")
				WHEN '165' THEN
					CASE T3."NegAmount" 
						WHEN 'N' THEN
							0
						WHEN 'Y' THEN
							0 - (T2."InsTotal" - T2."PaidToDate")
					END
				WHEN '166' THEN
					(T2."InsTotal" - T2."PaidToDate")
			 END								AS	"Debit",
			 CASE	T0."ObjType"
				WHEN '204' THEN
					(T2."InsTotal" - T2."PaidToDate")
				WHEN '18' THEN
					(T2."InsTotal" - T2."PaidToDate")
				WHEN '163' THEN
					CASE T3."NegAmount" 
						WHEN 'N' THEN
							0
						WHEN 'Y' THEN
							0 - (T2."InsTotal" - T2."PaidToDate")
					END
				WHEN '164' THEN
					(T2."InsTotal" - T2."PaidToDate")
				WHEN '203' THEN
					0
				WHEN '13' THEN
					0
				WHEN '165' THEN
					CASE T3."NegAmount" 
						WHEN 'N' THEN
							(T2."InsTotal" - T2."PaidToDate")
						WHEN 'Y' THEN
							0
					END
				WHEN '166' THEN
					0
			 END								AS "Credit",
			 CASE T0."ObjType"
				WHEN '204' THEN
					'EF'
				WHEN '18' THEN
					'EF'
				WHEN '163' THEN
					'EF'
				WHEN '164' THEN
					'EF'
				WHEN '203' THEN
					'SF'
				WHEN '13' THEN
					'SF'
				WHEN '165' THEN
					'SF'
				WHEN '166' THEN
					'SF'
			 END								AS "Group",
			 0									AS "PredictFlag",
			 T4."AvrageLate",
			 CASE T0."ObjType"
				WHEN '204' THEN
					IFNULL(T3."HldCode", '')
				WHEN '18' THEN
					IFNULL(T3."HldCode", '')
				WHEN '163' THEN
					IFNULL(T3."HldCode", '')
				WHEN '164' THEN
					IFNULL(T3."HldCode", '')
				WHEN '203' THEN
					IFNULL(T4."HldCode", '')
				WHEN '13' THEN
					IFNULL(T4."HldCode", '')
				WHEN '165' THEN
					IFNULL(T4."HldCode", '')
				WHEN '166' THEN
					IFNULL(T4."HldCode", '')
			 END								AS "HldCode"
	    FROM "ODRF" T0
   LEFT JOIN "ORCP" T1
		  ON T0."ObjType" = T1."DocObjType"
		 AND T0."DocEntry" = T1."DraftEntry"
		 AND T1."IsRemoved" = 'N'
  INNER JOIN "DRF6" T2
		  ON T2."DocEntry" = T0."DocEntry"
   LEFT JOIN "OADM" T3
		  ON T3."Code" = T3."Code"
  INNER JOIN "OCRD" T4
		  ON T4."CardCode" = T0."CardCode" 
	   WHERE T0."CANCELED" <> 'Y'
	     AND T0."DocStatus" = 'O'
		 AND T1."DraftEntry" IS NULL
		 AND T0."ObjType" IN ('203', '13', '165', '166', '204', '18', '163', '164')))
;

