      CASE	T0."ObjType" 
          WHEN '234000031' THEN
            CASE T4."NegAmount" 
		        WHEN 'N' THEN
			          (T0."DocTotal" - T0."PaidToDate")
		        WHEN 'Y' THEN
			          0
		    END
		  WHEN '234000032' THEN
		     CASE T4."NegAmount" 
		  	    WHEN 'N' THEN
	    	          0
	            WHEN 'Y' THEN
	    	          0 - (T0."DocTotal" - T0."PaidToDate")
