INNER JOIN "OCRD" T3  
         ON  T3."CardCode" = T0."CardCode"    
LEFT  JOIN "OADM" T4  
         ON T4."Code" = T4."Code"
      WHERE  T0."CANCELED" <> 'Y' 
        AND  T0."DocStatus" = 'O'
        AND  T1."DraftEntry" IS NULL
        AND  T0."ObjType" IN ('234000031', '234000032')))
