CREATE VIEW "SBODEMOUS"."B1_CashFlowForecastRecurringTrasactionView" AS
((SELECT T0."DocEntry", 
	  		 '540000043'						AS "DocType",
	         T0."DocNum", 
	         T0."CardCode", 
	         T0."CtlAccount", 
	         T0."TransId", 
	         T0."JrnlMemo",
	         T0."ObjType" || 'r'				AS "ObjType",
	         T0."ObjType"						AS "OriginalType", 
	         T0."CreateDate", 
	         T0."TaxDate", 
	         T0."ClsDate", 
	         T0."PayDuMonth", 
	         T0."ExtraMonth", 
	         T0."ExtraDays",
			 IFNULL(T2."TolDays", 0)			AS "TolDays", 
	         T0."GroupNum",  
			 IFNULL(T3."IntsNo", 0)				AS "InstID",
			 IFNULL(T2."InstNum", 0)			AS "InstNum",
			 IFNULL(T3."InstMonth", 0)			AS "InstMonth",
			 IFNULL(T3."InstDays", 0)			AS "InstDays",
			 IFNULL(T3."InstPrcnt", 100)		AS "InstPrcnt",
			 T0."Installmnt",
	         T0."DocDueDate", 
			 CASE	T0."ObjType" 
				WHEN '22' THEN
					0
				WHEN '204' THEN
					0
				WHEN '18' THEN
					0
				WHEN '163' THEN
					CASE T4."NegAmount" 
						WHEN 'N' THEN
							(T0."DocTotal" - T0."PaidToDate")
						WHEN 'Y' THEN
							0
					END
				WHEN '164' THEN
					0
				WHEN '17' THEN
					(T0."DocTotal" - T0."PaidToDate")
				WHEN '203' THEN
					(T0."DocTotal" - T0."PaidToDate")
				WHEN '13' THEN
					(T0."DocTotal" - T0."PaidToDate")
				WHEN '165' THEN
					CASE T4."NegAmount" 
						WHEN 'N' THEN
							0
						WHEN 'Y' THEN
							0 - (T0."DocTotal" - T0."PaidToDate")
					END
				WHEN '166' THEN
					(T0."DocTotal" - T0."PaidToDate")
			 END								AS "Debit",
			 CASE	T0."ObjType"
				WHEN '22' THEN
					(T0."DocTotal" - T0."PaidToDate")
				WHEN '204' THEN
					(T0."DocTotal" - T0."PaidToDate")
				WHEN '18' THEN
					(T0."DocTotal" - T0."PaidToDate")
				WHEN '163' THEN
					CASE T4."NegAmount" 
						WHEN 'N' THEN
							0
						WHEN 'Y' THEN
							0 - (T0."DocTotal" - T0."PaidToDate")
					END
				WHEN '164' THEN
					(T0."DocTotal" - T0."PaidToDate")
				WHEN '17' THEN
					0
				WHEN '203' THEN
					0
				WHEN '13' THEN
					0
				WHEN '165' THEN
					CASE T4."NegAmount" 
						WHEN 'N' THEN
							(T0."DocTotal" - T0."PaidToDate")
						WHEN 'Y' THEN
							0
					END
				WHEN '166' THEN
					0
			 END								AS "Credit",
			 CASE T0."ObjType"
				WHEN '22' THEN
					'EF'
				WHEN '204' THEN
					'EF'
				WHEN '18' THEN
					'EF'
				WHEN '163' THEN
					'EF'
				WHEN '164' THEN
					'EF'
				WHEN '17' THEN
					'SF'
				WHEN '203' THEN
					'SF'
				WHEN '13' THEN
					'SF'
				WHEN '165' THEN
					'SF'
				WHEN '166' THEN
					'SF'
			 END								AS "Group",
			 CASE T0."ObjType"
				WHEN '17' THEN
					1
				WHEN '22' THEN
					1
				ELSE
					0
			 END								AS "PredictFlag",
			 T5."AvrageLate",
			 CASE T0."ObjType"
				WHEN '22' THEN
					IFNULL(T4."HldCode", '')
				WHEN '204' THEN
					IFNULL(T4."HldCode", '')
				WHEN '18' THEN
					IFNULL(T4."HldCode", '')
				WHEN '163' THEN
					IFNULL(T4."HldCode", '')
				WHEN '164' THEN
					IFNULL(T4."HldCode", '')
				WHEN '17' THEN
					IFNULL(T5."HldCode", '')
				WHEN '203' THEN
					IFNULL(T5."HldCode", '')
				WHEN '13' THEN
					IFNULL(T5."HldCode", '')
				WHEN '165' THEN
					IFNULL(T5."HldCode", '')
				WHEN '166' THEN
					IFNULL(T5."HldCode", '')
			 END								AS "HldCode"
	    FROM "ODRF" T0
  INNER JOIN "ORCP" T1
		  ON T0."ObjType" = ABS(T1."DocObjType")
		 AND T0."DocEntry" = T1."DraftEntry"
