  INNER JOIN "OCRD" T5
		  ON T5."CardCode" = T0."CardCode" 
	   WHERE T0."CANCELED" <> 'Y'
		 AND T1."DraftEntry" IS NOT NULL
		 AND T0."ObjType" IN('17', '203', '13', '165', '166', '22', '204', '18', '163', '164')) UNION ALL (SELECT T0."DocEntry", 
	  		 '540000043'						AS "DocType",
	         T0."DocNum", 
	         T0."CardCode", 
	         T0."CtlAccount", 
	         T0."TransId", 
	         T0."JrnlMemo",
	         T0."ObjType" || 'r'				AS "ObjType",
	         T0."ObjType"						AS "OriginalType", 
	         T0."CreateDate", 
	         T0."TaxDate", 
	         T0."ClsDate", 
	         T0."PayDuMonth", 
	         T0."ExtraMonth", 
	         T0."ExtraDays",
			 IFNULL(T2."TolDays", 0)			AS "TolDays", 
	         T0."GroupNum",  
			 IFNULL(T0."Installmnt", 0)			AS "InstID", 
			 IFNULL(T0."Installmnt", 0)			AS "InstNum", 
			 0									AS "InstMonth", 
			 0									AS "InstDays", 
			 100								AS "InstPrcnt",
			 T0."Installmnt",
	         T0."DocDueDate", 
			 CASE	T0."ObjType" 
				WHEN '20' THEN
					0
				WHEN '21' THEN
					CASE T3."NegAmount" 
						WHEN 'N' THEN
							(T0."DocTotal" - T0."PaidToDate")
						WHEN 'Y' THEN
							0
					END
				WHEN '19' THEN
					CASE T3."NegAmount" 
						WHEN 'N' THEN
							(T0."DocTotal" - T0."PaidToDate")
						WHEN 'Y' THEN
							0
					END
				WHEN '15' THEN
					(T0."DocTotal" - T0."PaidToDate")
				WHEN '16' THEN
					CASE T3."NegAmount" 
						WHEN 'N' THEN
							0
						WHEN 'Y' THEN
							0 - (T0."DocTotal" - T0."PaidToDate")
					END
				WHEN '14' THEN
					CASE T3."NegAmount" 
						WHEN 'N' THEN
							0
						WHEN 'Y' THEN
							0 - (T0."DocTotal" - T0."PaidToDate")
					END
				WHEN '234000031' THEN
                    CASE T3."NegAmount" 
		                WHEN 'N' THEN
			                0
		                WHEN 'Y' THEN
			                0 - (T0."DocTotal" - T0."PaidToDate")
		            END
		        WHEN '234000032' THEN
		            CASE T3."NegAmount" 
		  	            WHEN 'N' THEN
	    	               (T0."DocTotal" - T0."PaidToDate")
	                    WHEN 'Y' THEN
	    	                0
	    	        END
			 END								AS "Debit",
			 CASE	T0."ObjType"
				WHEN '20' THEN
					(T0."DocTotal" - T0."PaidToDate")
				WHEN '21' THEN
					CASE T3."NegAmount" 
						WHEN 'N' THEN
							0
						WHEN 'Y' THEN
							0 - (T0."DocTotal" - T0."PaidToDate")
					END
				WHEN '19' THEN
					CASE T3."NegAmount" 
						WHEN 'N' THEN
							0
						WHEN 'Y' THEN
							0 - (T0."DocTotal" - T0."PaidToDate")
					END
				WHEN '15' THEN
					0
				WHEN '16' THEN
					CASE T3."NegAmount" 
						WHEN 'N' THEN
							(T0."DocTotal" - T0."PaidToDate")
						WHEN 'Y' THEN
							0
					END
				WHEN '14' THEN
					CASE T3."NegAmount" 
						WHEN 'N' THEN
							(T0."DocTotal" - T0."PaidToDate")
						WHEN 'Y' THEN
							0
					END
				WHEN '234000031' THEN
                    CASE T3."NegAmount" 
		                WHEN 'N' THEN
			                (T0."DocTotal" - T0."PaidToDate")
		                WHEN 'Y' THEN
			                0
		            END
		        WHEN '234000032' THEN
		            CASE T3."NegAmount" 
		                WHEN 'N' THEN
	    	                0
	                    WHEN 'Y' THEN
	    	                0 - (T0."DocTotal" - T0."PaidToDate")
	    	        END
			 END								AS "Credit",
			 CASE T0."ObjType"
				WHEN '20' THEN
					'EF'
				WHEN '21' THEN
					'EF'
				WHEN '19' THEN
					'EF'
				WHEN '15' THEN
					'SF'
				WHEN '16' THEN
					'SF'
				WHEN '14' THEN
					'SF'
				WHEN '234000031' THEN
			        'SF'
		        WHEN '234000032' THEN
				    'EF'
			 END								AS "Group",
			 CASE T0."ObjType"
				WHEN '15' THEN
					1
				WHEN '234000031' THEN
				    1
				WHEN '234000032' THEN
				    1
				ELSE
					0
			 END								AS "PredictFlag",
			 T4."AvrageLate",
			 CASE T0."ObjType"
				WHEN '20' THEN
					IFNULL(T3."HldCode", '')
				WHEN '21' THEN
					IFNULL(T3."HldCode", '')
				WHEN '19' THEN
					IFNULL(T3."HldCode", '')
				WHEN '15' THEN
					IFNULL(T4."HldCode", '')
				WHEN '16' THEN
					IFNULL(T4."HldCode", '')
				WHEN '14' THEN
					IFNULL(T4."HldCode", '')
				WHEN '234000031' THEN
				    IFNULL(T4."HldCode", '')
				WHEN '234000032' THEN
				    IFNULL(T3."HldCode", '')
			 END								AS "HldCode"
	    FROM "ODRF" T0
  INNER JOIN "ORCP" T1
		  ON T0."ObjType" = T1."DocObjType"
		 AND T0."DocEntry" = T1."DraftEntry"
		 AND T1."IsRemoved" = 'N'
  INNER JOIN "OCTG" T2
		  ON T2."GroupNum" = T0."GroupNum"
   LEFT JOIN "OADM" T3
		  ON T3."Code" = T3."Code"
  INNER JOIN "OCRD" T4
		  ON T4."CardCode" = T0."CardCode" 
	   WHERE T0."CANCELED" <> 'Y'
		 AND T1."DraftEntry" IS NOT NULL
		 AND T0."ObjType" IN ('15', '16', '14', '20', '21', '19', '234000031', '234000032')))
;

CREATE VIEW "SBODEMOUS"."B1_DeferredDocAppliedTotalsView" AS
SELECT T1."BaseObjTyp" AS "ObjType", T1."BaseAbs" AS "AbsEntry", SUM(T1."BaseSum") AS "BaseSum", SUM(T1."VatSum") AS "VatSum", SUM(T1."EqSum") AS "EqSum", SUM(T1."DeductSum") AS "DeductSum", SUM((T1."BaseSum" + T1."VatSum")) AS "TotalSum" FROM  "SBODEMOUS"."OTAX" T0  INNER  JOIN "SBODEMOUS"."TAX1" T1  ON  T1."AbsEntry" = T0."AbsEntry"    LEFT OUTER  JOIN "SBODEMOUS"."B1_MarketingDocumentsView" T2  ON  T2."DocType" = T1."BaseObjTyp"  AND  T2."DocEntry" = T1."BaseAbs"  AND  T2."CANCELED" = 'Y'   WHERE T1."Isdeferred" = ('Y' )  AND  T0."Cancelled" = ('N' )  AND  T2."DocEntry" IS NULL   AND  T1."BaseAbs" > (0 )  AND  (T1."TaxType" = ('D' )  OR  T0."SrcObjType" NOT IN('24' ,'46' ,'321' )  ) AND   NOT EXISTS (SELECT U0.*  FROM  "SBODEMOUS"."OTAX" U0  WHERE U0."SrcObjType" = T0."SrcObjType"  AND  U0."SrcObjAbs" = T0."SrcObjAbs"  AND  U0."AbsEntry" <> T0."AbsEntry"  AND  U0."Cancelled" = ('Y' )  )   GROUP BY T1."BaseObjTyp", T1."BaseAbs"
;

CREATE VIEW "SBODEMOUS"."B1_DeferredDocTotalsView" AS
SELECT T0."SrcObjType" AS "ObjType", T0."SrcObjAbs" AS "AbsEntry", SUM(T1."BaseSum") AS "BaseSum", SUM(T1."VatSum") AS "VatSum", SUM(T1."EqSum") AS "EqSum", SUM(T1."DeductSum") AS "DeductSum", SUM((T1."BaseSum" + T1."VatSum")) AS "TotalSum" FROM  "SBODEMOUS"."OTAX" T0  INNER  JOIN "SBODEMOUS"."TAX1" T1  ON  T1."AbsEntry" = T0."AbsEntry"    LEFT OUTER  JOIN "SBODEMOUS"."B1_MarketingDocumentsView" T2  ON  T2."DocType" = T0."SrcObjType"  AND  T2."DocEntry" = T0."SrcObjAbs"  AND  T2."CANCELED" = 'Y'   WHERE T1."Isdeferred" = ('Y' )  AND  T0."Cancelled" = ('N' )  AND  T2."DocEntry" IS NULL   AND  T0."SrcObjType" NOT IN('24' ,'46' ,'321' )   AND  (T1."BaseAbs" <= (0 )  OR  T1."BaseAbs" IS NULL   OR   NOT EXISTS (SELECT U0.*  FROM  "SBODEMOUS"."OTAX" U0  WHERE U0."SrcObjType" = T1."BaseObjTyp"  AND  U0."SrcObjAbs" = T1."BaseAbs"  ) )  GROUP BY T0."SrcObjType", T0."SrcObjAbs"
;

