CREATE VIEW "SBODEMOUS"."B1_DocBranchView" AS
(((((((((((((((((((((((((((((SELECT T0."CardCode", T0."ObjType", T0."DocEntry", T0."BPLId" FROM  "SBODEMOUS"."OQUT" T0) UNION (SELECT T0."CardCode", T0."ObjType", T0."DocEntry", T0."BPLId" FROM  "SBODEMOUS"."ORDR" T0)) UNION (SELECT T0."CardCode", T0."ObjType", T0."DocEntry", T0."BPLId" FROM  "SBODEMOUS"."ODLN" T0)) UNION (SELECT T0."CardCode", T0."ObjType", T0."DocEntry", T0."BPLId" FROM  "SBODEMOUS"."ORDN" T0)) UNION (SELECT T0."CardCode", T0."ObjType", T0."DocEntry", T0."BPLId" FROM  "SBODEMOUS"."OINV" T0)) UNION (SELECT T0."CardCode", T0."ObjType", T0."DocEntry", T0."BPLId" FROM  "SBODEMOUS"."ORIN" T0)) UNION (SELECT T0."CardCode", T0."ObjType", T0."DocEntry", T0."BPLId" FROM  "SBODEMOUS"."ODPI" T0)) UNION (SELECT T0."CardCode", T0."ObjType", T0."DocEntry", T0."BPLId" FROM  "SBODEMOUS"."OCSI" T0)) UNION (SELECT T0."CardCode", T0."ObjType", T0."DocEntry", T0."BPLId" FROM  "SBODEMOUS"."OCSV" T0)) UNION (SELECT T0."CardCode", T0."ObjType", T0."DocEntry", T0."BPLId" FROM  "SBODEMOUS"."ORRR" T0)) UNION (SELECT T0."CardCode", T0."ObjType", T0."DocEntry", T0."BPLId" FROM  "SBODEMOUS"."OPQT" T0)) UNION (SELECT T0."CardCode", T0."ObjType", T0."DocEntry", T0."BPLId" FROM  "SBODEMOUS"."OPRQ" T0)) UNION (SELECT T0."CardCode", T0."ObjType", T0."DocEntry", T0."BPLId" FROM  "SBODEMOUS"."OPDN" T0)) UNION (SELECT T0."CardCode", T0."ObjType", T0."DocEntry", T0."BPLId" FROM  "SBODEMOUS"."ORPD" T0)) UNION (SELECT T0."CardCode", T0."ObjType", T0."DocEntry", T0."BPLId" FROM  "SBODEMOUS"."OPCH" T0)) UNION (SELECT T0."CardCode", T0."ObjType", T0."DocEntry", T0."BPLId" FROM  "SBODEMOUS"."ORPC" T0)) UNION (SELECT T0."CardCode", T0."ObjType", T0."DocEntry", T0."BPLId" FROM  "SBODEMOUS"."ODPO" T0)) UNION (SELECT T0."CardCode", T0."ObjType", T0."DocEntry", T0."BPLId" FROM  "SBODEMOUS"."OCPI" T0)) UNION (SELECT T0."CardCode", T0."ObjType", T0."DocEntry", T0."BPLId" FROM  "SBODEMOUS"."OCPV" T0)) UNION (SELECT T0."CardCode", T0."ObjType", T0."DocEntry", T0."BPLId" FROM  "SBODEMOUS"."OPRR" T0)) UNION (SELECT T0."CardCode", T0."ObjType", T0."DocEntry", T0."BPLId" FROM  "SBODEMOUS"."OWTR" T0)) UNION (SELECT T0."CardCode", T0."ObjType", T0."DocEntry", T0."BPLId" FROM  "SBODEMOUS"."OWTQ" T0)) UNION (SELECT T0."CardCode", T0."ObjType", T0."DocEntry", T0."BPLId" FROM  "SBODEMOUS"."OIGE" T0)) UNION (SELECT T0."CardCode", T0."ObjType", T0."DocEntry", T0."BPLId" FROM  "SBODEMOUS"."OIGN" T0)) UNION (SELECT T0."CardCode", '203002' AS "ObjType", T0."DocEntry", T0."BPLId" FROM  "SBODEMOUS"."ODPI" T0  WHERE T0."Posted" = ('N' ))) UNION (SELECT T0."CardCode", '204002' AS "ObjType", T0."DocEntry", T0."BPLId" FROM  "SBODEMOUS"."ODPO" T0  WHERE T0."Posted" = ('N' ))) UNION (SELECT T0."CardCode", '13002' AS "ObjType", T0."DocEntry", T0."BPLId" FROM  "SBODEMOUS"."OINV" T0  WHERE T0."isIns" = ('Y' ))) UNION (SELECT T0."CardCode", '18002' AS "ObjType", T0."DocEntry", T0."BPLId" FROM  "SBODEMOUS"."OPCH" T0  WHERE T0."isIns" = ('Y' ))) UNION (SELECT T0."ShortName", T0."TransType", T0."TransId", T0."BPLId" FROM  "SBODEMOUS"."JDT1" T0  WHERE T0."TransType" = ('30' )))
;

