CREATE VIEW "SBODEMOUS"."B1_EDFLatestLogsView" AS
SELECT "TBLRANK"."AbsEntry" , "TBLRANK"."LogNum" , "TBLRANK"."LogType" , "TBLRANK"."LogMessage" , "TBLRANK"."LogData" , "TBLRANK"."LogOpDate" , "TBLRANK"."LogOpTS" , "TBLRANK"."ExportFmt" , "TBLRANK"."UserSign" , "TBLRANK"."CreateDate" , "TBLRANK"."CreateTS" , "TBLRANK"."UserSign2" , "TBLRANK"."UpdateDate" , "TBLRANK"."UpdateTS" , "TBLRANK"."LogInstanc" , "TBLRANK"."ExportFile" , "TBLRANK"."AutProcess" , "TBLRANK"."Sensitive" , "TBLRANK"."RankByDT" FROM (SELECT
	 *,
	 CAST(RANK() OVER (PARTITION BY "AbsEntry",
	 "LogType" 
			ORDER BY "LogOpDate" DESC,
	 "LogOpTS" DESC,
	 "LogNum" DESC) AS Integer) AS "RankByDT" 
	FROM "ECM3" ) tblRank 
WHERE tblRank."RankByDT" = 1 ORDER BY "AbsEntry",
	 "LogType"
;

CREATE VIEW "SBODEMOUS"."B1_EUSalesStockTransferView" AS
SELECT T2."LicTradNum" AS "OCRD_LicTradNum", T3."FedTaxID" AS "OWHS_From_FedTaxID", T0."LineTotal", T0."Quantity", T1."DocEntry", T1."DocNum", T1."ObjType", T1."DocDate", T1."TaxDate", T1."VatDate", T1."FinncPriod", T1."CANCELED", T1."CardCode" AS "OWTR_CardCode", T1."CardName" AS "OWTR_CardName", T7."CardCode" AS "Shipper_CardCode", T7."CardName" AS "Shipper_CardName", T3."Country" AS "OWHS_From_Country", T5."IsEC" AS "OCRY_From_IsEc", T4."Country" AS "OWHS_To_Country", T6."IsEC" AS "OCRY_To_IsEc", T9."NdPercent" AS "Dummy_TAX1_NdPercent", T9."CrditDebit" AS "Dummy_TAX1_CrditDebit", T9."BaseArrTyp" AS "Dummy_TAX1_BaseArrTyp", T10."Indicator" AS "Dummy_OVTG_TriangularDeal", T10."Code" AS "Dummy_OVTG_Code", T10."GoddsShip" AS "Dummy_OVTG_GoddsShip", T10."Category" AS "Dummy_OVTG_VatCategory", T10."ServSupply" AS "Dummy_OVTG_ServSupply" FROM  "SBODEMOUS"."WTR1" T0  INNER  JOIN "SBODEMOUS"."OWTR" T1  ON  T0."DocEntry" = T1."DocEntry"    LEFT OUTER  JOIN "SBODEMOUS"."OCRD" T2  ON  T1."CardCode" = T2."CardCode"   INNER  JOIN "SBODEMOUS"."OWHS" T3  ON  T0."FromWhsCod" = T3."WhsCode"   INNER  JOIN "SBODEMOUS"."OWHS" T4  ON  T0."WhsCode" = T4."WhsCode"   INNER  JOIN "SBODEMOUS"."OCRY" T5  ON  T3."Country" = T5."Code"   INNER  JOIN "SBODEMOUS"."OCRY" T6  ON  T4."Country" = T6."Code"    LEFT OUTER  JOIN "SBODEMOUS"."OCRD" T7  ON  T3."Shipper" = T7."CardCode"   INNER  JOIN "SBODEMOUS"."OADM" T8  ON  T8."CompnyName" = T8."CompnyName"    LEFT OUTER  JOIN "SBODEMOUS"."TAX1" T9  ON  T9."AbsEntry" = -1    LEFT OUTER  JOIN "SBODEMOUS"."OVTG" T10  ON  T10."Code" = ''   WHERE (T3."Country" = T8."Country"  AND  T5."IsEC" = ('Y' )  AND  T4."Country" <> T8."Country"  AND  T6."IsEC" = ('Y' ) ) OR  (T3."Country" <> T8."Country"  AND  T5."IsEC" = ('Y' )  AND  T4."Country" = T8."Country"  AND  T6."IsEC" = ('Y' ) ) OR  (T3."Country" <> T8."Country"  AND  T5."IsEC" = ('Y' )  AND  T4."Country" <> T8."Country"  AND  T6."IsEC" = ('Y' )  AND  T4."Country" <> T3."Country" )
;

CREATE VIEW "SBODEMOUS"."B1_ElectronicCRWView" AS
SELECT T0."AbsEntry", T0."Code", T0."ActType", T0."ActStatus", T0."ActDesc", T0."ActMessage", T0."ActEnv", T0."BPLId" AS "Branch", T0."SrcObjType", T0."SrcObjAbs", T0."Submits", T3."LogOpDate" AS "SendDate", T4."LogOpDate" AS "RecvDate", T0."UserSign", T0."CreateDate", T0."CreateTS", T0."UserSign2", T0."UpdateDate", T0."IsRemoved", T0."Cancel" AS "Cancelation", T3."LogData" AS "SendData", T4."LogData" AS "RecvData", T0."ReportID", T0."AssignedID", T1."CardCode", T2."CardName", T1."Year", T1."SentMeth", T1."SentValue", T1."LastAMeth", T1."LastAValue" FROM  "SBODEMOUS"."ECM2" T0   LEFT OUTER  JOIN "SBODEMOUS"."OCRW" T1  ON  T0."SrcObjType" = '254000013'  AND  T1."AbsEntry" = T0."SrcObjAbs"   INNER  JOIN "SBODEMOUS"."OCRD" T2  ON  T2."CardCode" = T1."CardCode"    LEFT OUTER  JOIN "SBODEMOUS"."B1_EDFLatestLogsView" T3  ON  T3."AbsEntry" = T0."AbsEntry"  AND  T3."LogType" = 'S'    LEFT OUTER  JOIN "SBODEMOUS"."B1_EDFLatestLogsView" T4  ON  T4."AbsEntry" = T0."AbsEntry"  AND  T4."LogType" = 'R'
