ode", T1."CountryOrg" FROM  "SBODEMOUS"."ODPO" T0  INNER  JOIN "SBODEMOUS"."DPO1" T1  ON  T0."DocEntry" = T1."DocEntry")) UNION ALL (SELECT T1."DocEntry", 140000010 AS "DocType", T1."LineNum", T0."Model", T0."Serial", T0."SeriesStr", T0."SubStr", T0."TaxDate", T1."CFOPCode", T1."CountryOrg" FROM  "SBODEMOUS"."OIEI" T0  INNER  JOIN "SBODEMOUS"."IEI1" T1  ON  T0."DocEntry" = T1."DocEntry")) UNION ALL (SELECT T1."DocEntry", 60 AS "DocType", T1."LineNum", T0."Model", T0."Serial", T0."SeriesStr", T0."SubStr", T0."TaxDate", T1."CFOPCode", T1."CountryOrg" FROM  "SBODEMOUS"."OIGE" T0  INNER  JOIN "SBODEMOUS"."IGE1" T1  ON  T0."DocEntry" = T1."DocEntry")) UNION ALL (SELECT T1."DocEntry", 59 AS "DocType", T1."LineNum", T0."Model", T0."Serial", T0."SeriesStr", T0."SubStr", T0."TaxDate", T1."CFOPCode", T1."CountryOrg" FROM  "SBODEMOUS"."OIGN" T0  INNER  JOIN "SBODEMOUS"."IGN1" T1  ON  T0."DocEntry" = T1."DocEntry")) UNION ALL (SELECT T1."DocEntry", 13 AS "DocType", T1."LineNum", T0."Model", T0."Serial", T0."SeriesStr", T0."SubStr", T0."TaxDate", T1."CFOPCode", T1."CountryOrg" FROM  "SBODEMOUS"."OINV" T0  INNER  JOIN "SBODEMOUS"."INV1" T1  ON  T0."DocEntry" = T1."DocEntry")) UNION ALL (SELECT T1."DocEntry", 140000009 AS "DocType", T1."LineNum", T0."Model", T0."Serial", T0."SeriesStr", T0."SubStr", T0."TaxDate", T1."CFOPCode", T1."CountryOrg" FROM  "SBODEMOUS"."OOEI" T0  INNER  JOIN "SBODEMOUS"."OEI1" T1  ON  T0."DocEntry" = T1."DocEntry")) UNION ALL (SELECT T1."DocEntry", 18 AS "DocType", T1."LineNum", T0."Model", T0."Serial", T0."SeriesStr", T0."SubStr", T0."TaxDate", T1."CFOPCode", T1."CountryOrg" FROM  "SBODEMOUS"."OPCH" T0  INNER  JOIN "SBODEMOUS"."PCH1" T1  ON  T0."DocEntry" = T1."DocEntry")) UNION ALL (SELECT T1."DocEntry", 20 AS "DocType", T1."LineNum", T0."Model", T0."Serial", T0."SeriesStr", T0."SubStr", T0."TaxDate", T1."CFOPCode", T1."CountryOrg" FROM  "SBODEMOUS"."OPDN" T0  INNER  JOIN "SBODEMOUS"."PDN1" T1  ON  T0."DocEntry" = T1."DocEntry")) UNION ALL (SELECT T1."D