CREATE VIEW "SBODEMOUS"."MTC_VW_AI_DocBatch" AS
SELECT
	 T1."DocDate",
	 T1."BaseType",
	 T1."BaseEntry",
	 T1."BsDocType" as "BsDocType0",
	 CASE WHEN T1."BaseType" = '310000001' 
THEN 'Opening Balance' WHEN T1."BaseType" = '20' 
THEN 'Goods Receipt PO' WHEN T1."BaseType" = '18' 
THEN 'Accounts Payable Invoice' WHEN T1."BaseType" = '16' 
THEN 'Sales Return' WHEN T1."BaseType" = '14' 
THEN 'Accounts Receivable Credit Memo' WHEN T1."BaseType" = '59' 
THEN 'Inventory Receipt' WHEN T1."BaseType" = '67' 
AND T1."Direction" = '0' 
THEN 'Inventory Transfer Receipt' WHEN T1."BaseType" = '10000071' 
AND T1."Direction" = '0' 
THEN 'Inventory Counting Gain' WHEN T1."BaseType" = '59' 
AND T1."BsDocType" = '202' 
THEN 'Production Receipt' WHEN T1."BaseType" = '15' 
THEN 'Sales Delivery' WHEN T1."BaseType" = '13' 
THEN 'Accounts Receivable Invoice' WHEN T1."BaseType" = '21' 
THEN 'Goods Return' WHEN T1."BaseType" = '19' 
THEN 'Accounts Payable Credit Memo' WHEN T1."BaseType" = '60' 
THEN 'Inventory Issue' WHEN T1."BaseType" = '67' 
AND T1."Direction" = '1' 
THEN 'Inventory Transfer Issue' WHEN T1."BaseType" = '10000071' 
AND T1."BsDocType" = '1' 
THEN 'Inventory Counting Loss' 
END AS "DocType",
	 T1."BaseNum",
	 CASE T1."BsDocType" WHEN '-1' 
THEN 'No Base Document' WHEN '13' 
THEN 'A/R Invoice' WHEN '22' 
THEN 'Purchase Order' WHEN '17' 
THEN 'Sales Order' WHEN '202' 
THEN 'Production Order' WHEN '18' 
THEN 'A/P Invoice' WHEN '20' 
THEN 'Goods Receipt PO' WHEN '15' 
THEN 'Delivery' 
END AS "BsDocType",
	 T1."BsDocEntry",
	 T1."WhsCode",
	 T2."WhsName",
	 T1."ItemCode",
	 T1."ItemName",
	 T1."BatchNum",
	 T1."Direction",
	 CASE T1."Direction" WHEN '0' 
THEN 'Inbound' WHEN '1' 
THEN 'Outbound' 
END AS "Input/Output",
	 T1."Quantity",
	 T1."CardCode",
	 T1."CardName",
	 T1."CreateDate",
	 T2."BPLid",
	 T3."BPLName" 
FROM IBT1 T1 
LEFT JOIN OWHS T2 ON T1."WhsCode" = T2."WhsCode" 
LEFT JOIN OBPL T3 ON T2."BPLid" = T3."BPLId" 
INNER JOIN "AgentAll_USERBPL"(SESSION_CONTEXT('USERCODE')) TB ON TB.BPLID=IFNULL(T3."BPLId",
	0)
;

