CREATE VIEW "SBODEMOUS"."MTC_VW_AI_FUNDBAL" AS
SELECT
 T0. "AcctCode" ,
 T0. "AcctName",
 T0. "ActCurr",
 CASE WHEN T0."ActCurr"=T1."MainCurncy" THEN 'Y' ELSE 'N' END AS "IsLocCurrency",
 T0. "CurrTotal",
 T0. "FcTotal" ,
 T0. "BPLId",
 T0. "BPLName"
FROM OACT  T0
LEFT JOIN OADM T1 ON T0."ActCurr"=T1."MainCurncy"
INNER JOIN "AgentAll_USERRIGHT"(SESSION_CONTEXT('USERCODE')) TD ON TD.USERID=T0."UserSign"
INNER JOIN "AgentAll_USERBPL"(SESSION_CONTEXT('USERCODE')) TB ON TB.BPLID=IFNULL(T0."BPLId",0)
WHERE "Finanse"='Y'
;

CREATE VIEW "SBODEMOUS"."MTC_VW_AI_FixedAssets" AS
SELECT
	 T1."ItemCode" ,
	 T1."ItemName" ,
	 T1."AssetSerNo" ,
	 T1."AssetClass",
	T7."Name" AS "AssetClassName",
	 T5."DprArea" ,
	T8."Descr" AS "DprAreaName",
	 T5."DprType" ,
	T9."Descr" AS "DprTypeName",
CASE T1."AsstStatus" WHEN N'N' THEN N'New'WHEN N'A' THEN N'Available'WHEN N'I' THEN N'Unavailable' END AS "AsstStatus",
 
 
	 T1."AcqDate" ,
	 T1."CapDate",
	 T5."DprStart" ,
	 T5."DprEnd" ,
	 NULLIF(T5."UsefulLife" ,
	0) AS "ServiceLife" ,
	 T6."Project",
	 T13."PrjName",
	 T2."OcrCode" ,
	 T16."PrcName" AS "CostCenterName1",
	 T2."OcrCode2" ,
	 T17."PrcName" AS "CostCenterName2",
	 T2."OcrCode3",
	 T18."PrcName" AS "CostCenterName3",
	 T2."OcrCode4" ,
	 T19."PrcName" AS "CostCenterName4",
	 T2."OcrCode5" ,
	 T20."PrcName" AS "CostCenterName5",
	 T4."BPLId",
	 T12."BPLName" 
FROM "OITM" T1 
LEFT JOIN (SELECT
	 * 
	FROM ITM6 
	WHERE IFNULL( "ValidTo",
	'')='') T2 ON T1."ItemCode" = T2."ItemCode" 
LEFT JOIN "OPRC" T3 ON T2."OcrCode" = T3."PrcCode" 
LEFT JOIN "OACS" T4 ON T1."AssetClass" = T4."Code" 
LEFT JOIN "ITM7" T5 ON T1."ItemCode" = T5."ItemCode" 
LEFT JOIN (SELECT
	 * 
	FROM ITM5 
	WHERE IFNULL("ValidTo",
	'')='') T6 ON T1."ItemCode" = T6."ItemCode" 
LEFT JOIN OACS T7 ON T1."AssetClass"=T7."Code" 
LEFT JOIN ODPA T8 ON T5."DprArea"=T8."Code" 
LEFT JOIN ODTP T9 ON T5."DprType"=T9."Code" 
LEFT JOIN OBPL T12 ON T12."BPLId" = T4."BPLId" 
LEFT JOIN OPRJ T13 ON T6."Project"=T13."PrjCode" 
LEFT JOIN (SELECT
	 "PrcCode",
	"PrcName" 
	FROM OPRC 
	WHERE "DimCode"=1) T16 ON T2."OcrCode"=T16."PrcCode" 
LEFT JOIN (SELECT
	 "PrcCode",
	"PrcName" 
	FROM OPRC 
	WHERE "DimCode"=2) T17 ON T2."OcrCode2"=T17."PrcCode" 
LEFT JOIN (SELECT
	 "PrcCode",
	"PrcName" 
	FROM OPRC 
	WHERE "DimCode"=3) T18 ON T2."OcrCode3"=T18."PrcCode" 
LEFT JOIN (SELECT
	 "PrcCode",
	"PrcName" 
	FROM OPRC 
	WHERE "DimCode"=4) T19 ON T2."OcrCode4"=T19."PrcCode" 
LEFT JOIN (SELECT
	 "PrcCode",
	"PrcName" 
	FROM OPRC 
	WHERE "DimCode"=5) T20 ON T2."OcrCode5"=T20."PrcCode" 
WHERE T1."ItemType" = N'F'
;

