  "T1"."LinManClsd",
  "T1"."LineNum",
  "T1"."ItemCode",
  "T1"."SubCatNum",
  "T1"."Dscription",
  "T9"."ItmsGrpNam",
  "T1"."Quantity",
  "T1"."OpenQty",
  "T7"."WhsName",
  "T1"."ShipDate",
  "T15"."TimelyDelQty",
  "T16"."DelayedDelQty",
  "T10"."Code",
  "T10"."Category",
  "T0"."BPLId",
  "T14"."BPLName" 
FROM "ORDR" "T0" 
INNER JOIN "RDR1" "T1" ON "T0"."DocEntry"="T1"."DocEntry" 
LEFT JOIN "OSLP" "T2" ON "T0"."SlpCode"="T2"."SlpCode" 
INNER JOIN "OCRD" "T4" ON "T0"."CardCode"="T4"."CardCode" 
LEFT JOIN "OCRG" "T5" ON "T4"."GroupCode"="T5"."GroupCode" 
INNER JOIN "OWHS" "T7" ON "T1"."WhsCode"="T7"."WhsCode" 
INNER JOIN "OITM" "T8" ON "T1"."ItemCode"="T8"."ItemCode" 
LEFT JOIN "OITB" "T9" ON "T8"."ItmsGrpCod"="T9"."ItmsGrpCod" 
LEFT JOIN "OFPR" "T10" ON "T0"."FinncPriod" = "T10"."AbsEntry" 
LEFT JOIN "OBPL" "T14" ON "T0"."BPLId"="T14"."BPLId" 
INNER JOIN "AgentAll_USERRIGHT"(SESSION_CONTEXT('USERCODE')) TD ON TD.USERID=T0."UserSign"
INNER JOIN "AgentAll_USERBPL"(SESSION_CONTEXT('USERCODE')) TB ON TB.BPLID=IFNULL(T0."BPLId",0)
LEFT JOIN ( SELECT
  "T3"."DocEntry",
  "T3"."LineNum",
  "T3"."ItemCode",
  "T3"."DocDate" AS "TimelyDelDate",
  SUM("T1"."Quantity") AS "TimelyDelQty" 
 FROM "DLN1" "T1" 
 LEFT JOIN "ODLN" "T2" ON "T2"."DocEntry"="T1"."DocEntry" 
 LEFT JOIN "RDR1" "T3" ON "T3"."DocEntry"="T1"."BaseEntry" 
 AND "T3"."LineNum"="T1"."BaseLine" 
 WHERE "T1"."BaseType"=17 
 AND "T2"."CANCELED"='N' 
 AND "T2"."DocDate"<="T3"."ShipDate" 
 GROUP BY "T3"."DocEntry",
  "T3"."LineNum",
  "T3"."ItemCode","T3"."DocDate") "T15" ON "T1"."DocEntry"="T15"."DocEntry" 
AND "T1"."LineNum"="T15"."LineNum" 
LEFT JOIN ( SELECT
  "T3"."DocEntry",
  "T3"."LineNum",
  "T3"."ItemCode",
   "T3"."DocDate" AS "DelayedDelDate",
  SUM("T1"."Quantity") AS "DelayedDelQty" 
 FROM "DLN1" "T1" 
 LEFT JOIN "ODLN" "T2" ON "T2"."DocEntry"="T1"."DocEntry" 
 LEFT JOIN "RDR1" "T3" ON "T3"."DocEntry"="T1"."BaseEntry" 
 AND "T3"."LineNum"="T1"."BaseLine" 
 WHERE "T1"."BaseType"=17 
 AND "T2"."CANCELED"='N' 
 AND "T2"."DocDate">"T3"."ShipDate" 
 GROUP BY "T3"."DocEntry",
  "T3"."LineNum",
  "T3"."ItemCode","T3"."DocDate" ) "T16" ON "T1"."DocEntry"="T16"."DocEntry" 
AND "T1"."LineNum"="T16"."LineNum" 
WHERE "T0"."CANCELED"='N' 
AND "T0"."DocType"='I' 
AND CAST("T1"."DocEntry" AS NVARCHAR)||CAST("T1"."LineNum" AS NVARCHAR)||"T1"."ItemCode" 
NOT IN (
    SELECT CAST("DocEntry" AS NVARCHAR)||CAST("LineNum" AS NVARCHAR)||"ItemCode" 
    FROM "RDR1" 
    WHERE "LinManClsd"='Y' AND "TargetType"='-1' AND "LineStatus"='C'
)
;

CREATE VIEW "SBODEMOUS"."MTC_VW_AI_Supplier" AS
SELECT
  T0."CardCode",
  T0."CardName",
  T0."CardType",
  T0."Currency",
  T0."LicTradNum",
  T0."validFor",
  T2."GroupName",
  T3."SlpName",
  T8."descript" AS "Province",
  T9."descript" AS "Region",
  T0."GTSRegNum",
  T0."GTSBankAct",
  T0."GTSBilAddr",
  T0."ECVatGroup",
  T7."Name" AS "VatName",
  T0."Phone1",
  T0."Phone2",
  T0."E_Mail",
  T0."CntctPrsn",
  T10."Position" ,
  T10."Address",
  T10."Tel1",
  T10."Cellolar",
  T10."E_MailL",
  T10."Address" as  "CntAddress",
  T0."MailAddres" ,
  T4."PymntGroup",
  T5."ListName",
  T0."BankCountr",
  T0."BankCode",
  T6."BankName",
  T0."DflAccount",
  T0."DflSwift",
  T0."DflBranch",
  T0."UseShpdGd",
  T0."ConnBP",
  T11."CardName" AS "ConnBPName",
  T0."FatherType",
  T0."FatherCard",
  T12."CardName" AS "FatherName",
  T0."CreateDate",
  T0."UpdateDate" 
FROM OCRD T0 
LEFT JOIN OCRG T2 ON T0."GroupCode" = T2."GroupCode" AND T0."CardType" = T2."GroupType" 
LEFT JOIN OSLP T3 ON T0."SlpCode" = T3."SlpCode"
LEFT JOIN OCTG T4 ON T0."GroupNum"=T4."GroupNum"
LEFT JOIN OPLN T5 ON T0."ListNum"=T5."ListNum"
LEFT JOIN ODSC T6 ON T0."BankCode"=T6."BankCode"
LEFT JOIN OVTG T7 ON T0."ECVatGroup"=T7."Code"
LEFT JOIN OTER T8 ON T0."Territory"=T8."territryID"
LEFT JOIN OTER T9 ON T8."parent"=T9."territryID"
LEFT JOIN OCPR T10 ON T0."CntctPrsn"=T10."Name" AND T0."CardCode"=T10."CardCode" 
LEFT JOIN OCRD T11 ON T0."ConnBP"=T11."CardCode"
LEFT JOIN OCRD T12 ON T0."FatherCard"=T12."CardCode"
where  T0."CardType"='S'
;

CREATE VIEW "SBODEMOUS"."OIBT" AS
SELECT OBTN."ItemCode"	AS "ItemCode", OBTN."DistNumber"	AS "BatchNum", OBTQ."WhsCode"		AS "WhsCode", OITL."ItemName"	AS "ItemName", OBTN."MnfSerial"	AS "SuppSerial", OBTN."LotNumber"	AS "IntrSerial", OBTN."ExpDate"		AS "ExpDate", OBTN."MnfDate"		AS "PrdDate", OBTN."InDate"		AS "InDate", OBTW."Location"	AS "Located", OBTN."Notes"		AS "Notes", OBTQ."Quantity"	AS "Quantity", OITL."DocType"		AS "BaseType", OITL."DocEntry"	AS "BaseEntry", OITL."DocNum"		AS "BaseNum", OITL."DocLine"		AS "BaseLinNum", ( CASE WHEN OITL."DocType" = 59 OR OITL."DocType" = 60 		OR OITL."DocType" = 10000071 OR OITL."DocType" = 310000001 		OR OITL."DocType" = 58 THEN NULL ELSE OITL."CardCode" END )			AS "CardCode", ( 	CASE WHEN OITL."DocType" = 59 OR OITL."DocType" = 60 			OR OITL."DocType" = 10000071 OR OITL."DocType" = 310000001 			OR OITL."DocType" = 58 THEN NULL 	ELSE OITL."CardName" END )			AS "CardName", OBTN."CreateDate"	AS "CreateDate", OBTN."Status"		AS "Status", 0			AS "Direction", OBTQ."CommitQty"	AS "IsCommited", 0			AS "OnOrder", 0			AS "Consig", OBTN."DataSource"	AS "DataSource", OBTN."UserSign"	AS "UserSign", OBTN."Transfered"	AS "Transfered", OBTN."Instance"	AS "Instance", OBTN."SysNumber"	AS "SysNumber", OBTN."LogInstanc"	AS "LogInstanc", OBTN."UserSign2"	AS "UserSign2", OBTN."UpdateDate"	AS "UpdateDate" FROM		OBTN LEFT JOIN	OBTQ OBTQ ON OBTN."ItemCode" = OBTQ."ItemCode" AND OBTN."SysNumber" = OBTQ."SysNumber" INNER JOIN	OBTW OBTW ON OBTN."ItemCode" = OBTW."ItemCode" AND OBTN."SysNumber" = OBTW."SysNumber" AND OBTQ."WhsCode" = OBTW."WhsCode" INNER JOIN OITL ON OITL."LogEntry" IN ( SELECT MIN(T1."LogEntry") AS "LogEntry" FROM OITL T1 INNER JOIN ITL1 T2 ON T1."LogEntry" = T2."LogEntry" AND T1."ItemCode" = T2."ItemCode" AND T1."ItemCode" = OITL."ItemCode" AND T2."SysNumber" = OBTN."SysNumber" GROUP BY T1."ItemCode", T2."SysNumber" ) AND OITL."ItemCode" = OBTN."ItemCode"
;

