CREATE VIEW "SBODEMOUS"."OSRD" AS
SELECT MIN(a."ItemCode")	as "ItemCode",MIN(a."ApplyType")	as "DocType",MIN(a."ApplyEntry")	as "DocEntry",MIN(a."AppDocNum")	as "DocNum",MIN(a."ApplyLine")	as "DocLineNum",ABS(SUM(a."DocQty") - SUM(IFNULL (d."DocQty", 0)))	as "DocQuty",ABS(SUM(a."DocQty") - SUM(IFNULL (d."DocQty", 0))) - MIN(b."DefinedQty") as "DocOpenQty",MIN(a."DocDate")		as "DocDate",(CASE WHEN ABS(SUM(a."DocQty") - SUM(IFNULL (d."DocQty", 0))) > MIN(b."DefinedQty") THEN '0' ELSE '1' END)		as "Status",(CASE WHEN MIN(a."ManagedBy") = 10000044 THEN 106 ELSE 94 END)			as "SrdType",MIN(a."ItemName")	as "ItemName",MIN(a."LocCode")		as "WhsCode",MIN(a."CardCode")	as "CardCode",MIN(a."CardName")		as "CardName",MIN(c."ManOutOnly")	as "ManOutOnly",(CASE WHEN (SUM(a."DocQty") > 0 AND MIN(a."StockEff") = 1) OR (SUM(a."DocQty") < 0 AND MIN(a."StockEff") = 2)  THEN '0' ELSE '1' END)		as "Direction",NULL				as "CreateNew",'N'				as "DataSource",NULL				as "UserSign" FROM  "SBODEMOUS".OITL  a	LEFT  JOIN	( select (CASE when IFNULL(ABS(SUM(bb."Quantity")), 0) > 0 THEN	IFNULL(ABS(SUM(bb."Quantity")), 0)	else IFNULL(ABS(SUM(bb."AllocQty")), 0) END	) 					as "DefinedQty",MIN (aa."LogEntry") as "LogEntry" from  "SBODEMOUS".OITL aa left join	"SBODEMOUS".ITL1 bb on aa."LogEntry" = bb."LogEntry" group by	aa."ItemCode", aa."ApplyType", aa."ApplyEntry", aa."ApplyLine", aa."LocCode" ) b on b."LogEntry" = a."LogEntry"  INNER JOIN	"SBODEMOUS".OITM c on c."ItemCode" = a."ItemCode" LEFT OUTER JOIN "SBODEMOUS".OITL d on (d."LogEntry" = a."LogEntry" and d."StockQty" = 0 and d."DefinedQty" > 0 and d."StockEff" = 1)  or (d."LogEntry" = a."LogEntry" and d."StockEff" = 2 and d."ApplyType" in (13,14,15,60,59,67))WHERE d."ApplyType" <> 13 or d."LogEntry" is null or  d."ApplyType" = 13 and exists (select 1 from "SBODEMOUS".OITL U0 WHERE U0."TransId" = a."TransId" AND U0."StockEff" <> 2)  GROUP BY	a."ItemCode", a."ApplyType", a."ApplyEntry", a."ApplyLine", a."LocCode" HAVING (MIN(a."ApplyType") <> 67 and SUM(a."DocQty") <> 0)	OR	 (MIN(a."ApplyType") = 67 and SUM(a."DocQty") < 0)
;

CREATE VIEW "SBODEMOUS"."OSRI" AS
SELECT "T11"."ItemCode" , "T11"."SysSerial" , "T11"."SuppSerial" , "T11"."IntrSerial" , "T11"."BatchId" , "T11"."ExpDate" , "T11"."PrdDate" , "T11"."InDate" , "T11"."GrntStart" , "T11"."GrntExp" , "T11"."WhsCode" , "T11"."Located" , "T11"."Notes" , "T11"."Quantity" , "T11"."BaseType" , "T11"."BaseEntry" , "T11"."BaseNum" , "T11"."BaseLinNum" , "T11"."CreateDate" , "T11"."CardCode" , "T11"."CardName" , "T11"."ItemName" , "T11"."Status" , "T11"."Direction" , "T11"."DataSource" , "T11"."UserSign" , "T11"."Transfered" , "T11"."Instance" from (SELECT T0."ItemCode" AS "ItemCode",T0."SysNumber" AS "SysSerial",T0."MnfSerial" AS "SuppSerial",T0."DistNumber" AS "IntrSerial",T0."LotNumber" AS "BatchId",T0."ExpDate" AS "ExpDate",T0."MnfDate" AS "PrdDate",T0."InDate" AS "InDate",T0."GrntStart" AS "GrntStart",T0."GrntExp" AS "GrntExp",OSRQ."WhsCode" AS "WhsCode",T0."Location" AS "Located",T0."Notes" AS "Notes",T2."DocQty" AS "Quantity",T2."DocType" AS "BaseType",T2."DocEntry" AS "BaseEntry",T2."DocNum" AS "BaseNum",T2."DocLine" AS "BaseLinNum",T0."CreateDate" AS "CreateDate",( CASE when T2."DocType" = 59 or T2."DocType" = 60 or T2."DocType" = 10000071 or T2."DocType" = 310000001 or T2."DocType" = 58 then NULL ELSE T2."CardCode" END ) AS "CardCode",( CASE when T2."DocType" = 59 or T2."DocType" = 60 or T2."DocType" = 10000071 or T2."DocType" = 310000001 or T2."DocType" = 58 then NULL ELSE T2."CardName" END ) AS "CardName",T2."ItemName" AS "ItemName",(case when OSRQ."Quantity" is null then 1 when OSRQ."Quantity" = 0 then 1 when OSRQ."Quantity" = 1 then 0 else null end) AS "Status",0 AS "Direction",T0."DataSource" AS "DataSource",T0."UserSign" AS "UserSign",T0."Transfered" AS "Transfered",T0."Instance" AS "Instance" FROM "SBODEMOUS".OSRN T0  LEFT JOIN "SBODEMOUS".OSRQ OSRQ  ON T0."ItemCode" = OSRQ."ItemCode" AND T0."SysNumber" = OSRQ."SysNumber"  INNER JOIN "SBODEMOUS"."ixvITL_Min" T1  ON T0."ItemCode" = T1."ItemCode" AND T0."SysNumber" = T1."SysNumber"  INNER JOIN "SBODEMOUS".OITL T2  ON T2."LogEntry" = T1."LogEntry" AND T2."ItemCode" = T1."ItemCode"  WHERE (OSRQ."Quantity" is null OR OSRQ."Quantity" = 0 or OSRQ."Quantity" = 1)  ) t11  INNER JOIN "SBODEMOUS"."ixvITL_LastWhs" T3  ON T11."ItemCode" = T3."ItemCode" AND T11."SysSerial" = T3."SysNumber"   AND t11."WhsCode" = T3."WhsCode"
;

CREATE VIEW "SBODEMOUS"."SBO_ACCOUNT_ATTR" AS
SELECT left("OACT"."AcctCode",10) AS "GL_ACCOUNT", 
			CASE "OACT"."ActType"  
			WHEN 'E'  THEN 'E'
			WHEN 'I'  THEN 'I'
			END AS "INCST_FLAG",
			CASE "OACT"."ActType" 
				WHEN 'N'  THEN 'X'
			END AS "BAL_FLAG"
			FROM "SBODEMOUS"."OACT" WHERE ("Postable" = 'Y')
;

CREATE VIEW "SBODEMOUS"."SBO_ACCOUNT_TEXT" AS
SELECT "OACT"."AcctCode" AS "GL_ACCOUNT",
				left("OACT". "AcctName",20) AS "TXTSH", 
				left("OACT"."AcctName",60) AS "TXTLG"
				FROM "SBODEMOUS"."OACT"  WHERE ("OACT"."Postable" = 'Y')
;

CREATE VIEW "SBODEMOUS"."SBO_ALTACT_ATTR" AS
SELECT 
				left(IFNULL("OACT"."AccntntCod",'DEFT_ACCT'),10)  AS "SBO_ALTACT_ATTR"
				FROM "OACT"     Where "OACT"."Postable" = 'Y'  GROUP BY "OACT"."AccntntCod"
;

CREATE VIEW "SBODEMOUS"."SBO_CUSTOMER_ATTR" AS
SELECT TO_CHAR("CardCode") AS "CARDCODE", "City" AS "CITY", "Country" AS "COUNTRY", "Fax" AS "FAX", 
      			"CardName" AS "CARDNAME", "Phone1" AS "PHONE1", "ZipCode" AS "ZIPCODE", 
      			"Address" AS "ADDRESS",
      			TO_CHAR(YEAR("CreateDate"))
       			|| case LENGTH(MONTH("CreateDate"))
          		when 1 then '0' || TO_CHAR(MONTH("CreateDate"))
          		else TO_CHAR(MONTH("CreateDate"))
         		end
      			|| case LENGTH(EXTRACT(DAY FROM "CreateDate"))
          		when 1 then '0' || TO_CHAR(EXTRACT(DAY FROM "CreateDate"))
          		else TO_CHAR(EXTRACT(DAY FROM "CreateDate"))
        		end  AS "CREATEDATE",
      			TO_CHAR(YEAR("UpdateDate"))
       			|| case LENGTH(MONTH("UpdateDate"))
          		when 1 then '0' || TO_CHAR(MONTH("UpdateDate"))
          		else TO_CHAR(MONTH("UpdateDate"))
         		end
      			|| case LENGTH(EXTRACT(DAY FROM "UpdateDate"))
          		when 1 then '0' || TO_CHAR(EXTRACT(DAY FROM "UpdateDate"))
          		else TO_CHAR(EXTRACT(DAY FROM "UpdateDate"))
        		end  AS "UPDATEDATE"
				FROM OCRD
				WHERE "CardType" = 'C'
;

CREATE VIEW "SBODEMOUS"."SBO_CUSTOMER_TEXT" AS
SELECT     OCRD."CardCode" as "CARDCODE", OCRD."CardName" as "CARDNAME"
				FROM         "OCRD"
				WHERE "CardType" = 'C'
;

CREATE VIEW "SBODEMOUS"."SBO_FI_GL_01" AS
SELECT 
				DISTINCT
				left(J."Account",10) as "GL_ACCOUNT",
				left(IFNULL(A."AccntntCod",'DEFT_ACCT'),10)  as "SBO_ALTACT",
				(SELECT SUM(J2."Debit") as "DEBIT" from "SBODEMOUS"."JDT1" as J2 where (J2."FinncPriod"=J."FinncPriod") and J2."Account"=J."Account")  as "DEBIT", 
				(SELECT SUM(J2."Credit") from "SBODEMOUS"."JDT1" as J2 where (J2."FinncPriod"=J."FinncPriod") and J2."Account"=J."Account")  as "CREDIT", 		
				(SELECT SUM(J2."Debit"-J2."Credit") from "SBODEMOUS"."JDT1" as J2 where (J2."FinncPriod"<=J."FinncPriod") and J2."Account"=J."Account") as "BALANCE",		
				'0' || TO_CHAR(MONTH(J."RefDate")) || TO_CHAR(YEAR(J."RefDate")) as "FISCPER",
				CASE (SELECT Top 1 C."MainCurncy" from "SBODEMOUS"."OADM" as C) 		
          			WHEN '€' THEN 'EUR'	
					WHEN 'Eur' THEN 'EUR'
					WHEN '$' THEN 'USD'
          			ELSE (SELECT Top 1 C."MainCurncy" from "SBODEMOUS"."OADM" as C)
      			END		
	 			AS "CURRENCY",
				'10' AS "CURTYPE"		
				FROM "SBODEMOUS"."JDT1" as J 
				INNER JOIN "SBODEMOUS"."OACT" as A ON J."Account"=A."AcctCode"
;

CREATE VIEW "SBODEMOUS"."SBO_FI_GL_02" AS
SELECT
			J."TransId" as "AC_DOC_NO",
			J."Line_ID" as "ITEM_NUM",
			left(J."Account",10) as "GL_ACCOUNT", 
			left(IFNULL(A."AccntntCod",'DEFT_ACCT'),10)  as "SBO_ALTACT", 
			J."Debit" as "DEBIT_LC", 		
			J."Credit" as "CREDIT_LC", 		
			CASE (SELECT Top 1 C."MainCurncy" from "SBODEMOUS"."OADM" as C) 		
	          		WHEN '€' THEN 'EUR'	
					WHEN 'Eur' THEN 'EUR'
					WHEN '$' THEN 'USD'
	          		ELSE (SELECT Top 1 C."MainCurncy" from "SBODEMOUS"."OADM" as C)
			      	END  AS "LOC_CURRCY",	
			J."SYSCred" as "SBOCRD_SC",
			J."SYSDeb" as "SBODBT_SC",
			CASE (SELECT Top 1 C."SysCurrncy" from "SBODEMOUS"."OADM" as C) 		
 	      		WHEN '€' THEN 'EUR'	
				WHEN 'Eur' THEN 'EUR'
				WHEN '$' THEN 'USD'
          		ELSE (SELECT Top 1 C."MainCurncy" from "SBODEMOUS"."OADM" as C)
		      	END  AS "SBOSYS_CUR",	
			J."FCDebit" as "DEBIT_DC",
			J."FCCredit" as "CREDIT_DC",
			CASE 	J."FCCurrency"
          		WHEN '€' THEN 'EUR'	
				WHEN 'Eur' THEN 'EUR'
				WHEN '$' THEN 'USD'
          		ELSE J."FCCurrency"
      		END  AS "DOC_CURRCY",	
			(SELECT SUM(J2."Debit"-J2."Credit") from "SBODEMOUS"."JDT1" as J2 where (TO_INT(J2."TransId")+TO_INT(J2."Line_ID"))<=(TO_INT(J."TransId")+TO_INT(J."Line_ID")) and J2."Account"=J."Account") as "BALANCE",	
			TO_CHAR(YEAR(J."DueDate"))		
	       		|| case LENGTH(MONTH(J."DueDate"))	
          			when 1 then '0' || TO_CHAR(MONTH(J."DueDate"))
          			else TO_CHAR(MONTH(J."DueDate"))
        		 end	
    	  		|| case LENGTH(TO_CHAR(EXTRACT(DAY FROM J."DueDate")))	
          			when 1 then '0' || TO_CHAR(EXTRACT(DAY FROM J."DueDate"))
          			else TO_CHAR(EXTRACT(DAY FROM J."DueDate"))
        		end  	
			as "NETDUEDATE",	
			J."ContraAct" AS 	"REF_DOC_AA",
			TO_INT(J."TransType") as "SBOTRN_TYP",
			TO_CHAR(YEAR(J."RefDate"))		
       		|| case LENGTH(MONTH(J."RefDate"))
          			when 1 then '0' || TO_CHAR(MONTH(J."RefDate"))
          			else TO_CHAR(MONTH(J."RefDate"))
        		 end	
      		|| case LENGTH(TO_CHAR(EXTRACT(DAY FROM J."RefDate")))	
          			when 1 then '0' || TO_CHAR(EXTRACT(DAY FROM J."RefDate"))
          			else TO_CHAR(EXTRACT(DAY FROM J."RefDate"))
       		end  	
			as "PSTNG_DATE",	
			J."Ref1" AS "REF_KEY1",
			J."Ref2" AS "REF_KEY2",
			J."CreatedBy" AS "REF_KEY3",
			J."BaseRef" AS "REF_DOC_NO",
			J."Project" AS "OPP_REF",
			J."TransCode" AS "SBOTRN_COD",
			J."ProfitCode" AS "SBOPFT_COD",
			TO_CHAR(YEAR(J."TaxDate"))		
       		|| case LENGTH(MONTH(J."TaxDate"))
          			when 1 then '0' || TO_CHAR(MONTH(J."TaxDate"))
          			else TO_CHAR(MONTH(J."TaxDate"))
        		 end	
      		|| case LENGTH(TO_CHAR(EXTRACT(DAY FROM J."TaxDate")))
          			when 1 then '0' || TO_CHAR(EXTRACT(DAY FROM J."TaxDate"))
          			else TO_CHAR(EXTRACT(DAY FROM J."TaxDate"))
        		end  	
			as "SBOTX_DATE",
			J."BatchNum" AS "BATCH",
			J."VatGroup" AS "SBOVAT_GRP",
			J."BaseSum" AS "ID_BASE",
			J."VatRate" AS "ID_TXRATE",
			J."Indicator" AS "BBP_FLAG",
			J."AdjTran" AS "SBOADJ_IND",		/* Adj Transaction  Indicators */
			J."RevSource" AS "SBOREV_IND", 	 /* Reverse Sources Indicators */
			CASE (SELECT Top 1 C."MainCurncy" from "SBODEMOUS"."OADM" as C) 		
        		WHEN '€' THEN 'EUR'	
				WHEN 'Eur' THEN 'EUR'
				WHEN '$' THEN 'USD'
       		ELSE (SELECT Top 1 C."MainCurncy" from "SBODEMOUS"."OADM" as C)
      		END		
	 		AS "CURRENCY"
			FROM "SBODEMOUS"."JDT1" AS J 
			INNER JOIN	"SBODEMOUS"."OACT" AS A ON J."Account"=A."AcctCode"
;

CREATE VIEW "SBODEMOUS"."SBO_FI_PC_01" AS
SELECT TO_CHAR(P."PrcCode") as "PROFIT_CTR",
	 			TO_CHAR(P."OcrCode") as "SBOPFT_COD",
	 			P."Direct"  as "CRM_DIRECT",
	 			J."TransId" as "AC_DOC_NO",
	 			left(J."Account", 10) as "GL_ACCOUNT",
				TO_CHAR(YEAR(J."RefDate"))		
       				|| case LENGTH(MONTH(J."RefDate"))	
          			when 1 then '0' || TO_CHAR(MONTH(J."RefDate"))
          			else TO_CHAR(MONTH(J."RefDate"))
        		 end	
      				|| case LENGTH(TO_CHAR(EXTRACT(DAY FROM J."RefDate")))
          			when 1 then '0' || TO_CHAR(EXTRACT(DAY FROM J."RefDate"))
          			else TO_CHAR(EXTRACT(DAY FROM J."RefDate"))
        		end  	
				as "CALDAY",
				A."ActType" as "ACCT_TYPE",
				J."Debit" * (P."PrcAmount"/P."OcrTotal") as "DEBIT",
				J."Credit" * (P."PrcAmount"/P."OcrTotal") as "CREDIT",
				CASE A."ActCurr" 		
          			WHEN '€' THEN 'EUR'	
					WHEN '##' THEN 'EUR'
					WHEN '$' THEN 'USD'
          			ELSE A."ActCurr" 	
      			END		
				AS "CURRENCY"	
				FROM (OCR1 as P  INNER JOIN JDT1 as J  ON P."OcrCode"=J."ProfitCode")   
				INNER JOIN OACT as A ON A."AcctCode"=J."Account"
;

CREATE VIEW "SBODEMOUS"."SBO_MATERIAL_ATTR" AS
SELECT "ItemCode" AS "ITEMCODE", 
      			TO_CHAR(YEAR("CreateDate"))
       				|| case LENGTH(MONTH("CreateDate"))
          		when 1 then '0' || TO_CHAR(month("CreateDate"))
          		else TO_CHAR(month("CreateDate"))
         		end
      				|| case LENGTH(EXTRACT(DAY FROM "CreateDate"))
         		when 1 then '0' || TO_CHAR(EXTRACT(DAY FROM "CreateDate"))
          		else TO_CHAR(EXTRACT(DAY FROM "CreateDate"))
        		end  AS CREATEDATE,
      			TO_CHAR(YEAR("UpdateDate"))
       				|| case LENGTH(MONTH("UpdateDate"))
          		when 1 then '0' || TO_CHAR(month("UpdateDate"))
          		else TO_CHAR(month("UpdateDate"))
         		end
      			|| case LENGTH(EXTRACT(DAY FROM "UpdateDate"))
          		when 1 then '0' || TO_CHAR(EXTRACT(DAY FROM "UpdateDate"))
          		else TO_CHAR(EXTRACT(DAY FROM "UpdateDate"))
        		end  AS "UPDATEDATE"
				FROM OITM
;

CREATE VIEW "SBODEMOUS"."SBO_MATERIAL_TEXT" AS
SELECT "ItemCode" AS "ITEMCODE", "ItemName" AS "ITEMNAME", 
      			TO_CHAR(YEAR("UpdateDate"))
       			|| case  LENGTH(MONTH("UpdateDate"))
          			when 1 then '0' || TO_CHAR(month("UpdateDate"))
          			else TO_CHAR(month("UpdateDate"))
         			end
      			|| case LENGTH(EXTRACT(DAY FROM "UpdateDate"))
          			when 1 then '0' || TO_CHAR(EXTRACT(DAY FROM "UpdateDate"))
          			else TO_CHAR(EXTRACT(DAY FROM "UpdateDate"))
        		end  AS "UPDATEDATE", 
      			TO_CHAR(YEAR("CreateDate"))
       			|| case LENGTH(MONTH("CreateDate"))
          			when 1 then '0' || TO_CHAR(month("CreateDate"))
          			else TO_CHAR(month("CreateDate"))
         			end
      			|| case LENGTH(EXTRACT(DAY FROM "CreateDate"))
          			when 1 then '0' || TO_CHAR(EXTRACT(DAY FROM "CreateDate"))
          			else TO_CHAR(EXTRACT(DAY FROM "CreateDate"))
        			end  AS "CREATEDATE"
				FROM OITM
;

CREATE VIEW "SBODEMOUS"."SBO_PROFIT_COD_ATTR" AS
SELECT TO_CHAR(P."OcrCode") AS "SBOPFT_COD"
				FROM OOCR AS P
;

CREATE VIEW "SBODEMOUS"."SBO_PROFIT_COD_TXT" AS
SELECT TO_CHAR(P."OcrCode") AS "SBOPFT_COD", 
				left(P."OcrName",20) AS "TXTSH"
				FROM OOCR AS P
;

CREATE VIEW "SBODEMOUS"."SBO_PROFIT_CTR_ATTR" AS
SELECT TO_CHAR(P."PrcCode") AS "PROFIT_CTR", 
				left(P."GrpCode",20) AS "SORT_COD",
				CASE (SELECT Top 1 C."MainCurncy" from "SBODEMOUS"."OADM" as C) 	
          			WHEN '€' THEN 'EUR'	
					WHEN 'Eur' THEN 'EUR'
          			ELSE  (SELECT Top 1 C."MainCurncy" from "SBODEMOUS"."OADM" as C) 	
      			END		
				AS "OBJ_CURR"
				FROM "SBODEMOUS"."OPRC" AS P
;

CREATE VIEW "SBODEMOUS"."SBO_PROFIT_CTR_TXT" AS
SELECT TO_CHAR(P."PrcCode") AS "PROFIT_CTR", 
				left(P."PrcName",20) AS "TXTSH", 
				left(P."PrcName",40) AS "TXTMD"
				FROM OPRC AS P
;

CREATE VIEW "SBODEMOUS"."SBO_PUR_GR_GRET" AS
((SELECT TO_CHAR(PDN1."DocEntry") as "DOCENTRY", 
				PDN1."LineNum" as "LINENUM",
      			' ' as "RETURNID", 
      			PDN1."ItemCode" as "ITEMCODE", 
      			TO_CHAR(OPDN."CardCode") as "CARDCODE", 
      			TO_CHAR(YEAR(OPOR."DocDate")) 
       			|| case LENGTH(MONTH(OPOR."DocDate"))
          			when 1 then '0' || TO_CHAR(MONTH(OPOR."DocDate"))
          			else TO_CHAR(MONTH(OPOR."DocDate"))
         			end
      			|| case LENGTH(EXTRACT(DAY FROM OPOR."DocDate"))
          			when 1 then '0' || TO_CHAR(EXTRACT(DAY FROM OPOR."DocDate"))
          			else TO_CHAR(EXTRACT(DAY FROM OPOR."DocDate"))
        			end  AS PODOCDATE,
      			TO_CHAR(YEAR(OPDN."DocDate"))
       			|| case LENGTH(MONTH(OPDN."DocDate"))
         			 when 1 then '0' || TO_CHAR(MONTH(OPDN."DocDate"))
          			else TO_CHAR(MONTH(OPDN."DocDate"))
         			end
      			|| case LENGTH(EXTRACT(DAY FROM OPDN."DocDate"))
          			when 1 then '0' || TO_CHAR(EXTRACT(DAY FROM OPDN."DocDate"))
          			else TO_CHAR(EXTRACT(DAY FROM OPDN."DocDate"))
        			end  AS "DOCDATE",
       			TO_CHAR(YEAR(OPDN."CreateDate"))
       			|| case LENGTH(MONTH(OPDN."CreateDate"))
          			when 1 then '0' || TO_CHAR(MONTH(OPDN."CreateDate"))
          			else TO_CHAR(MONTH(OPDN."CreateDate"))
         		end
      			|| case LENGTH(EXTRACT(DAY FROM OPDN."CreateDate"))
          			when 1 then '0' || TO_CHAR(EXTRACT(DAY FROM OPDN."CreateDate"))
         			 else TO_CHAR(EXTRACT(DAY FROM OPDN."CreateDate"))
        			end  AS "CREATEDATE",
       			TO_CHAR(YEAR(OPDN."UpdateDate"))
       			|| case LENGTH(MONTH(OPDN."UpdateDate"))
         			when 1 then '0' || TO_CHAR(MONTH(OPDN."UpdateDate"))
          			else TO_CHAR(MONTH(OPDN."UpdateDate"))
         			end
      			|| case LENGTH(EXTRACT(DAY FROM OPDN."UpdateDate"))
          			when 1 then '0' || TO_CHAR(EXTRACT(DAY FROM OPDN."UpdateDate"))
         			else TO_CHAR(EXTRACT(DAY FROM OPDN."UpdateDate"))
        			end  AS "UPDATEDATE",
      				ROUND(PDN1."LineTotal" * (1 - OPDN."DiscPrcnt" / 100) + PDN1."VatSum", 2) AS "GRVALUE", 
     			 CASE PDN1."UseBaseUn" 
          			WHEN 'Y' THEN PDN1."Quantity" 
          			WHEN 'N' THEN PDN1."Quantity" * OITM."NumInBuy" 
      			END  AS "GRQUANTITY", 
      			CASE (SELECT Top 1 "MainCurncy" FROM "SBODEMOUS"."OADM")
          			WHEN 'Eur' THEN 'EUR'
          			WHEN '$' THEN 'USD'    
          			WHEN '€' THEN 'EUR'
          			ELSE (SELECT Top 1 "MainCurncy" FROM "SBODEMOUS"."OADM") 
      			END AS "CURRENCY", 
      			CASE OITM."BuyUnitMsr"
          			WHEN 'Centimeter' THEN 'CM'
          			WHEN 'CM' THEN 'CM'
          			WHEN 'Gram' THEN 'G'
          			WHEN 'G' THEN 'G'
          			WHEN 'Kilogram' THEN 'KG'
          			WHEN 'KG' THEN 'KG'
          			WHEN 'Liter' THEN 'L'
          			WHEN 'L' THEN 'L'
          			WHEN 'Meter' THEN 'M'
          			WHEN 'M' THEN 'M'
          			WHEN 'Tonnes' THEN 'TO'
          			WHEN 'Ton' THEN 'TO'
          			WHEN 'TO' THEN 'TO'
          			ELSE 'PC'
      			End AS "BASEUNIT"
			FROM "SBODEMOUS"."PDN1" 
			INNER JOIN "SBODEMOUS"."OPDN" ON PDN1."DocEntry" = OPDN."DocEntry" 
			INNER JOIN "SBODEMOUS"."OITM" ON PDN1."ItemCode" = OITM."ItemCode" 
			INNER JOIN "SBODEMOUS"."OPOR" ON PDN1."BaseEntry" = OPOR."DocEntry"
			WHERE OPDN."DocType" = 'I' and PDN1."BaseType" = '22') UNION (SELECT TO_CHAR(RPD1."DocEntry") as "DOCENTRY", RPD1."LineNum" as "LINENUM",
      		'X' as "RETURNID", 
      		RPD1."ItemCode" as "ITEMCODE", TO_CHAR(ORPD."CardCode") as "CARDCODE", 
       		TO_CHAR(YEAR(OPOR."DocDate"))
       		|| case LENGTH(MONTH(OPOR."DocDate"))
          		when 1 then '0' || TO_CHAR(MONTH(OPOR."DocDate"))
          		else TO_CHAR(MONTH(OPOR."DocDate"))
         		end
      		|| case LENGTH(EXTRACT(DAY FROM OPOR."DocDate"))
          		when 1 then '0' || TO_CHAR(EXTRACT(DAY FROM OPOR."DocDate"))
          		else TO_CHAR(EXTRACT(DAY FROM OPOR."DocDate"))
        		end  AS "PODOCDATE",
     		 TO_CHAR(YEAR(ORPD."DocDate"))
       		|| case LENGTH(MONTH(ORPD."DocDate"))
          		when 1 then '0' || TO_CHAR(MONTH(ORPD."DocDate"))
          		else TO_CHAR(MONTH(ORPD."DocDate"))
         		end
      		|| case LENGTH(EXTRACT(DAY FROM ORPD."DocDate"))
          		when 1 then '0' || TO_CHAR(EXTRACT(DAY FROM ORPD."DocDate"))
          		else TO_CHAR(EXTRACT(DAY FROM ORPD."DocDate"))
        		end  AS "DOCDATE",
       		TO_CHAR(YEAR(ORPD."CreateDate"))
       		|| case LENGTH(MONTH(ORPD."CreateDate"))
         		when 1 then '0' || TO_CHAR(MONTH(ORPD."CreateDate"))
          		else TO_CHAR(MONTH(ORPD."CreateDate"))
         		end
      		|| case LENGTH(EXTRACT(DAY FROM ORPD."CreateDate"))
          		when 1 then '0' || TO_CHAR(EXTRACT(DAY FROM ORPD."CreateDate"))
          		else TO_CHAR(EXTRACT(DAY FROM ORPD."CreateDate"))
        		end  AS "CREATEDATE",
       		TO_CHAR(YEAR(ORPD."UpdateDate"))
       		|| case LENGTH(MONTH(ORPD."UpdateDate"))
          		when 1 then '0' || TO_CHAR(MONTH(ORPD."UpdateDate"))
          		else TO_CHAR(MONTH(ORPD."UpdateDate"))
         		end
      		|| case LENGTH(EXTRACT(DAY FROM ORPD."UpdateDate"))
          		when 1 then '0' || TO_CHAR(EXTRACT(DAY FROM ORPD."UpdateDate"))
          		else TO_CHAR(EXTRACT(DAY FROM ORPD."UpdateDate"))
        		end  AS "UPDATEDATE",
      		ROUND(RPD1."LineTotal" * (1 - ORPD."DiscPrcnt" / 100) + RPD1."VatSum", 2) AS "GRVALUE", 
      		CASE RPD1."UseBaseUn" 
          		WHEN 'Y' THEN RPD1."Quantity" 
          		WHEN 'N' THEN RPD1."Quantity" * OITM."NumInBuy" 
     	 	END  AS "GRQUANTITY", 
      		CASE (SELECT Top 1 "MainCurncy" FROM "SBODEMOUS"."OADM")
          		WHEN 'Eur' THEN 'EUR'
          		WHEN '$' THEN 'USD'    
          		WHEN '€' THEN 'EUR'
          		ELSE (SELECT Top 1 "MainCurncy" FROM "SBODEMOUS"."OADM") 
      		END AS "CURRENCY", 
      		CASE OITM."BuyUnitMsr"
          		WHEN 'Centimeter' THEN 'CM'
          			WHEN 'CM' THEN 'CM'
          		WHEN 'Gram' THEN 'G'
          		WHEN 'G' THEN 'G'
          		WHEN 'Kilogram' THEN 'KG'
          		WHEN 'KG' THEN 'KG'
          		WHEN 'Liter' THEN 'L'
          		WHEN 'L' THEN 'L'
          		WHEN 'Meter' THEN 'M'
          		WHEN 'M' THEN 'M'
         		WHEN 'Tonnes' THEN 'TO'
          		WHEN 'Ton' THEN 'TO'
          		WHEN 'TO' THEN 'TO'
          		ELSE 'PC'
      		End AS "BASEUNIT"
		FROM "SBODEMOUS"."RPD1" 
		INNER JOIN "SBODEMOUS"."ORPD" ON RPD1."DocEntry" = ORPD."DocEntry" 
		INNER JOIN "SBODEMOUS"."OITM" ON RPD1."ItemCode" = OITM."ItemCode" 
		INNER JOIN "SBODEMOUS"."PDN1" ON RPD1."BaseEntry" = PDN1."DocEntry" AND RPD1."BaseLine" = PDN1."LineNum" 
		INNER JOIN "SBODEMOUS"."OPOR" ON PDN1."BaseEntry" = OPOR."DocEntry"
	WHERE ORPD."DocType" = 'I' and RPD1."BaseType" = '20'))
;

CREATE VIEW "SBODEMOUS"."SBO_PUR_IV_CM" AS
((((SELECT TO_CHAR(PCH1."DocEntry") as "DOCENTRY", PCH1."LineNum" as "LINENUM",
      ' ' as "RETURNID", PCH1."ItemCode" as "ITEMCODE", TO_CHAR(OPCH."CardCode") as "CARDCODE",
      'X' as "GRID",
      TO_CHAR(YEAR(OPOR."DocDate"))
       || case LENGTH(MONTH(OPOR."DocDate"))
          when 1 then '0' || TO_CHAR(MONTH(OPOR."DocDate"))
          else TO_CHAR(MONTH(OPOR."DocDate"))
         end
      || case LENGTH(EXTRACT(DAY FROM OPOR."DocDate"))
          when 1 then '0' || TO_CHAR(EXTRACT(DAY FROM OPOR."DocDate"))
          else TO_CHAR(EXTRACT(DAY FROM OPOR."DocDate"))
        end  AS "PODOCDATE",
      TO_CHAR(YEAR(OPCH."DocDate"))
       || case LENGTH(MONTH(OPCH."DocDate"))
          when 1 then '0' || TO_CHAR(MONTH(OPCH."DocDate"))
          else TO_CHAR(MONTH(OPCH."DocDate"))
         end
      || case LENGTH(EXTRACT(DAY FROM OPCH."DocDate"))
          when 1 then '0' || TO_CHAR(EXTRACT(DAY FROM OPCH."DocDate"))
          else TO_CHAR(EXTRACT(DAY FROM OPCH."DocDate"))
        end  AS "DOCDATE",
      TO_CHAR(YEAR(OPCH."CreateDate"))
       || case LENGTH(MONTH(OPCH."CreateDate"))
          when 1 then '0' || TO_CHAR(MONTH(OPCH."CreateDate"))
          else TO_CHAR(MONTH(OPCH."CreateDate"))
         end
      || case LENGTH(EXTRACT(DAY FROM OPCH."CreateDate"))
          when 1 then '0' || TO_CHAR(EXTRACT(DAY FROM OPCH."CreateDate"))
          else TO_CHAR(EXTRACT(DAY FROM OPCH."CreateDate"))
        end  AS "CREATEDATE",
      TO_CHAR(YEAR(OPCH."UpdateDate"))
       || case LENGTH(MONTH(OPCH."UpdateDate"))
          when 1 then '0' || TO_CHAR(MONTH(OPCH."UpdateDate"))
          else TO_CHAR(MONTH(OPCH."UpdateDate"))
         end
      || case LENGTH(EXTRACT(DAY FROM OPCH."UpdateDate"))
          when 1 then '0' || TO_CHAR(EXTRACT(DAY FROM OPCH."UpdateDate"))
          else TO_CHAR(EXTRACT(DAY FROM OPCH."UpdateDate"))
        end  AS "UPDATEDATE",
      ROUND(PCH1."LineTotal" * (1 - OPCH."DiscPrcnt" / 100) 
            + PCH1."VatSum", 2) AS "IVVALUE", 
      CASE PCH1."UseBaseUn" 
          WHEN 'Y' THEN PCH1."Quantity" 
          WHEN 'N' THEN PCH1."Quantity" * OITM."NumInBuy" 
      END  AS "IVQUANTITY", 
      CASE (SELECT Top 1 "MainCurncy" FROM  "SBODEMOUS"."OADM")
          WHEN 'Eur' THEN 'EUR'
          WHEN '$' THEN 'USD'    
          WHEN '€' THEN 'EUR'
          ELSE (SELECT Top 1 "MainCurncy" FROM  "SBODEMOUS"."OADM") 
      END AS "CURRENCY", 
      CASE OITM."BuyUnitMsr"
          WHEN 'Centimeter' THEN 'CM'
          WHEN 'CM' THEN 'CM'
          WHEN 'Gram' THEN 'G'
          WHEN 'G' THEN 'G'
          WHEN 'Kilogram' THEN 'KG'
          WHEN 'KG' THEN 'KG'
          WHEN 'Liter' THEN 'L'
          WHEN 'L' THEN 'L'
          WHEN 'Meter' THEN 'M'
          WHEN 'M' THEN 'M'
          WHEN 'Tonnes' THEN 'TO'
          WHEN 'Ton' THEN 'TO'
          WHEN 'TO' THEN 'TO'
          ELSE 'PC'
      End AS "BASEUNIT"
FROM  "SBODEMOUS"."PCH1" INNER JOIN
       "SBODEMOUS"."OPCH" ON PCH1."DocEntry" = OPCH."DocEntry" INNER JOIN
       "SBODEMOUS"."OITM" ON PCH1."ItemCode" = OITM."ItemCode" INNER JOIN
       "SBODEMOUS"."OPOR" ON PCH1."BaseEntry" = OPOR."DocEntry" 
WHERE OPCH."DocType" = 'I' and PCH1."BaseType" = '22') UNION (SELECT TO_CHAR(PCH1."DocEntry") as "DOCENTRY", PCH1."LineNum" as "LINENUM",
      ' ' as "RETURNID", PCH1."ItemCode" as "ITEMCODE", TO_CHAR(OPCH."CardCode") as "CARDCODE",
      ' ' as "GRID",
      TO_CHAR(YEAR(OPOR."DocDate"))
       || case LENGTH(MONTH(OPOR."DocDate"))
          when 1 then '0' || TO_CHAR(MONTH(OPOR."DocDate"))
          else TO_CHAR(MONTH(OPOR."DocDate"))
         end
      || case LENGTH(EXTRACT(DAY FROM OPOR."DocDate"))
          when 1 then '0' || TO_CHAR(EXTRACT(DAY FROM OPOR."DocDate"))
          else TO_CHAR(EXTRACT(DAY FROM OPOR."DocDate"))
        end  AS "PODOCDATE",
      TO_CHAR(YEAR(OPCH."DocDate"))
       || case LENGTH(MONTH(OPCH."DocDate"))
          when 1 then '0' || TO_CHAR(MONTH(OPCH."DocDate"))
          else TO_CHAR(MONTH(OPCH."DocDate"))
         end
      || case LENGTH(EXTRACT(DAY FROM OPCH."DocDate"))
          when 1 then '0' || TO_CHAR(EXTRACT(DAY FROM OPCH."DocDate"))
          else TO_CHAR(EXTRACT(DAY FROM OPCH."DocDate"))
        end  AS "DOCDATE",
      TO_CHAR(YEAR(OPCH."CreateDate"))
       || case LENGTH(MONTH(OPCH."CreateDate"))
          when 1 then '0' || TO_CHAR(MONTH(OPCH."CreateDate"))
          else TO_CHAR(MONTH(OPCH."CreateDate"))
         end
      || case LENGTH(EXTRACT(DAY FROM OPCH."CreateDate"))
          when 1 then '0' || TO_CHAR(EXTRACT(DAY FROM OPCH."CreateDate"))
          else TO_CHAR(EXTRACT(DAY FROM OPCH."CreateDate"))
        end  AS "CREATEDATE",
      TO_CHAR(YEAR(OPCH."UpdateDate"))
       || case LENGTH(MONTH(OPCH."UpdateDate"))
          when 1 then '0' || TO_CHAR(MONTH(OPCH."UpdateDate"))
          else TO_CHAR(MONTH(OPCH."UpdateDate"))
         end
      || case LENGTH(EXTRACT(DAY FROM OPCH."UpdateDate"))
          when 1 then '0' || TO_CHAR(EXTRACT(DAY FROM OPCH."UpdateDate"))
          else TO_CHAR(EXTRACT(DAY FROM OPCH."UpdateDate"))
        end  AS "UPDATEDATE",
      ROUND(PCH1."LineTotal" * (1 - OPCH."DiscPrcnt" / 100) 
            + PCH1."VatSum", 2) AS "IVVALUE", 
      CASE PCH1."UseBaseUn" 
