          else TO_CHAR(MONTH(ORPC."DocDate"))
         end
      || case LENGTH(EXTRACT(DAY FROM ORPC."DocDate"))
          when 1 then '0' || TO_CHAR(EXTRACT(DAY FROM ORPC."DocDate"))
          else TO_CHAR(EXTRACT(DAY FROM ORPC."DocDate"))
        end  AS "DOCDATE",
      TO_CHAR(YEAR(ORPC."CreateDate"))
