        end  AS "UPDATEDATE",
      ROUND(RPC1."LineTotal" * (1 - ORPC."DiscPrcnt" / 100) 
            + RPC1."VatSum", 2) AS "IVVALUE", 
      CASE RPC1."UseBaseUn" 
          WHEN 'Y' THEN RPC1."Quantity" 
