CREATE VIEW "SBODEMOUS"."SBO_PUR_PO" AS
SELECT TO_CHAR(POR1."DocEntry") as "DOCENTRY", POR1."LineNum" as "LINENUM",
      OPOR."CANCELED" as "CANCELLED", POR1."ItemCode" as "ITEMCODE", TO_CHAR(OPOR."CardCode") as "CARDCODE", 
      TO_CHAR(YEAR(OPOR."DocDate"))
       || case LENGTH(MONTH(OPOR."DocDate"))
          when 1 then '0' || TO_CHAR(MONTH(OPOR."DocDate"))
          else TO_CHAR(MONTH(OPOR."DocDate"))
         end
      || case LENGTH(EXTRACT(DAY FROM OPOR."DocDate"))
          when 1 then '0' || TO_CHAR(EXTRACT(DAY FROM OPOR."DocDate"))
          else TO_CHAR(EXTRACT(DAY FROM OPOR."DocDate"))
        end  AS "DOCDATE",
      TO_CHAR(YEAR(OPOR."UpdateDate"))
       || case LENGTH(MONTH(OPOR."UpdateDate"))
          when 1 then '0' || TO_CHAR(MONTH(OPOR."UpdateDate"))
          else TO_CHAR(MONTH(OPOR."UpdateDate"))
         end
      || case LENGTH(EXTRACT(DAY FROM OPOR."UpdateDate"))
          when 1 then '0' || TO_CHAR(EXTRACT(DAY FROM OPOR."UpdateDate"))
          else TO_CHAR(EXTRACT(DAY FROM OPOR."UpdateDate"))
        end  AS "UPDATEDATE",
      ROUND(POR1."LineTotal" * (1 - OPOR."DiscPrcnt" / 100) 
            + POR1."VatSum", 2) AS "ORDERVALUE", 
      CASE POR1."UseBaseUn" 
          WHEN 'Y' THEN POR1."Quantity" 
          WHEN 'N' THEN POR1."Quantity" * OITM."NumInBuy" 
      END  AS "ORDERQUANTITY", 
      CASE (SELECT Top 1 "MainCurncy" FROM "SBODEMOUS"."OADM")
          WHEN 'Eur' THEN 'EUR'
          WHEN '$' THEN 'USD'    
          WHEN '€' THEN 'EUR'
          ELSE (SELECT Top 1 "MainCurncy" FROM "SBODEMOUS"."OADM") 
      END AS "CURRENCY", 
      CASE OITM."BuyUnitMsr"
          WHEN 'Centimeter' THEN 'CM'
          WHEN 'CM' THEN 'CM'
          WHEN 'Gram' THEN 'G'
          WHEN 'G' THEN 'G'
          WHEN 'Kilogram' THEN 'KG'
          WHEN 'KG' THEN 'KG'
          WHEN 'Liter' THEN 'L'
          WHEN 'L' THEN 'L'
          WHEN 'Meter' THEN 'M'
          WHEN 'M' THEN 'M'
          WHEN 'Tonnes' THEN 'TO'
          WHEN 'Ton' THEN 'TO'
          WHEN 'TO' THEN 'TO'
          ELSE 'PC'
      End AS "BASEUNIT"
FROM "SBODEMOUS"."POR1" INNER JOIN
      "SBODEMOUS"."OPOR" ON POR1."DocEntry" = OPOR."DocEntry" INNER JOIN
      "SBODEMOUS"."OITM" ON POR1."ItemCode" = OITM."ItemCode"
WHERE OPOR."DocType" = 'I'
;

CREATE VIEW "SBODEMOUS"."SBO_SALES_DE" AS
SELECT     ODLN."DocNum" AS "DOCNUM", DLN1."LineNum" AS "LINENUM", ODLN."CANCELED" as "CANCELLED", DLN1."ItemCode" as "ITEMCODE", 
             ODLN."CardCode" as "CARDCODE",
              TO_CHAR(ODLN."SlpCode") AS "SALESPERSON",
             
              TO_CHAR(YEAR(ODLN."DocDate")) || CASE LENGTH(MONTH(ODLN."DocDate")) 
              WHEN 1 THEN '0' || TO_CHAR(MONTH(ODLN."DocDate")) ELSE TO_CHAR(MONTH(ODLN."DocDate")) 
              END 
              || CASE LENGTH(EXTRACT(DAY FROM ODLN."DocDate")) WHEN 1 THEN '0'
               || TO_CHAR(EXTRACT(DAY FROM ODLN."DocDate")) 
              ELSE TO_CHAR(EXTRACT(DAY FROM ODLN."DocDate")) END AS "DOCDATE",

           TO_CHAR(YEAR(ODLN."UpdateDate"))
       || case LENGTH(MONTH(ODLN."UpdateDate"))
          when 1 then '0' || TO_CHAR(MONTH(ODLN."UpdateDate"))
          else TO_CHAR(MONTH(ODLN."UpdateDate"))
         end
      || case LENGTH(EXTRACT(DAY FROM ODLN."UpdateDate"))
          when 1 then '0' || TO_CHAR(EXTRACT(DAY FROM ODLN."UpdateDate"))
          else TO_CHAR(EXTRACT(DAY FROM ODLN."UpdateDate"))
        end  AS "UPDATEDATE",

          CASE DLN1."UseBaseUn" 
          WHEN 'Y' THEN DLN1."Quantity" 
          WHEN 'N' THEN DLN1."Quantity" * OITM."NumInSale"
          END  AS "DELIVERYQUANTITY",


               CASE OITM."SalUnitMsr"
          WHEN 'Centimeter' THEN 'CM'
          WHEN 'CM' THEN 'CM'
          WHEN 'Gram' THEN 'G'
          WHEN 'G' THEN 'G'
          WHEN 'Kilogram' THEN 'KG'
          WHEN 'KG' THEN 'KG'
          WHEN 'Liter' THEN 'L'
          WHEN 'L' THEN 'L'
          WHEN 'Meter' THEN 'M'
          WHEN 'M' THEN 'M'
          WHEN 'Tonnes' THEN 'TO'
          WHEN 'Ton' THEN 'TO'
          WHEN 'TO' THEN 'TO'
          ELSE 'PC'
      End AS "BASEUNIT"

FROM         "SBODEMOUS"."DLN1" INNER JOIN
                      "SBODEMOUS"."ODLN" ON DLN1."DocEntry" = ODLN."DocEntry" INNER JOIN
                      "SBODEMOUS"."OITM" ON DLN1."ItemCode" = OITM."ItemCode"
;

CREATE VIEW "SBODEMOUS"."SBO_SALES_IN" AS
SELECT     OINV."DocNum" AS "DOCNUM", INV1."LineNum" AS "LINENUM", OINV."CANCELED" as "CANCELLED",  INV1."ItemCode" as "ITEMCODE", 
             OINV."CardCode" as "CARDCODE",
              TO_CHAR(OINV."SlpCode") AS "SALESPERSON",

              TO_CHAR(year(OINV."DocDate")) || CASE LENGTH(MONTH(OINV."DocDate"))
              WHEN 1 THEN '0' || TO_CHAR(MONTH(OINV."DocDate")) ELSE TO_CHAR(MONTH(OINV."DocDate")) 
              END 
              || CASE LENGTH(EXTRACT(DAY FROM OINV."DocDate")) WHEN 1 THEN '0' 
              || TO_CHAR(EXTRACT(DAY FROM OINV."DocDate")) 
              ELSE TO_CHAR(EXTRACT(DAY FROM OINV."DocDate")) END AS "DOCDATE",  

            TO_CHAR(year(OINV."UpdateDate"))
       || case LENGTH(MONTH(OINV."UpdateDate"))
          when 1 then '0' || TO_CHAR(MONTH(OINV."UpdateDate"))
          else TO_CHAR(MONTH(OINV."UpdateDate"))
         end
      || case LENGTH(EXTRACT(DAY FROM OINV."UpdateDate"))
          when 1 then '0' || TO_CHAR(EXTRACT(DAY FROM OINV."UpdateDate"))
          else TO_CHAR(EXTRACT(DAY FROM OINV."UpdateDate"))
        end  AS "UPDATEDATE", 
      
      ROUND ( INV1."LineTotal" * (1- OINV."DiscPrcnt"/ 100), 2) AS "ORDERVALUE", 
       
         
          CASE INV1."UseBaseUn" 
          WHEN 'Y' THEN INV1."Quantity" 
          WHEN 'N' THEN INV1."Quantity" * OITM."NumInSale"
          END  AS "ORDERQUANTITY", 
         

      INV1."GrossBuyPr" AS "GROSSBYEPR", 
      CASE (SELECT Top 1 "MainCurncy" FROM "SBODEMOUS"."OADM")
          WHEN 'Eur' THEN 'EUR'
          WHEN '$' THEN 'USD'    
          WHEN '€' THEN 'EUR'
          ELSE (SELECT Top 1 "MainCurncy" FROM "SBODEMOUS"."OADM") 
      END AS "CURRENCY", 
 
     CASE OITM."SalUnitMsr"
          WHEN 'Centimeter' THEN 'CM'
          WHEN 'CM' THEN 'CM'
          WHEN 'Gram' THEN 'G'
          WHEN 'G' THEN 'G'
          WHEN 'Kilogram' THEN 'KG'
          WHEN 'KG' THEN 'KG'
          WHEN 'Liter' THEN 'L'
          WHEN 'L' THEN 'L'
          WHEN 'Meter' THEN 'M'
          WHEN 'M' THEN 'M'
          WHEN 'Tonnes' THEN 'TO'
          WHEN 'Ton' THEN 'TO'
          WHEN 'TO' THEN 'TO'
          ELSE 'PC'
      End AS "BASEUNIT"


FROM         "SBODEMOUS"."INV1" INNER JOIN
                      "SBODEMOUS"."OINV" ON INV1."DocEntry" = OINV."DocEntry" INNER JOIN
                      "SBODEMOUS"."OITM" ON INV1."ItemCode" = OITM."ItemCode"
;

CREATE VIEW "SBODEMOUS"."SBO_SALES_SO" AS
SELECT     ORDR."DocNum" as "DOCNUM", RDR1."LineNum" as "LINENUM", ORDR."CANCELED" AS "CANCELLED", RDR1."ItemCode" as "ITEMCODE", 
             ORDR."CardCode" as "CARDCODE",
             TO_int(ORDR."SlpCode") AS "SALESPERSON",

	TO_CHAR(YEAR(ORDR."DocDate")) || CASE LENGTH(MONTH(ORDR."DocDate")) 
              WHEN 1 THEN '0' || TO_CHAR(MONTH(ORDR."DocDate")) ELSE TO_CHAR(MONTH(ORDR."DocDate")) 
              END 
              || CASE LENGTH(EXTRACT(DAY FROM ORDR."DocDate")) WHEN 1 THEN '0' || TO_CHAR(EXTRACT(DAY FROM ORDR."DocDate"))
              ELSE TO_CHAR(EXTRACT(DAY FROM ORDR."DocDate")) END AS "DOCDATE",  

           TO_CHAR(YEAR(ORDR."UpdateDate"))
       || case LENGTH(MONTH(ORDR."UpdateDate"))
          when 1 then '0' || TO_CHAR(MONTH(ORDR."UpdateDate"))
          else TO_CHAR(MONTH(ORDR."UpdateDate"))
         end
      || case LENGTH(EXTRACT(DAY FROM ORDR."UpdateDate"))
          when 1 then '0' || TO_CHAR(EXTRACT(DAY FROM ORDR."UpdateDate"))
          else TO_CHAR(EXTRACT(DAY FROM ORDR."UpdateDate"))
        end  AS "UPDATEDATE",
        
           ROUND ( RDR1."LineTotal" * (1- ORDR."DiscPrcnt"/ 100), 2) AS "ORDERVALUE", 
          
           CASE RDR1."UseBaseUn" 
          WHEN 'Y' THEN RDR1."Quantity" 
          WHEN 'N' THEN RDR1."Quantity" * OITM."NumInSale"
          END  AS "ORDERQUANTITY", 
         
          CASE RDR1."UseBaseUn" 
          WHEN 'Y' THEN RDR1."OpenQty"
          WHEN 'N' THEN RDR1."OpenQty" * OITM."NumInSale"
          END  AS "OPENORDQUANT", 

      RDR1."GrossBuyPr" AS "GROSSBYEPR", 
      CASE (SELECT Top 1 "MainCurncy" FROM "SBODEMOUS"."OADM")
          WHEN 'Eur' THEN 'EUR'
          WHEN '$' THEN 'USD'    
          WHEN '€' THEN 'EUR'
          ELSE (SELECT Top 1 "MainCurncy" FROM "SBODEMOUS"."OADM") 
      END AS "CURRENCY", 
 
     CASE OITM."SalUnitMsr"
          WHEN 'Centimeter' THEN 'CM'
          WHEN 'CM' THEN 'CM'
          WHEN 'Gram' THEN 'G'
          WHEN 'G' THEN 'G'
          WHEN 'Kilogram' THEN 'KG'
          WHEN 'KG' THEN 'KG'
          WHEN 'Liter' THEN 'L'
          WHEN 'L' THEN 'L'
          WHEN 'Meter' THEN 'M'
          WHEN 'M' THEN 'M'
          WHEN 'Tonnes' THEN 'TO'
          WHEN 'Ton' THEN 'TO'
          WHEN 'TO' THEN 'TO'
          ELSE 'PC'
      End AS "BASEUNIT"

FROM         "SBODEMOUS"."RDR1" INNER JOIN
                      "SBODEMOUS"."ORDR" ON RDR1."DocEntry" = ORDR."DocEntry" INNER JOIN
                      "SBODEMOUS"."OITM" ON RDR1."ItemCode" = OITM."ItemCode"
;

CREATE VIEW "SBODEMOUS"."SBO_VENDOR_ATTR" AS
SELECT TO_CHAR("CardCode") AS "CARDCODE", "City" AS "CITY", "Country" AS "COUNTRY", "Fax" AS "FAX", 
      "CardName" AS "CARDNAME", "Phone1" AS "PHONE1", "ZipCode" AS "ZIPCODE", 
      "Address" AS "ADDRESS",
      TO_CHAR(YEAR("CreateDate"))
       || case LENGTH(MONTH("CreateDate"))
          when 1 then '0' || TO_CHAR(MONTH("CreateDate"))
          else TO_CHAR(MONTH("CreateDate"))
         end
      || case LENGTH(EXTRACT(DAY FROM "CreateDate"))
          when 1 then '0' || TO_CHAR(EXTRACT(DAY FROM "CreateDate"))
          else TO_CHAR(EXTRACT(DAY FROM "CreateDate"))
        end  AS "CREATEDATE",
      TO_CHAR(YEAR("UpdateDate"))
       || case LENGTH(MONTH("UpdateDate"))
          when 1 then '0' || TO_CHAR(MONTH("UpdateDate"))
          else TO_CHAR(MONTH("UpdateDate"))
         end
      || case LENGTH(EXTRACT(DAY FROM "UpdateDate"))
          when 1 then '0' || TO_CHAR(EXTRACT(DAY FROM "UpdateDate"))
          else TO_CHAR(EXTRACT(DAY FROM "UpdateDate"))
        end  AS "UPDATEDATE"
FROM OCRD
WHERE "CardType" = 'S'
;

CREATE VIEW "SBODEMOUS"."SBO_VENDOR_TEXT" AS
SELECT  TO_CHAR("CardCode") AS "CARDCODE", "CardName" AS "CARDNAME",
      TO_CHAR(YEAR("UpdateDate"))
       || case LENGTH(MONTH("UpdateDate"))
          when 1 then '0' || TO_CHAR(MONTH("UpdateDate"))
          else TO_CHAR(MONTH("UpdateDate"))
         end
      || case LENGTH(EXTRACT(DAY FROM "UpdateDate"))
          when 1 then '0' || TO_CHAR(EXTRACT(DAY FROM "UpdateDate"))
          else TO_CHAR(EXTRACT(DAY FROM "UpdateDate"))
        end  AS "UPDATEDATE", 
     TO_CHAR(YEAR("CreateDate"))
       || case LENGTH(MONTH("CreateDate"))
          when 1 then '0' || TO_CHAR(MONTH("CreateDate"))
          else TO_CHAR(MONTH("CreateDate"))
         end
      || case LENGTH(EXTRACT(DAY FROM "CreateDate"))
          when 1 then '0' || TO_CHAR(EXTRACT(DAY FROM "CreateDate"))
          else TO_CHAR(EXTRACT(DAY FROM "CreateDate"))
        end  AS "CREATEDATE"
FROM OCRD
WHERE "CardType" = 'S'
;

