CREATE VIEW "SBODEMOUS"."SRI1" AS
SELECT "ItemCode","SysSerial",(select count(1) from "SBODEMOUS".SRI1_LINK b where b."ItemCode" = a."ItemCode" and b."SysSerial" = a."SysSerial" and b."LogEntry" < a."LogEntry" ) as "LineNum","BaseType","BaseEntry","BaseNum","BaseLinNum","DocDate","WhsCode","CardCode","CardName","Direction","CreateDate","ItemName","DataSource","UserSign","BsDocType","BsDocEntry", "BsDocLine" from "SBODEMOUS".SRI1_LINK a
;

CREATE VIEW "SBODEMOUS"."SRI1_LINK" AS
SELECT b."LogEntry" as "LogEntry", b."ItemCode" as "ItemCode", c."SysNumber"		as "SysSerial", b."ApplyType"		as "BaseType", b."ApplyEntry"	as "BaseEntry", b."AppDocNum"		as "BaseNum", b."ApplyLine"		as "BaseLinNum", b."DocDate"		as "DocDate", b."LocCode"		as "WhsCode", b."CardCode"		as "CardCode", b."CardName"		as "CardName", ( CASE WHEN a."Quantity" > 0 THEN 0  ELSE 1 END ) as "Direction", b."CreateDate"	as "CreateDate", b."ItemName"		as "ItemName", 'N'				as "DataSource", NULL			as "UserSign", b."BaseType"		as "BsDocType", b."BaseEntry"		as "BsDocEntry", b."BaseLine"		as "BsDocLine" FROM		"SBODEMOUS".ITL1 a INNER JOIN	"SBODEMOUS".OITL b ON a."LogEntry" = b."LogEntry" INNER JOIN	OSRN c ON a."ItemCode" = c."ItemCode" and a."SysNumber" = c."SysNumber"
;

CREATE VIEW "SBODEMOUS"."VBIN" AS
SELECT "T0"."AbsEntry" , "T0"."BinCode" , "T0"."WhsCode" , "T0"."SysBin" , "T0"."SL1Abs" , "T0"."SL1Code" , "T0"."SL2Abs" , "T0"."SL2Code" , "T0"."SL3Abs" , "T0"."SL3Code" , "T0"."SL4Abs" , "T0"."SL4Code" , "T0"."Attr1Abs" , "T0"."Attr1Val" , "T0"."Attr2Abs" , "T0"."Attr2Val" , "T0"."Attr3Abs" , "T0"."Attr3Val" , "T0"."Attr4Abs" , "T0"."Attr4Val" , "T0"."Attr5Abs" , "T0"."Attr5Val" , "T0"."Attr6Abs" , "T0"."Attr6Val" , "T0"."Attr7Abs" , "T0"."Attr7Val" , "T0"."Attr8Abs" , "T0"."Attr8Val" , "T0"."Attr9Abs" , "T0"."Attr9Val" , "T0"."Attr10Abs" , "T0"."Attr10Val" , "T0"."Disabled" , "T0"."Descr" , "T0"."BarCode" , "T0"."AltSortCod" , "T0"."ItmRtrictT" , "T0"."SpcItmCode" , "T0"."SpcItmGrpC" , "T0"."SngBatch" , "T0"."RtrictType" , "T0"."RtrictResn" , "T0"."RtrictDate" , "T0"."DataSource" , "T0"."UserSign" , "T0"."Transfered" , "T0"."Instance" , "T0"."LogInstanc" , "T0"."CreateDate" , "T0"."UserSign2" , "T0"."UpdateDate" , "T0"."Deleted" , "T0"."MinLevel" , "T0"."MaxLevel" , "T0"."ReceiveBin" , "T0"."NoAutoAllc" , "T0"."MaxWeight1" , "T0"."Wght1Unit" , "T0"."MaxWeight2" , "T0"."Wght2Unit" , "T0"."UoMRtrict" , "T0"."SpcUoMCode" , "T0"."SpcUGPCode" , "T0"."SngUoMCode" , "T1"."BinAbs" , "T1"."ItemQty" , "T1"."ItemsNum" , "T1"."SnBNum" , "T1"."ItemWeight" FROM "OBIN" T0 
		LEFT OUTER JOIN "VBIN_Qty" T1 ON T1."BinAbs" = T0."AbsEntry"
;

CREATE VIEW "SBODEMOUS"."VBIN_Qty" AS
SELECT T0."BinAbs", SUM(T0."OnHandQty") AS "ItemQty", COUNT(DISTINCT T0."ItemCode") AS "ItemsNum", 
		COUNT(DISTINCT T0."ItemCode") AS "SnBNum", COUNT(DISTINCT T0."ItemCode") AS "ItemWeight" 
		FROM "OIBQ" T0 
		WHERE T0."OnHandQty" <> (0 ) 
		GROUP BY T0."BinAbs"
;

CREATE VIEW "SBODEMOUS"."VTSP" AS
SELECT T0."AbsEntry", T0."TransCode", T0."TransName", T0."TransID", IFNULL(T1."LineNum", 0) as "LineNum", T2."ModeName" as "TransMode", T3."TypeName" as "VehicleTyp", T1."VehicleNo"
		FROM "OTSP" T0 
		LEFT OUTER JOIN "TSP1" T1 ON T1."AbsEntry" = T0."AbsEntry"
		LEFT OUTER JOIN "OETM" t2 ON T2."ModeCode" = t1."TransMode"
		LEFT OUTER JOIN "OEVT" t3 ON T3."TypeCode" = t1."VehicleTyp"
;

CREATE VIEW "SBODEMOUS"."ixvITL_LastWhs" AS
SELECT		T0."ItemCode", lastLogEntry."SysNumber", T0."LocCode" AS "WhsCode" FROM		"SBODEMOUS".OITL  T0 INNER JOIN	(SELECT	MAX("LogEntry") AS "LogEntry", "ItemCode", "SysNumber" FROM "SBODEMOUS".ITL1 GROUP BY "ItemCode", "SysNumber") AS lastLogEntry ON lastLogEntry."LogEntry" = T0."LogEntry" AND T0."ItemCode" = lastLogEntry."ItemCode"
;

CREATE VIEW "SBODEMOUS"."ixvITL_Min" AS
SELECT MIN("LogEntry") AS "LogEntry", "ItemCode", "SysNumber" FROM ITL1 GROUP BY "ItemCode", "SysNumber"
;


